(window.GIM_TS=window.GIM_TS||{})["Ketubot.3"]={"from":72,"a":[["\u0003הני מילי\u0004 \u0005[דברים אלה],\u0006 שאין כפרה על ידי ממון, אמורים דווקא \u0003היכא\u0004 \u0005[היכן,\u0006 כאשר\u0005]\u0006 \u0003הרגו דרך עלייה,\u0004 שזו היא עבירה \u0003שלא ניתנה\u0004 בה \u0003שגגתו לכפרה,\u0004 שאם הרג נפש בשוגג בדרך זו, אינו נענש בגלות ואין לו כפרה מפורשת אחרת, \u0003אבל\u0004 אם \u0003הרגו\u0004 במזיד \u0003דרך ירידה,\u0004 ש\u0003ניתנה שגגתו,\u0004 אילו הרג בשוגג, \u0003לכפרה\u0004 על ידי גלות, \u0003אימא נישקול ממונא מיניה וניפטריה\u0004 \u0005[אמור\u0006 ש\u0005ניטול ממון ממנו ונפטרנו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הפסוק \"כל חרם\" שאין לו תקנה בכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003מדתנא דבי\u0004 \u0005[מ\u0006מה \u0005ששנה\u0006 החכם מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה נפקא\u0004 \u0005[\u0006הוא \u0005יוצא,\u0006 נלמד\u0005],\u0006 \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה:\u0004 נאמרו בכתוב אחד (ויקרא כד, כא) דין \u0003מכה אדם ו\u0004דין \u0003מכה בהמה,\u0004 ועל ידי כך הם מושווים זה לזה בכתוב,","ומכאן נלמד: \u0003מה מכה בהמה לא חלקת בו בין\u0004 שמכה אותה ב\u0003שוגג ל\u0004בין ב\u0003מזיד, בין\u0004 ש\u0003מתכוין\u0004 להכאה \u0003ל\u0004בין \u0003שאין מתכוין, בין דרך ירידה לדרך עלייה,\u0004 שבכל אלה לא באת \u0003לפוטרו ממון אלא לחייבו ממון,\u0004 שהוא חייב תשלומים בכל מקרה, \u0003אף מכה אדם\u0004 והרגו \u0003לא תחלוק בו בין שוגג למזיד, בין מתכוין לשאין מתכוין, בין דרך ירידה לדרך עליה\u0004 שלא \u0003לחייבו ממון אלא\u0004 תמיד \u0003לפוטרו ממון.\u0004 לומר שכל מי שהרג אדם בכל דרך ובכל אופן פטור מן התשלומים, ואם כן אין צורך בכתוב נוסף לזה!","\u0003אלא אמר רמי בר חמא: איצטריך\u0004 \u0005[צריך]\u0006 הכתוב של \"כל חרם\" (ויקרא כז, כט) לענין אחר, והוא: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאין אדם משלם ומומת, זה רק \u0003היכא\u0004 \u0005[היכן,\u0006 כאשר\u0005]\u0006 \u0003סימא את עינו והרגו בה,\u0004 שעל ידי הפגיעה בעינו גרם גם למותו, \u0003אבל היכא\u0004 \u0005[היכן]\u0006 ש\u0003סימא את עינו והרגו בדבר אחר — אימא נישקול ממונא מיניה\u0004 \u0005[אמור\u0006 ש\u0005נקח ממון ממנו]\u0006 עבור הנזק שגרם לו באותה שעה שסימא את עינו, על כן השמיע לנו הכתוב שלא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: הא נמי\u0004 \u0005[\u0006דבר \u0005זה,\u0006 שסימא את עינו והרגו בה, \u0005גם כן]\u0006 \u0003מאידך תנא דבי\u0004 \u0005[מ\u0006דבר \u0005אחר ששנה בבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה נפקא\u0004 \u0005[\u0006הוא \u0005יוצא,\u0006 נלמד\u0005]\u0006 \u0003דתנא דבי\u0004 \u0005[ששנה בבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה,\u0004 נאמר: \u0003\"עין תחת עין\"\u0004 (שמות כא, כד), הרי זה למעט: שמשלם דמי עין בלבד, \u0003ולא עין ונפש תחת עין.\u0004 הרי אנו למדים שבזמן שהוא נותן נפש על שהרג בהוצאת עין — אינו נותן כסף תמורת העין.","\u0003אלא אמר רב אשי:\u0004 יש לחזור מפירושים אלה, ולומר כי \u0003איצטריך\u0004 \u0005[צריך]\u0006 בכל זאת לכתוב \"כל חרם\". כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל וחידוש הוא שחידשה תורה בקנס,\u0004 שדיני קנסות שבתורה אינם תלויים בערך הממשי של הנזק אלא גזירת הכתוב היא, ולכך הייתי אומר שהתורה מחמירה בו \u0003אף על גב דמיקטיל\u0004 \u0005[אף על פי\u0006 שזה \u0005שנהרג]\u0006 \u0003משלם\u0004 גם קנס, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו תשלומי קנס איננו משלם. ושואלים: \u0003ול\u0004שיטת \u0003רבה\u0004 ש\u0003אמר חידוש הוא שחידשה תורה בקנס,\u0004 ובאמת \u0003אף על גב דמיקטיל\u0004 \u0005[אף על פי שנהרג]\u0006 הוא \u0003משלם,\u0004 אם כן \u0003האי\u0004 \u0005[\u0006הפסוק \u0005הזה],\u0006 \u0003\"כל חרם\", מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומסבירים: חייבים לומר ש\u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 רבה בפירוש המקרא הזה \u0003כ\u0004שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 של \u0003ר' חנניא בן עקביא,\u0004 שאומר שכתוב זה בא ללמדנו שהאומר \"ערכו של יוצא ליהרג עלי\" לא אמר כלום.","\u0003נערה שנתארסה ו\u0004אחר כך \u0003נתגרשה,\u0004 ונאנסה — \u0003ר' יוסי הגלילי אומר: אין לה קנס. ר' עקיבא אומר: יש לה קנס,\u0004 אבל כיון שהיא כבר היתה ארוסה ונתגרשה אינה עוד ברשות אביה, \u0003וקנסה\u0004 הוא \u0003לעצמה\u0004 ולא לאב.","\u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי הגלילי?\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004כי ימצא איש נערה בתולה \u0003אשר לא ארשה\"\u0004 (דברים כב, כח), ומכאן נלמד: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אורסה — אין לה קנס.\u0004 ושואלים: \u0003ור' עקיבא,\u0004 כיצד הוא מפרש? ומסבירים: אם היא נערה \u0003אשר לא ארשה\u0004 — יש לנהוג בה כדברי הכתוב וקנסה \u0003לאביה, הא\u0004 \u0005[הרי]\u0006 אם \u0003אורסה\u0004 — הרי קנסה \u0003לעצמה.\u0004","ומקשים על שיטת ר' עקיבא: \u0003אלא מעתה,\u0004 לפי אותה דרך־פירוש, מה שאנחנו מדייקים מן הכתוב שעונש קנס הוא באונס \u0003נערה ולא\u0004 באונס \u0003בוגרת,\u0004 האם \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 נאמר שיש לה קנס וקנסה יהיה \u0003לעצמה?\u0004 וכן את הדיוק \u0003\"בתולה\" ולא בעולה, הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שיש לה קנס וקנסה הוא \u0003לעצמה?\u0004 חידוש כזה הלא לא מצאנו בשום מקום! \u0003אלא\u0004 ודאי שמפרשים שהאונס בוגרת או בעולה \u0003לגמרי\u0004 פטר אותו הכתוב מקנס, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לגבי \"לא אורשה\" צריך לפרש כי \u0003לגמרי\u0004 פטר הכתוב אם אורסה!","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ר' עקיבא: האי\u0004 \u0005[\u0006הכתוב \u0005הזה]\u0006 \u0003\"לא ארשה\" מיבעי ליה לכדתניא\u0004 \u0005[צריך אותו לכפי ששנינו\u0006 בברייתא אחרת\u0005]:\u0006 מה שנאמר \u0003\"אשר לא ארשה\"\u0004 — משמעות הפסוק היא \u0003פרט לנערה שנתארסה ונתגרשה, שאין לה קנס,\u0004 אלו \u0003דברי ר' יוסי הגלילי. ר' עקיבא אומר: יש לה קנס, וקנסה לאביה\u0004 (והיא שיטה שונה משיטתו במשנתנו). \u0003ו\u0004לכאורה אין צורך בכתוב מפורש כזה כי \u0003הדין נותן,\u0004 כלומר, סברה היא שיהא כן, \u0003הואיל ו\u0004בכלל \u0003אביה זכאי בכסף קידושיה,\u0004 שאם מקדש אותה לפני שבגרה, כסף הקידושין שייך לאב, \u0003ו\u0004כן \u0003אביה זכאי בכסף קנסה.\u0004 ומכאן נדון: \u0003מה כסף קידושיה אף על פי שנתארסה ונתגרשה,\u0004 אם מתקדשת שוב בעודה נערה, כסף הקידושין הוא \u0003לאביה — אף כסף קנסה, אף על פי שנתארסה ונתגרשה\u0004 הוא \u0003לאביה.\u0004","\u0003אם כן\u0004 שהלכה זו נלמדת מן הסברה, \u0003מה תלמוד לומר \"אשר לא ארשה\"\u0004 — הרי זה מקרא \u0003מופנה\u0004 (מיותר) שאינו נחוץ לעניינו, והוא בא \u0003להקיש לו ולדון הימנו\u0004 (ממנו) \u0003גזירה שוה: נאמר כאן\u0004 בדין אנוסה \u0003\"אשר לא ארשה\", ונאמר להלן\u0004 בדין מפותה \u0003\"\u0004וכי יפתה איש בתולה \u0003אשר לא ארשה\"\u0004 (שמות כב, טו), \u0003מה כאן\u0004 מפרש הכתוב באונס שמשלם \u0003חמישים\u0004 כסף (\"ונתן האיש השוכב עמה לאבי הנערה חמישים כסף\". דברים כב, כט) — \u0003אף להלן,\u0004 במפתה, צריך לשלם \u0003חמישים\u0004 כסף למרות שאין הסכום מפורש בכתוב, ומגזירה שווה זו נלמד גם להיפך: \u0003ומה להלן,\u0004 במפותה, הוא משלם \u0003שקלים,\u0004 ככתוב \"כסף ישקול\" (שמות כב טז), — \u0003אף כאן\u0004 באונס, חמישים אלה שנאמרו — \u0003שקלים\u0004 הם. ומצאנו איפוא שר' עקיבא דורש הלכה אחרת מהמילים \"אשר לא אורשה\".","ושואלים: \u0003ור' עקיבא, מאי חזית\u0004 \u0005[מה ראית]\u0006 שאת המילים \u0003\"אשר לא ארשה\"\u0004 יש ללמוד \u0003לגזירה שוה, ו\u0004המלה \u0003\"בתולה\"\u0004 הכתובה כאן באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003בעולה\u0004 שאין לה קנס,"],["\u0003אימא\u0004 \u0005[אמור]\u0006 להיפך: \u0003\"בתולה\"\u0004 שנאמרה גם באנוסה וגם במפותה — \u0003לגזירה שוה\u0004 היא, ואין ללמוד מכאן להוציא בעולה, \u0003ו\u0004מה שנאמר \u0003\"אשר לא אורסה\"\u0004 (שמות כב, טו), יתפרש כר' יוסי הגלילי — \u0003פרט לנערה שנתארסה ונתגרשה!\u0004","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ש\u0003\"אשר לא אורסה\"\u0004 הוא שבא \u0003לגזירה שוה\u0004 ולא למעט נתארסה ונתגרשה, \u0003שהרי\u0004 גם בזו שאורסה \u0003אני קורא בה \"נערה בתולה\",\u0004 כלומר, עדיין מתקיים בה חלקו האחר של הכתוב. ומקשים: \u0003אדרבה\u0004 (להיפך), נלמד ש\u0003\"בתולה\" לגזירה שוה\u0004 היא באה, \u0003שהרי אני קורא בה,\u0004 גם בבתולה וגם בבעולה, \u0003\"אשר לא אורסה\"!\u0004 ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר שהפסוק \"בתולה\" בא להוציא את הבעולה, ו\"אשר לא אורסה\" לא בא למעט נתארסה ונתגרשה, אלא לגזירה שווה. שהרי \u0003הא\u0004 \u0005[זו\u0006 שנבעלה\u0005],\u0006 \u0003אישתני\u0004 \u0005[נשתנה]\u0006 \u0003גופה, והא\u0004 \u0005[וזו\u0006 שנתארסה ונתגרשה\u0005],\u0006 \u0003לא אישתני\u0004 \u0005[השתנה]\u0006 \u0003גופה,\u0004 וגם דינה לגבי קנס לא השתנה.","ושואלים: \u0003ור' יוסי הגלילי האי סברא מנא ליה\u0004 \u0005[סברה זו\u0006 לגבי סכום הקנס במפתה, ומאיזה כסף משלם האונס, \u0005מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה מדתניא\u0004 \u0005[יוצא לו\u0006 הדבר \u0005ממה ששנינו\u0006 בברייתא אחרת\u0005];\u0006 נאמר במפתה: \u0003\"כסף ישקל כמהר הבתולת\"\u0004 (שמות כב, טז), לומר \u0003שיהא זה\u0004 סכום הקנס \u0003כמוהר הבתולות,\u0004 כלומר, חמישים כסף, \u0003ומוהר הבתולות\u0004 יהיה \u0003כזה,\u0004 שיהיה אף הוא בשקלים.","ומעירים: \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' עקיבא\u0004 על דברי \u0003ר' עקיבא.\u0004 שהרי בברייתא שנינו שר' עקיבא אומר שקנסה של זו שנתארסה ונתגרשה גם הוא לאביה, ולא כבמשנתנו שהוא לעצמה! ומשיבים: זו היא מחלוקת של \u0003תרי תנאי\u0004 \u0005[שני תנאים]\u0006 \u0003ואליבא\u0004 \u0005[ועל פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' עקיבא.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003ר' עקיבא דמתניתין\u0004 \u0005[של משנתנו],\u0006 לדעתו \u0003לא אתיא\u0004 \u0005[באה]\u0006 \u0003גזירה שוה\u0004 של \"אורסה\" \"אורסה\" \u0003ומפקא ליה לקרא מפשטיה\u0004 \u0005[ומוציאה אותו את הכתוב מפשוטו]\u0006 \u0003לגמרי,\u0004 שהרי לשיטתו מה שנאמר \"לא אורסה\" מלמדנו שיש הבדל בדין בין מאורסה ושאינה מאורסה, שזו שנתארסה קנסה לעצמה. \u0003אלא לר' עקיבא\u0004 של ה\u0003ברייתא,\u0004 הרי \u0003אתיא\u0004 \u0005[באה]\u0006 \u0003גזירה שוה ומפקא מפשטיה\u0004 \u0005[ומוציאה\u0006 את הכתוב \u0005מפשוטו]\u0006 \u0003לגמרי,\u0004 שהרי לשיטה זו אין הבדל כלל בין ארוסה ושאינה ארוסה, בניגוד לנשמע מפשוטו של מקרא, המדגיש \"אשר לא אורשה\".","\u0003אמר רב נחמן בר יצחק: קרי ביה\u0004 \u0005[קרא בו]\u0006 בכתוב זה \u0003\"אשר לא ארוסה\",\u0004 שאין פירוש הביטוי לא אורסה בעבר, אלא אשר לא ארוסה בהווה, שכעת היא פנויה ואינה ארוסה. ותוהים: לשם כך אין צורך בכתוב מיוחד, הלא \u0003ארוסה בת סקילה היא,\u0004 כלומר, ראויה היא להיסקל, כמפורש בפסוקים אחרים ובודאי אין לה קנס! ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל וחידוש הוא שחידשה תורה בקנס,\u0004 ולכן, כיון שחידוש הוא \u0003אף על גב דמיקטיל\u0004 \u0005[אף על פי\u0006 שהוא \u0005נהרג]\u0006 משום שבועל נערה ארוסה — הוא גם \u0003משלם\u0004 קנס, על כן השמיע לנו שאין זה כך.","ושואלים: \u0003ול\u0004דעת \u0003רבה\u0004 ש\u0003אמר:\u0004 אכן, \u0003חידוש הוא שחידשה תורה בקנס, אף על גב דמיקטיל\u0004 \u0005[אף על פי ש\u0006הוא \u0005נהרג]\u0006 \u0003משלם\u0004 קנס, אם כן, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 לשיטתו ולאיזה צורך יש בפסוק זה? ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 רבה \u0003כר' עקיבא דמתניתין\u0004 \u0005[של משנתנו]\u0006 שלשיטתו \"לא אורסה\" מתפרש כפשוטו ואינו ענין לקנס במקום חיוב מיתה.","\u0003תנו רבנן:\u0004 \u0005[שנו חכמים]:\u0006 אנוסה, \u0003קנסה למי — לאביה. ויש אומרים: לעצמה.\u0004 ותוהים: \u0003לעצמה אמאי\u0004 \u0005[מדוע],\u0006 הלא מפורש במקרא שמשלם לאביה! \u0003אמר רב חסדא: הכא\u0004 \u0005[כאן]\u0006 \u0003בנערה שנתארסה ונתגרשה עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003וקמיפלגי בפלוגתא\u0004 \u0005[וחולקים\u0006 חכמים אלה שבברייתא \u0005במחלוקת]\u0006 של \u0003ר' עקיבא דמתניתין\u0004 \u0005[של משנתנו]\u0006 \u0003ור' עקיבא\u0004 של ה\u0003ברייתא\u0004 למי הקנס.","\u0003אמר אביי: בא עליה,\u0004 על נערה, באונס \u0003ומתה\u0004 לפני שנתחייב בדין — הרי הוא \u0003פטור\u0004 מקנס, \u0003שנאמר: \"ונתן\u0004 האיש השוכב עמה \u0003לאבי הנערה\"\u0004 (דברים כב, כט), ומלשון הכתוב משמע — \u0003ולא לאבי מתה.\u0004 ומעירים: \u0003מלתא דפשיטא ליה\u0004 \u0005[דבר\u0006 שהיה \u0005פשוט לו]\u0006 \u0003לאביי, מיבעיא ליה\u0004 \u0005[\u0006היה \u0005מסופק לו]\u0006 \u0003לרבא.\u0004","\u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבא:\u0004 האם \u0003יש בגר בקבר,\u0004 כלומר, נערה שנאנסה ולא עמד האונס בדין עד שמתה ועבר משך זמן כזה שאילו היתה חיה היתה כבר בוגרת (שקנסה לעצמה) ורק אז עמד בדין. והשאלה היא: האם כיון שהתחייב בדין בזמן שהיתה כבר צריכה להיות בוגרת אם היתה חיה, הרי הקנס ניתן לה, \u0003או אין בגר בקבר\u0004 ודינה כנערה וקנסה לאביה. וההבדל הנובע מכאן למעשה, אם \u0003יש בגר בקבר ו\u0004הקנס היה שייך משום כך לה — הרי של \u0003בנה הוי\u0004 \u0005[הוא],\u0006 שהרי הוא יורש את אמו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אין בגר בקבר, ו\u0004הקנס, כיון שבמותה היתה נערה, של \u0003אביה הוי\u0004 \u0005[הוא].\u0006"],["\u0003ומי מעברא\u0004 \u0005[והאם\u0006 קטנה שנבעלה \u0005מתעברת]?\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב ביבי קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן\u0004 ברייתא זו: \u0003שלש נשים משמשות במוך,\u0004 כלומר, מותר להן לשים מוך בצוואר הרחם כדי להימנע מהריון, \u0003אלו הן: קטנה, ו\u0004זו שהיא כבר \u0003מעוברת, ומניקה.\u0004 וטעמו של דבר: \u0003קטנה — שמא תתעבר ותמות, מעוברת — שמא\u0004 תתעבר שנית ו\u0003תעשה עוברה\u0004 הראשון \u0003סנדל,\u0004 כלומר, שימעך בגלל העובר השני עליו, \u0003מניקה — שמא\u0004 תתעבר וייפסק חלבה ו\u0003תגמול את בנה\u0004 מיניקה לפני הזמן ויסתכן.","\u0003ו\u0004אמרו שם: \u0003איזוהי קטנה\u0004 לענין זה — \u0003מבת אחת עשרה שנה ויום אחד עד שתים עשרה שנה ויום אחד, פחות מיכן\u0004 או \u0003יתר על כן — משמשת כדרכה והולכת,\u0004 אלו \u0003דברי ר' מאיר.\u0004 כלומר, שקטנה פחות מבת אחת עשרה איננה מתעברת כלל ואין לה סכנה. \u0003וחכמים אומרים: אחת זו ואחת זו\u0004 בכל המקרים \u0003משמשת כדרכה והולכת, ומן השמים ירחמו\u0004 שלא יקרה מכשול, \u0003משום שנאמר: \"שמר פתאים ה'\"\u0004 (תהלים קטז, ו). ומכאן שלא ייתכן שתתעבר ותלד כשהיא קטנה!","\u0003וכי תימא דאיעברא\u0004 \u0005[ואם תאמר שהתעברה]\u0006 \u0003כשהיא נערה\u0004 בת שתים עשרה \u0003ו\u0004גם \u0003אולידה\u0004 \u0005[ילדה]\u0006 \u0003כשהיא נערה\u0004 ומתה לפני שבגרה, אולם, \u0003ובשיתא ירחי מי קא ילדה\u0004 \u0005[ובשישה חדשים האם\u0006 יכולה \u0005ללדת]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: אין בין\u0004 זמן \u0003נערות ל\u0004זמן \u0003בגרות אלא ששה חדשים\u0004 והרי מתה לפני שבגרה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ותפרש את דברי שמואל: \u0003בציר\u0004 \u0005[פחות\u0006 מכאן\u0005]\u0006 משישה חדשים \u0003הוא דליכא\u0004 \u0005[שאין],\u0006 \u0003הא טפי\u0004 \u0005[אבל יותר]\u0006 — \u0003איכא\u0004 \u0005[יש],\u0006 שיש נערה המאחרת ליבגר והספיקה ללדת לפני בגרות — אולם דבר זה אי אפשר לומר, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"אלא\" קאמר\u0004 \u0005[אמר],\u0006 משמע שכוונתו רק לזמן זה דווקא ולא יותר מזה!","\u0003אלא,\u0004 יש לומר שלא היתה כוונת שאלת רבא האם היא בוגרת בקבר ובנה יורש אותה, אלא לעניין אחר; \u0003הכי קמיבעיא ליה\u0004 \u0005[כך הסתפק לו]:\u0006 האם \u0003יש בגר בקבר ופקע\u0004 \u0005[ופקעה]\u0006 תביעתו של ה\u0003אב,\u0004 וכיון שכך אין מי שיזכה, ואין האונס משלם, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אין בגר בקבר, ולא פקע\u0004 \u0005[פקעה]\u0006 זכות ה\u0003אב. מר בר רב אשי בעי לה הכי\u0004 \u0005[שאל\u0006 את השאלה הזו \u0005כך],\u0006 בצורה זו: האם \u0003מיתה עושה בגרות,\u0004 כלומר, האם דינה של מיתה עצמה כבגרות, שמפקיעה זכות האב, \u0003או אין\u0004 המיתה עצמה \u0003עושה בגרות?\u0004 ולשאלה זו לא נמצאה תשובה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה. ועל כל פנים רואים מכאן שמה שהיה ברור לאביי, שמיתה מפקיעה את חובת הקנס, היה בגדר ספק אצל רבא.","ועוד בענין דומה \u0003בעי מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מאביי: בא עליה,\u0004 על הנערה באונס, \u0003ונתארסה\u0004 לאחר מכן, \u0003מהו\u0004 הדין, האם הקנס לעצמה או לאביה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"ונתן לאבי הנערה אשר לא ארוסה\"?\u0004 הרי נאמר \"כי ימצא איש נערה... אשר לא ארשה\" (דברים כב, כח), משמע שלא היתה ארוסה בעבר, שיש הבדל בדין אם היתה מאורסת קודם שבא עליה, אבל אין הדבר תלוי אם נתארסה לאחר מכן. הקשה לו רבא: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 \u0003הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003בא עליה\u0004 על הנערה \u0003ונשאת\u0004 אחר כך, שהדין הוא שהקנס הוא \u0003לעצמה\u0004 ולא לאביה, ומדוע לא תאמר אף שם כמו כן: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"ונתן לאבי הנערה אשר לא נשואה\"?\u0004 והרי על אף שלא נאמר כך, אם נשאת אחר כך, זוכה היא בקנס!","ענה לו אביי: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 יש מקום לשנות מלשון הכתוב, כי \u0003הואיל ובגרות מוציאה מרשות אב, ונשואין מוציאין מרשות אב,\u0004 לפיכך יש לומר \u0003מה\u0004 ב\u0003בגרות\u0004 כש\u0003בא עליה\u0004 באונס בעודה נערה \u0003ובגרה\u0004 — קנסה הוא \u0003לעצמה, אף נישואין\u0004 אם \u0003בא עליה\u0004 באונס \u0003ונשאת\u0004 לאחר מכן — קנסה \u0003לעצמה. אלא אירוסין, מי קא מפקי מרשותא\u0004 \u0005[האם הם\u0006 \u0005מוציאים מרשות]\u0006 ה\u0003אב לגמרי? הא תנן\u0004 \u0005[הרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נערה המאורסה אביה ובעלה\u0004 יחד \u0003מפירין לה נדריה.\u0004 משמע שעל ידי האירוסין עדיין לא יצאה לגמרי מרשות האב, ואין ללמוד אירוסין מבגרות, ואם כן באירוסין אין מקום לשאלה.","\u0003המפתה נותן\u0004 לאבי המפותה \u0003שלשה דברים, והאונס\u0004 נותן לאבי האנוסה \u0003ארבעה.\u0004 ומפרטים: \u0003המפתה נותן בושת ופגם וקנס, ומוסיף עליו אונס שנותן את הצער.\u0004 ומלבד ענין זה \u0003מה\u0004 ההבדל \u0003בין\u0004 דין \u0003אונס למפתה: האונס נותן את הצער והמפתה אינו נותן את הצער,\u0004 כאמור, וכן \u0003האונס נותן\u0004 לאנוסה \u0003מיד, והמפתה\u0004 איננו נותן לה מיד אלא \u0003לכשיוציא,\u0004 כשלא ירצה לישא אותה, ישלם לה את מה שחייב לה: קנס, בושת ופגם. ועוד הבדל יש: \u0003האונס שותה בעציצו\u0004 (בכלי שלו, בכלי שבחר לשתות ממנו), כלומר, חייב לשאת את הנערה, \u0003והמפתה, אם רצה להוציא\u0004 (לא לכנוס) — \u0003מוציא.\u0004","ומפרטים, \u0003כיצד שותה בעציצו: אפילו היא\u0004 האנוסה \u0003חיגרת, אפילו היא סומא\u0004 (עיוורת), \u0003ואפילו היא מוכת שחין\u0004 — חייב לשאת אותה ואינו רשאי לגרשה. אולם אם \u0003נמצא בה דבר ערוה,\u0004 כגון שזנתה בזמן נישואיה \u0003או שאינה ראויה לבא בישראל,\u0004 כגון שהיא ממזרת — \u0003אינו רשאי לקיימה, שנאמר: \"ולו תהיה לאשה\"\u0004 (דברים כב, כט), ואנחנו מדייקים בלשון שתהא על כל פנים \u0003אשה הראויה לו\u0004 מצד הדין.","אמרנו שהאונס משלם בעד הצער. ושואלים: \u0003צער דמאי\u0004 \u0005[של מה]\u0006 בעד איזה צער הוא משלם? \u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל: צער שחבטה\u0004 והפילה \u0003על גבי קרקע\u0004 כשאנס אותה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: אלא מעתה,\u0004 אם \u0003חבטה על גבי שיראין\u0004 (משי), במקרה זה \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהוא \u0003פטור\u0004 לשלם בעד הצער? \u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר: כך\u0006 הוא \u0005גם כן]\u0006 — \u0003והתניא\u0004 \u0005[והרי\u0006 \u0005שנינו בברייתא\u0006\u0005],\u0006 \u0003ר' שמעון בן יהודה אומר משום ר' שמעון: אונס אינו משלם את הצער\u0004 וטעמו של דבר — \u0003מפני\u0004"],["\u0003שסופה להצטער תחת בעלה\u0004 בכגון אותו צער שמחמת הביאה. \u0003אמרו לו: אינו דומה נבעלת באונס לנבעלת ברצון.\u0004 משמע שהצער שבאונס הוא צער שנגרם ישירות מהביאה עצמה ולא הצער שבא מסיבה אחרת שבאותו מקרה! \u0003אלא אמר רב נחמן אמר רבה בר אבוה: צער של פיסוק הרגלים\u0004 בשעת ביאה. \u0003וכן הוא אומר: \"ותפשקי את רגליך לכל עובר\"\u0004 (יחזקאל טז, כה).","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שיש בזה צער, ומשלם על צער כזה — \u0003מפותה נמי\u0004 \u0005[גם כן]\u0006 צריך היה לשלם! \u0003אמר רב נחמן אמר רבה בר אבוה: משל\u0004 של זו ה\u0003מפותה למה הדבר דומה — לאדם שאמר לחבירו: קרע שיראין\u0004 (משי) \u0003שלי והפטר,\u0004 שאם עשה כדבריו, הוא פטור. ואף זו, כיון שנבעלה מרצונה, בודאי מוחלת לו ואיננו מתחייב על מה שציער אותה. על עצם ההשוואה ל\"קרע שיראין שלי\", תוהים: \u0003שלי?!\u0004 וכי הנזק רק שלה? הלא \u0003דאבוה נינהו\u0004 \u0005[של אביה הוא]\u0006 שהרי הקנס והתשלומים מגיעים לאביה, וכיצד יכולה היא למחול עליהם? \u0003אלא אמר רב נחמן אמר רבה בר אבוה:\u0004 יש לחזור מהתירוצים הקודמים ולומר כך: \u0003פקחות שבהן,\u0004 שבין הנשים, \u0003אומרות: מפותה אין לה צער\u0004 בשעת ביאה, שכיון שעושה מרצונה — אינה מצטערת בכך.","ושואלים: \u0003והא קא חזינן דאית לה\u0004 \u0005[והרי אנו רואים ש\u0006גם אשה הנבעלת ברצון וכגון זו הנישאת \u0005יש לה]\u0006 כאב בשעת ביאה ראשונה? \u0003אמר אביי: אמרה לי אם\u0004 (אומנתי) שהצער הזה אינו קשה כל כך, שהוא \u0003כמיא חמימי על רישיה דקרחא\u0004 \u0005[כמו מים חמים על ראשו של\u0006 איש \u0005קרח].\u0006 \u0003רבא אמר: אמרה לי בת רב חסדא\u0004 (אשתו): \u0003כי ריבדא דכוסילתא\u0004 \u0005[כמו דקירה של סכין הקזה].\u0006 \u0003רב פפא אמר: אמרה לי בת אבא סוראה\u0004 (אשתו): הכאב הוא \u0003כי נהמא אקושא בחינכי\u0004 \u0005[כמו לחם קשה בחניכיים],\u0006 שכאשר נבעלת האשה מרצונה הצער הוא מועט, ואינו צריך לשלם עליו.","שנינו במשנה ש\u0003האונס נותן מיד\u0004 ו\u0003המפתה לכשיוציא וכו'.\u0004 ותוהים: \u0003לכשיוציא?!\u0004 וכי \u0003אשתו היא?\u0004 הרי עדיין לא נשא אותה, ואם כן מדוע אומרים לכשיוציא? \u0003אמר אביי: אימא\u0004 \u0005[אמור,\u0006 הכוונה היא\u0005]\u0006 \u0003לכשלא יכנוס.\u0004 כלומר, אם רוצה לשאתה — אינו משלם, אבל אם אינו רוצה לכונסה — משלם. \u0003תניא נמי הכי\u0004 \u0005[שנויה גם כן\u0006 בברייתא\u0005]\u0006 במפורש: \u0003אף על פי שאמרו המפתה נותן\u0004 קנס \u0003לכשלא יכנוס,\u0004 מכל מקום \u0003בושת ופגם נותן מיד.\u0004 ועוד נאמר שם: \u0003ואחד האונס ואחד המפתה, בין היא ובין אביה יכולין לעכב.\u0004 שאף על פי שהאונס חייב לשאת את האנוסה, היא או אביה יכולים לסרב.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 בענין \u0003מפותה — כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"אם מאן ימאן אביה\u0004 לתתה לו\u0003\"\u0004 (שמות כב, טז), ודרשו חכמים: \u0003אין לי אלא אביה\u0004 שיכול למאן, \u0003היא עצמה מנין\u0004 שיכולה למאן בו — \u0003תלמוד לומר: \"ימאן\", מכל מקום,\u0004 שמכפל הלשון למדים שאף היא רשאית למאן.","\u0003אלא אונס,\u0004 מניין לנו דין זה? \u0003בשלמא איהי\u0004 \u0005[נניח היא]\u0006 שיכולה למאן — \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ולו תהיה\u0004 לאשה\u0003\"\u0004 (דברים כב, כט), משמע \"תהיה\" היא — \u0003מדעתה\u0004 ומרצונה. \u0003אלא אביה מנלן\u0004 \u0005[מניין לנו]\u0006 שיכול לעכב?","\u0003אמר אביי:\u0004 יש סברה בדבר: \u0003שלא יהא חוטא נשכר,\u0004 שאם אין אביה יכול למאן, נמצא שעל ידי שחטא בה ואנסה יוכל לשאתה למרות סירובו של אביה. \u0003רבא אמר: קל וחומר\u0004 הוא, \u0003ומה מפתה שלא עבר אלא על דעת אביה בלבד,\u0004 שהרי היא עצמה התרצתה לו, בכל זאת \u0003בין היא ובין אביה יכולין לעכב — אונס שעבר על דעת אביה ועל דעת עצמה לא כל שכן\u0004 ששניהם יכולים לעכב.","ומסבירים: \u0003רבא לא אמר כאביי\u0004 ומדוע — \u0003כיון דקא\u0004 \u0005[שהוא]\u0006 \u0003משלם קנס\u0004 אם כן \u0003לאו\u0004 \u0005[לא]\u0006 \u0003חוטא נשכר הוא,\u0004 שאינו מרויח מן האונס, שהרי הוא משלם כמוהר הבתולות גם כאשר הוא נושא אותה. \u0003אביי לא אמר כרבא,\u0004 וטעמו הוא: \u0003מפתה דאיהו מצי מעכב\u0004 \u0005[שהוא\u0006 עצמו \u0005יכול לעכב],\u0006 כלומר, הוא יכול להחליט אם הוא רוצה לשאתה או לא — \u0003אביה נמי מצי מעכב\u0004 \u0005[גם כן יכול לעכב],\u0006 \u0003אונס דאיהו לא מצי מעכב\u0004 \u0005[שהוא\u0006 עצמו \u0005אינו יכול לעכב]\u0006 וחייב לשאתה בעל כרחו, אפשר היה לומר ש\u0003אביה נמי לא מצי מעכב\u0004 \u0005[גם כן אינו יכול לעכב].\u0006","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אף על פי שאמרו אונס נותן מיד, כשיוציא הוא אין לה עליו כלום.\u0004 מתחילה תוהים על עצם הלשון: \u0003כשיוציא?! מי מצי מפיק לה\u0004 \u0005[האם\u0006 הוא \u0005יכול להוציא אותה]?!\u0006 והרי הכתוב אומר שאסור לו לגרש אותה! אלא \u0003אימא\u0004 \u0005[אמור],\u0006 תקן את הלשון, כך: \u0003כשתצא היא,\u0004 אם היא רוצה להתגרש ממנו ותובעת ממנו גט \u0003אין לה עליו כלום\u0004 כל תביעה נוספת של ממון. וכן אם \u0003מת\u0004 ובטלו נישואיהם לא על ידי גירושין אלא על ידי מיתה — \u0003יצא כסף קנסה בכתובתה,\u0004 שכיון ששילם כבר קנס כמוהר הבתולות, הרי כסף הקנס הוא במקום תשלום הכתובה. \u0003ר' יוסי בר' יהודה אומר:\u0004 אף אנוסה \u0003יש לה כתובה מנה\u0004 (ככתובתה של כל אשה שאינה בתולה).","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון הם \u0005חולקים],\u0006 כשדנו אם יש לה כתובה. ומסבירים, \u0003רבנן סברי\u0004 \u0005[סבורים]:\u0006 \u0003טעמא מאי תקינו רבנן\u0004 \u0005[מה טעם תיקנו חכמים]\u0006 \u0003כתובה\u0004 לאשה \u0005—\u0006 \u0003כדי שלא תהא קלה בעיניו להוציאה,\u0004 שכשהדבר יהיה קשור בהוצאה כספית יתעכב הדבר, \u0003והא לא מצי מפיק לה\u0004 \u0005[וזו,\u0006 האנוסה, הרי \u0005אינו יכול להוציאה]\u0006 שהרי מדין תורה אסור לו לגרשה, ולכן אין לה כתובה. \u0003ור' יוסי בר' יהודה סבר: הא נמי מצער לה\u0004 \u0005[זה גם כן\u0006 יכול הוא \u0005לצער אותה]\u0006 \u0003עד דאמרה\u0004 \u0005[שאומרת]\u0006 \u0003היא \"לא בעינא לך\u0004 \u0005[אינני רוצה אותך]\u0006 \u0003\"\u0004ויגרשנה, ולכן תיקנו גם לה כתובה של מנה, כדי שלא ימהר לעשות זאת.","שנינו במשנה \u0003אונס שותה בעציצו,\u0004 שחייב לשאת את אנוסתו, מה שאין כן המפתה שאינו חייב לשאת את מפותתו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא מפרזקיא לרב אשי: מכדי מיגמר גמרי מהדדי\u0004 \u0005[הלא למודים הם\u0006 אונס ומפתה \u0005זה מזה]\u0006 לענין סכום הקנס, משמע שדיניהם דומים זה לזה, ואם כן,"],["\u0003להא מילתא נמי ליגמרו מהדדי\u0004 \u0005[לדבר זה\u0006 שיהא מפתה חייב לשאת בעל כרחו \u0005גם כן ילמדו זה מזה]!\u0006 ענה לו רב אשי: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין מפתה: \u0003\"מהר ימהרנה לו לאשה\"\u0004 (שמות כב, טו) והלשון \u0003\"לו\"\u0004 כוונתה \u0003מדעתו.\u0004","שנינו במשנה \u0003כיצד שותה בעציצו כו',\u0004 ואמרו שם שגם אם יש בה מומים — חייב לשאתה לאשה. אבל אם יש בה איסור בנישואיה, בין אם זה מצד התנהגותה בפריצות, ובין אם זה מצד פגם יוחסין — אינו חייב לשאתה. \u0003אמר רב כהנא: אמריתא לשמעתא קמיה\u0004 \u0005[אמרתי מימרה\u0006 זו \u0005לפני]\u0006 \u0003רב זביד מנהרדעא\u0004 ושאלתי: מדוע לא נאמר כי \u0003ניתי\u0004 \u0005[תבוא]\u0006 מצוות \u0003עשה\u0004 של \"ולו תהיה לאשה\" \u0003ונדחה\u0004 \u0005[ותדחה]\u0006 את מצוות \u0003לא תעשה\u0004 שיש בנישואין פסולים, ונאמר שגם אם יש בה איסור \"לא תעשה\" — מכל מקום העשה של נישואין ידחה אותו, כפי הכלל שמצוות \"עשה\" דוחה מצוות \"לא תעשה\"!","\u0003אמר לי: היכא אמרינן ניתי\u0004 \u0005[היכן אומרים אנו\u0006 את הכלל ש\u0005תבוא]\u0006 מצוות \u0003עשה ונידחי\u0004 \u0005[ותדחה]\u0006 את מצוות \u0003לא תעשה,\u0004 הרי זה \u0003כגון\u0004 במקרה של \u0003מילה בצרעת,\u0004 שעם ביצוע מצוות המילה הוא חותך את נגע הצרעת שהיתה על הערלה. ומותר לו לעשות זאת משום שהעשה של מילה דוחה את הלא תעשה האוסר לחתוך את נגע הצרעת. וזאת מפני \u0003דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר לקיומיה\u0004 \u0005[לקיים]\u0006 את ה\u0003עשה\u0004 בלא לדחות על ידי כך את הלא תעשה, ובמקרה כזה העשה דוחה. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 בענין אונס, הלא \u0003אי אמרה דלא בעינא\u0004 \u0005[אם\u0006 היא \u0005אומרת שאינה רוצה]\u0006 אותו לבעל \u0003מי איתיה\u0004 \u0005[האם ישנו]\u0006 \u0003לעשה\u0004 ב\u0003כלל?\u0004 וכיון שמצוות עשה זו איננה חיוב הכרחי לגמרי, ואפשר לדחותו על פי רצון האשה, לכן אין עשה זה יכול לדחות מצוות לא תעשה.","נערה \u0003יתומה,\u0004 או נערה \u0003שנתארסה ונתגרשה, ר' אלעזר אומר: האונס\u0004 אותה בנערותה \u0003חייב\u0004 בקנס שהרי היא נערה בתולה שחייב לשלם קנס עליה, \u0003והמפתה\u0004 — \u0003פטור.\u0004 כיון שהיא יתומה, או שנתארסה ונתגרשה, הרי היא כעומדת ברשות עצמה, ומכיון שנתפתתה מרצון, ממילא מחלה על הקנס.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: ר' אלעזר בשיטת ר' עקיבא רבו אמרה\u0004 להלכה זו. ש\u0003אמר\u0004 ר' עקיבא במשנה לעיל (כתובות לח, א) שנערה שנתארסה ונתגרשה ואחר כך נאנסה, \u0003יש לה קנס וקנסה לעצמה.\u0004 ואילו לר' יוסי הגלילי אין לה קנס. ו\u0003ממאי\u0004 \u0005[\u0006ו\u0005ממה,\u0006 מניין\u0005]\u0006 אנו יודעים זאת — \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 במשנה: \u0003יתומה, ר' אלעזר אומר: האונס חייב והמפתה פטור.\u0004","ויש לשאול: \u0003יתומה, פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, שהרי אין לה אב ואינה ברשות אחר, ואם כן, מדוע ישלם לה קנס על מה שעושה מרצונה? \u0003אלא הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003נערה שנתארסה ונתגרשה,\u0004 אפילו כשיש לה אב, דינה \u0003כיתומה, מה יתומה\u0004 קנסה \u0003לעצמה — אף נערה שנתארסה ונתגרשה\u0004 קנסה \u0003לעצמה.\u0004","\u0003אמר ר' זירא אמר רבה בר שילא אמר רב המנונא סבא אמר רב אדא בר אהבה אמר רב: הלכה כר' אלעזר.\u0004 ובכלל \u0003קרי\u0004 \u0005[\u0006היה \u0005קורא]\u0006 \u0003רב עליה\u0004 \u0005[עליו]\u0006 על \u0003ר' אלעזר: \"טובינא דחכימי\"\u0004 \u0005[\"מאושר שבחכמים\"],\u0006 משום שהיה סבור שהלכה כמותו בהרבה מקומות.","\u0003איזהו בושת,\u0004 איך אומדים את הערך הכספי של הבושת באונס ובפיתוי? — \u0003הכל לפי המבייש והמתבייש.\u0004 שהדבר תלוי הן במעלת משפחת האנוסה והן בטיבו של האונס. \u0003פגם\u0004 כיצד אומדים אותו — \u0003רואין אותה כאילו היא שפחה הנמכרת בשוק\u0004 ובודקים \u0003כמה היתה יפה\u0004 (שווה) קודם לכן, \u0003וכמה היא יפה\u0004 כעת לאחר הבעילה. סכום ה\u0003קנס שוה בכל אדם,\u0004 שכלל הוא: \u0003וכל שיש לו קצבה מן התורה — שוה בכל אדם,\u0004 ואין מבחינים לפי חשיבותו של הנפגע.","לעיקר דברי המשנה שהאונס משלם בושת ופגם שואלים: \u0003ואימא\u0004 \u0005[ואמור\u0006 כך\u0005]:\u0006 \u0003חמשים סלעים אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 שמשלם, והכוונה היא \u0003מכל מילי\u0004 \u0005[\u0006ה\u0005דברים\u0006 יחד\u0005],\u0006 שכל התשלומים הנזכרים כאן, גם הקנס וגם הפגם, והבושת והצער, כל אלה יסתכמו בחמישים סלעים! \u0003אמר ר' זירא:\u0004 אי אפשר לומר כך, כי \u0003יאמרו:\u0004 אם \u0003בעל בת מלכים\u0004 משלם בסך הכל \u0003חמשים\u0004 סלעים, ואם \u0003בעל בת הדיוטות\u0004 ישלם גם כן \u0003חמשים?! אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 זה אינו נימוק מכריע, כי \u0003אי הכי\u0004 \u0005[אם כך]\u0006 ל\u0003גבי\u0004 דין ה\u0003עבד\u0004 שאמרה תורה שאם שור הרג עבד כנעני, חייב בעל השור לשלם לאדוניו של העבד שלושים שקלים — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003יאמרו: עבד נוקב מרגליות\u0004 ששווה הרבה, משום שאומנותו חשובה — משלם עבורו \u0003שלשים, עבד\u0004 ש\u0003עושה\u0004"],["\u0003מעשה מחט\u0004 (חייט) שמלאכתו פשוטה ושוויו מועט — ישלם גם כן \u0003שלשים?!\u0004 אלא ודאי יש לומר שזו היא גזירת התורה, ואינה מבדילה בטיבו של הניזק, ואף באנוסה אפשר לומר כן!","\u0003אלא אמר ר' זירא,\u0004 ודאי שאין הבושת והפגם בכלל החמישים, ויש להוכיח זאת באופן אחר: \u0003אילו באו עליה שנים, אחד\u0004 בא עליה \u0003כדרכה, ואחד\u0004 בא עליה \u0003שלא כדרכה,\u0004 האם \u0003יאמרו\u0004 שמי ש\u0003בעל\u0004 בתולה \u0003שלימה\u0004 משלם \u0003חמשים,\u0004 ומי ש\u0003בעל\u0004 אותה כשהיא \u0003פגומה,\u0004 שכבר נבעלה מקודם שלא כדרכה, משלם גם כן \u0003חמשים?\u0004 אלא ודאי תשלום חמישים הוא תשלום קצוב של קנס, והשאר משתנה בהתאם לפרטי המעשה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 גם זו אינה הוכחה, כי \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003גבי עבד נמי\u0004 \u0005[גם כן]\u0006 \u0003יאמרו:\u0004 אם נגח השור \u0003עבד בריא\u0004 — משלם \u0003שלשים,\u0004 ואם נגח \u0003עבד מוכה שחין\u0004 — משלם \u0003שלשים?!\u0004","\u0003אלא אמר אביי,\u0004 להוכיח באופן אחר שאין הבושת והפגם בכלל החמישים, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"תחת אשר ענה\"\u0004 (דברים כב, כט), \u0003הני\u0004 \u0005[\u0006תשלומים \u0005אלה]\u0006 של הקנס הם \u0003תחת אשר עינה\u0004 בלבד, ו\u0003מכלל\u0004 זה נלמד \u0003דאיכא\u0004 \u0005[שיש]\u0006 עוד תשלומים נוספים של \u0003בושת ופגם\u0004 שלא נמנו בכתוב זה משום שאינם בכלל העינוי. \u0003רבא אמר\u0004 הוכחה אחרת, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ונתן האיש השכב עמה לאבי הנערה חמשים כסף\"\u0004 (דברים כב, כט), ההדגשה של \"השוכב עמה\" באה לומר: עבור \u0003הנאת שכיבה\u0004 נותן הוא \u0003חמשים, מכלל\u0004 זה נלמד \u0003דאיכא\u0004 \u0005[שיש]\u0006 עוד תשלומי \u0003בושת ופגם\u0004 שאינם משום הנאת השכיבה, ואותם הוא מוסיף על הקנס.","שואלים בענין אחר: \u0003ואימא לדידה\u0004 \u0005[ואמור\u0006 שאת התשלומים הנוספים הללו ישלם \u0005לה]\u0006 ולא לאביה? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004בין אב לבתו \u0003בנעריה בית אביה\"\u0004 (במדבר ל, יז), ומכאן למדים: \u0003כל שבח נעוריה,\u0004 כל מה שהיא מרוויחה בנעוריה בכל אופן שהוא — שייך \u0003לאביה.\u0004","ושואלים: \u0003ואלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב הונא אמר רב: מנין שמעשה הבת\u0004 שייכים \u0003לאביה — שנאמר: \"וכי ימכר איש את בתו לאמה\"\u0004 (שמות כא, ז), מההיקש של בת לאמה למדים: \u0003מה אמה מעשה ידיה לרבה\u0004 (אדוניה), שהרי לכך נמכרה — \u0003אף בת מעשה ידיה לאביה.\u0004 אולם הוכחה מסובכת זו \u0003למה לי? תיפוק ליה\u0004 \u0005[תצא לו]\u0006 ההוכחה במישרין \u0003מ\"בנעריה בית אביה\"! אלא,\u0004 ודאי אין ללמוד מן הכתוב \"בנעוריה בית אביה\" כי \u0003ההיא\u0004 (אותה הלכה) \u0003בהפרת נדרים הוא דכתיב\u0004 \u0005[שנאמר],\u0006 שלענין נדרים שנדרה הרי היא ברשות האב, בהיותה בנעוריה בבית אביה, ואביה מיפר לה את נדריה, אבל אין ללמוד מכאן לענין ממונות,","\u0003וכי תימא נילף מיניה\u0004 \u0005[ואם תאמר נלמד מכאן]\u0006 שכשם שלענין נדרים היא ברשות אביה, כך לענין ממון היא ברשות אביה, הרי זה בניגוד לכלל ש\u0003ממונא מאיסורא לא ילפינן\u0004 \u0005[ממון מאיסור אין אנו למדים],\u0006 \u0003וכי תימא נילף מקנסא\u0004 \u0005[ואם תאמר נלמד מקנס],\u0006 שכשם שמפורש בתורה שהקנס מגיע לאביה, אף ממון המגיע לה ממעשה ידיה גם הוא לאביה, אולם דבר זה הוא כנגד הכלל ש\u0003ממונא מקנסא לא ילפינן\u0004 \u0005[\u0006דין חיוב \u0005ממון מקנס אין אנו למדים],\u0006 שקנס הוא חידוש לעצמו, ואיננו מלמד לגבי שאר חיובי ממונות. \u0003אלא\u0004 יש לומר כי \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 על פי ההגיון, כי של \u0003אביה הוי\u0004 \u0005[הוא]\u0006 תשלום בושת ופגם, כיון \u0003דאי בעי\u0004 \u0005[שאם\u0006 היה \u0005רוצה]\u0006 הלא \u0003מסר לה\u0004 (אותה) לנישואין \u0003למנוול ומוכה שחין,\u0004 והיתה לה בושת על ידי כך, וכיון שבושתה תלויה בו, לכן התשלום עבור בושת, שלו הוא.","נאמר במשנה שלגבי \u0003פגם רואין אותה כאילו היא שפחה נמכרת,\u0004 ורואים בכמה פחת מחירה. ושואלים: \u0003היכי שיימינן לה\u0004 \u0005[איך אומדים אותה]\u0006 לענין זה? \u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל: אומדין כמה אדם רוצה ליתן\u0004 ולהוסיף \u0003בין שפחה בתולה לשפחה בעולה לשמשו\u0004 (לשרת אותו).","ותוהים: \u0003שפחה בעולה לשמשו מאי נפקא ליה מינה\u0004 \u0005[מה יוצא לו מזה]\u0006 אם בתולה היא או בעולה היא? שכיון שמשתמש בה לעבודה בלבד מה ההבדל עבורו אם היא בתולה או בעולה? \u0003אלא\u0004 ההבדל \u0003בין שפחה בעולה לשפחה שאינה בעולה\u0004 הוא באופן שרוצה \u0003להשיאה לעבדו.\u0004 ושואלים עוד: \u0003ולעבדו מאי נפקא ליה מינה\u0004 \u0005[מה יוצא לו מזה]\u0006 מה איכפת לו איזו שפחה תהיה נשואה לעבד? ומשיבים: \u0003בעבד שיש לו לרבו קורת רוח הימנו\u0004 והאדון רוצה לעשות לעבד גם כן נחת רוח, ולכן רוצה לחפש עבורו שפחה בתולה דווקא, וכיוון שיש הבדל במחירה, ההבדל הזה הוא סכום הפגם שיש לשלם לאנוסה.","\u0003כל מקום שיש מכר,\u0004 כלומר, בזמן שיש זכות לאב למכור את בתו לאמה, כשהיא קטנה — \u0003אין קנס\u0004 אם נאנסה. \u0003וכל מקום שיש קנס,\u0004 כלומר, שהיא נערה — \u0003אין מכר,\u0004 אין זכות לאב למכור. ופירוט הדברים: \u0003קטנה — יש לה מכר,\u0004 שהיא נמכרת על ידי האב \u0003ואין לה קנס, נערה — יש לה קנס ואין לה מכר. הבוגרת — אין לה לא מכר ולא קנס.\u0004","\u0003אמר רב יהודה אמר רב:\u0004 משנה \u0003זו דברי ר' מאיר\u0004 היא, \u0003אבל חכמים אומרים: יש לה קנס\u0004 גם \u0003במקום\u0004 שיש בה \u0003מכר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003קטנה מבת יום אחד ועד שתביא שתי שערות\u0004 (שאז נעשית נערה) \u0003— יש לה מכר ואין לה קנס. משתביא שתי שערות עד שתיבגר — יש לה קנס ואין לה מכר,\u0004 אלו \u0003דברי ר' מאיר. שהיה ר' מאיר אומר\u0004 כלל: \u0003כל מקום שיש מכר — אין קנס, וכל מקום שיש קנס — אין מכר. וחכמים אומרים: קטנה מבת שלש שנים ויום אחד ועד שתיבגר — יש לה קנס.\u0004","תחילה תוהים על לשון חכמים בברייתא: \u0003קנס — אין\u0004 \u0005[כן],\u0006 \u0003מכר — לא?!\u0004 האם לדעתם אין רשאי למכור אותה לאמה כשהיא קטנה? אלא \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003אף קנס\u0004 יש לה \u0003במקום\u0004 שיש בה גם \u0003מכר. אמר רב חסדא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר?\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באונס: \u0003\"ולו תהיה לאשה\"\u0004 (דברים כב, כט) — \u0003במהוה\u0004 (במשיאה) \u0003עצמה הכתוב מדבר.\u0004 שהיא בגיל שיכולה להשיא את עצמה, ואם כן צריכה היא להיות לפחות נערה, הנחשבת כבת דעת וברשות עצמה. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה טעמם? — \u0003אמר ריש לקיש: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"נערה\"\u0004 והכתיב שם הוא \"נער\", וכתיב חסר זה בא ללמד ש\u0003אפילו קטנה במשמע.\u0004","מספרים: \u0003שמעה\u0004 \u0005[שמע\u0006 את ההלכה הזאת\u0005]\u0006 \u0003רב פפא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חנן מ\u0004המקום הנקרא \u0003בי כלוחית, אזל\u0004 \u0005[הלך]\u0006 ו\u0003אמרה קמיה\u0004 \u0005[לפני]\u0006 \u0003רב שימי בר אשי. אמר ליה\u0004 \u0005[לו]\u0006 רב שימי: \u0003אתון, אהא מתניתו לה\u0004 \u0005[אתם, על זה,\u0006 על בעיה זו \u0005אתם שונים אותה]\u0006 את השמועה הזאת, \u0003אנן, אהא מתנינן לה\u0004 \u0005[אנו,\u0006 לפי מסורות שבידינו, \u0005על\u0006 דבר \u0005זה אנו שונים אותה],\u0006 ש\u0003אמר ריש לקיש: המוציא שם רע על הקטנה פטור\u0004 מקנס, \u0003שנאמר: \"ונתנו לאבי הנערה\"\u0004 (דברים כב, יט), \u0003\"נערה\"\u0004 בכתיב \u0003מלא דיבר הכתוב.\u0004 ללמד שדין זה הוא רק בנערה ולא בקטנה, משמע שאם המלה כתובה חסר, היינו למדים שאף קטנה בכלל זה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אדא בר אהבה: טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003\"נערה\"\u0004 מלא, \u0003הא לאו הכי הוה אמינא\u0004 \u0005[הרי לולא זה הייתי\u0006 לכאורה \u0005אומר]\u0006 ש\u0003אפילו קטנה\u0004 בכלל דין זה? אולם איך אפשר לומר כך? \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ואם אמת היה הדבר הזה לא נמצאו בתולים לנער. והוציאו את הנער אל פתח בית אביה וסקלוה\"\u0004 (דברים כב, כ-כא), ש\"נער\" בכתיב חסר נאמרה כאן, וחייבים לומר שכאן מדובר בנערה שהיא כבר בת דעת ובת עונשין, שהרי \u0003קטנה לאו בת עונשין היא! אלא\u0004 כך צריך לומר: \u0003כאן\u0004 בענין מוציא שם רע \u0003נערה\u0004 דווקא ולא קטנה, וכיון שרק בדין זה כתובה המלה \"נערה\" מלא (דברים כב, יט), נלמד מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כל מקום שנאמר \"נער\"\u0004 בכתיב חסר של נערה — \u0003אפילו קטנה במשמע.\u0004"],["\u0003האומר: \"פתיתי את בתו של פלוני\" — משלם בושת ופגם על פי\u0004 הודאת \u0003עצמו, ואין משלם קנס\u0004 על פי הודאת עצמו. וכן \u0003האומר: \"גנבתי\" — משלם את הקרן,\u0004 את שווי הגניבה עצמה, \u0003על פי עצמו, ואין משלם תשלומי כפל ותשלומי ארבעה וחמשה\u0004 אם טבח או מכר את הגניבה, לפי שהם קנס ואין אדם משלם קנס על פי עצמו. וכן אם הודה: \u0003\"המית שורי את פלוני\", או:\u0004 \"המית שורי את \u0003שורו של פלוני\" — הרי זה משלם על פי עצמו.\u0004 אבל אמר: \u0003\"המית שורי\u0004 את \u0003עבדו של פלוני\" — אין משלם על פי עצמו,\u0004 לפי שהתשלום על כך הוא בגדר קנס. \u0003זה הכלל: כל המשלם יתר על מה שהזיק,\u0004 ואלה הרי הם בגדר של קנסות — \u0003אינו משלם על פי\u0004 הודאת \u0003עצמו,\u0004 אלא רק על פי עדות אחרת.","שואלים: \u0003וליתני\u0004 \u0005[ושישנה]\u0006 האומר \u0003\"אנסתי\u0004 את בתו של פלוני \u0003\"\u0004ולמה אמרה המשנה את הדין דווקא בפיתוי? ומשיבים: בלשון \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 \u0003קאמר\u0004 \u0005[אמר]\u0006 באופן זה: \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 המשנה להשמיענו כשאומר \u0003\"אנסתי\", דלא קא פגים לה\u0004 \u0005[שאינו פוגם אותה],\u0006 שהרי הוא מעיד רק בגנות עצמו, ש\u0003משלם בושת ופגם על פי עצמו, אבל\u0004 כשאמר \u0003\"פתיתי\u0004 את בתו של פלוני \u0003\", דקא פגים לה\u0004 \u0005[שפוגם אותה],\u0006 שהרי הוא מעיד שזנתה עמו מרצונה, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא משלם על פי עצמו — על כן קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכיון שהודה בדבר, חייב את עצמו בתשלומים.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003ר' שמעון בן יהודה אומר משום ר' שמעון: אף בושת ופגם אינו משלם על פי עצמו,\u0004 והטעם — \u0003לא כל הימנו,\u0004 כלומר, אין זה בכוחו \u0003שיפגום בתו של פלוני\u0004 על ידי הודאתו בלבד, וכל עוד אין לנו עדות אחרת בדבר, אין להאמין כלל שנתפתתה לו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004 לשיטת ר' שמעון, אם \u0003ניחא\u0004 \u0005[נוח]\u0006 \u0003לה לדידה\u0004 \u0005[עצמה]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 יהא הדין\u0005],\u0006 שאם גם היא מודה בדבר, האם גם אז יאמר שאינו חייב בבושת ופגם? ענה לו: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לא ניחא ליה\u0004 \u0005[נוח לו\u0006 הדבר\u0005]\u0006 \u0003לאביה\u0004 שיצא על בתו שם רע, ולפיכך גם במקרה כזה לא נסמוך על הודאתו בלא עדות אחרת. המשיך רב פפא ושאל: אם \u0003ניחא ליה\u0004 \u0005[נוח לו]\u0006 גם \u0003לאביה, מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 ענה לו: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לא ניחא להו\u0004 \u0005[נוח להם]\u0006 \u0003לבני\u0004 ה\u0003משפחה\u0004 האחרים, שיפגם שם אחת מקרובותיהם. חזר ושאל: אם \u0003ניחא להו\u0004 \u0005[נוח להם]\u0006 \u0003לבני\u0004 ה\u0003משפחה מאי\u0004 \u0005[מה\u0006 יהא הדין\u0005]?\u0006 ענה לו: \u0003אי אפשר דליכא חד\u0004 \u0005[שאין אחד]\u0006 \u0003במדינת הים,\u0004 כלומר, בארץ רחוקה, ש\u0003לא ניחא ליה\u0004 \u0005[נוח לו],\u0006 שגם אם הקרובים שלפנינו אומרים שלא איכפת להם, עדיין ניתן לומר שאחד הקרובים במרחקים מקפיד בדבר.","שנינו במשנה: \u0003האומר \"גנבתי\"\u0004 — \u0003משלם את הקרן,\u0004 אבל אינו משלם תשלומי כפל ותשלומי ארבעה וחמישה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים ביחס ל\u0003פלגא ניזקא\u0004 \u0005[חצי נזק]\u0006 שחייב אדם לשלם אם הזיק שור תם שלו (שעדיין לא העידו בו שנגח שלוש פעמים) את שורו של אחר. \u0003רב פפא אמר: פלגא ניזקא\u0004 \u0005[חצי נזק]\u0006 — \u0003ממונא\u0004 \u0005[\u0006זה הוא \u0005ממון],\u0006 כלומר, תשלום זה הוא חיוב ממון שיש לשלם לניזק על הנזק שנגרם לו. \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: פלגא ניזקא\u0004 \u0005[חצי נזק]\u0006 — \u0003קנסא\u0004 \u0005[קנס\u0006 הוא\u0005].\u0006","ומסבירים את טעמיהם: \u0003רב פפא אמר פלגא ניזקא ממונא\u0004 \u0005[חצי נזק ממון\u0006 הוא\u0005],\u0006 \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 כי \u0003סתם שוורים לאו בחזקת שימור קיימי\u0004 \u0005[עומדים],\u0006 שההנחה העקרונית היא שסתם שוורים אינם שמורים והם בחזקת מזיקים, \u0003ובדין הוא דמשלם כוליה\u0004 \u0005[שישלם\u0006 את הנזק \u0005כולו],\u0006 \u0003ורחמנא הוא דחייס עלויה\u0004 \u0005[והתורה היא שחסה עליו],\u0006 משום \u0003דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא איעד תורא\u0004 \u0005[הועד השור],\u0006 שרק בנגיחת הפעם השלישית הוא נעשה מועד, אך על כל פנים, אותו סכום שהוא משלם — מן הדין הוא משלם. ואילו \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: פלגא ניזקא קנסא\u0004 \u0005[חצי נזק קנס\u0006 הוא\u0005],\u0006 \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003סתם שוורים בחזקת שימור קיימי\u0004 \u0005[עומדים],\u0006 ואין להניח שהם מזיקים, \u0003ובדין הוא\u0004 ש\u0003לא לישלם\u0004 \u0005[ישלם]\u0006 \u0003כלל,\u0004 לפי שסתם שור שנוגח עושה מעשה שאין לצפותו מראש, ואינו בגדר אחריותו של בעליו. \u0003ורחמנא הוא דקנסיה כי היכי דנינטריה לתוריה\u0004 \u0005[והתורה היא שקנסה אותו כדי שישמור את שורו],\u0006 ואם כן מה שמשלם הוא רק קנס.","ונותנים \u0003סימן\u0004 להלכות שמהן יביאו להלן ראיה בדין זה, והן: \u0003היזיק, מה, והמית, כלל. תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 שכאשר נגח שור תם את שורו של אדם אחר והרגו — \u0003הניזק והמזיק בתשלומין,\u0004 כלומר, שניהם מפסידים בשל אותה נגיחה. ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003פלגא ניזקא ממונא\u0004 \u0005[חצי נזק ממון\u0006 הוא\u0005],\u0006 \u0003היינו\u0004 \u0005[זהו\u0006 הטעם\u0005]\u0006 ש\u0003שייך\u0004 ה\u0003ניזק בתשלומין.\u0004 שהרי לשיטתו מן הדין היה הניזק צריך לקבל את כל דמי הנזק, אבל כיון שהיה המזיק שור תם, נמצא שהניזק משתתף בעצמו ומכסה חצי סכום הנזק, ולכן אמרה המשנה שגם הוא \"בתשלומים\". \u0003אלא למאן דאמר פלגא ניזקא קנסא\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006 ש\u0005חצי נזק קנס\u0006 הוא\u0005]\u0006 ולדבריו מן הדין לא מגיע לניזק כלום, אם כן \u0003השתא דלאו דידיה קא שקיל\u0004 \u0005[עכשיו,\u0006 הרי, מה \u0005שאינו שלו\u0006 מן הדין, הוא \u0005נוטל],\u0006 וכי \u0003בתשלומין איתיה\u0004 \u0005[הוא נמצא]?!\u0006 שהרי מה שמקבל הניזק אינו אלא משום שקנסו את המזיק, ואם כן הניזק בעצם אינו משלם כלום!","ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 מימרה זו \u0003אלא לפחת נבילה.\u0004 אמנם מעריכים את חצי הנזק כאשר מחלקים לשנים את ההפרש שבין דמי שור חי ודמי הנבילה בשעת עמידה בדין. ואולם מה שערך הנבילה פוחת אחר כך, עד הזמן שבעל הנבילה מוכר אותה בפועל — את זה אין משלמים לניזק, ונמצא שהניזק נעשה גם הוא שותף בתשלומים, שהרי הוא מפסיד את הסכום הזה משל עצמו. ומקשים על תירוץ זה: \u0003פחת נבילה\u0004 הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר במפורש בברייתא במסכת בבא קמא, שמה נאמר במשנה \u0003\"תשלומי נזק\"\u0004 — הרי זה \u0003מלמד שהבעלים מטפלין בנבילה\u0004 ועל חשבונם הפחת ממחירה!","ומשיבים: \u0003חדא\u0004 \u0005[\u0006הלכה \u0005אחת]\u0006 נאמרה לגבי שור \u0003תם וחדא\u0004 \u0005[ו\u0006הלכה \u0005אחת]\u0006 נאמרה לגבי שור \u0003מועד.\u0004 ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שתיאמרנה שתיהן; \u0003דאי אשמועינן\u0004 \u0005[שאם\u0006 היה \u0005משמיע לנו]\u0006 דין זה רק ב\u0003תם,\u0004 היינו אומרים: \u0003משום דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא איעד\u0004 \u0005[הועד]\u0006 השור, לכן מקילים בדינו של המזיק, \u0003אבל מועד דאיעד\u0004 \u0005[ש\u0006כבר \u0005הועד],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ויתחייב בעל השור המזיק גם בתשלומי הפחת. ולהיפך: \u0003ואי אשמועינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003מועד,\u0004 היינו אומרים: \u0003משום דקא\u0004 \u0005[שהוא]\u0006 \u0003משלם\u0004 את הנזק \u0003כוליה\u0004 \u0005[כולו]\u0006 ופחת הדמים של הנבילה שהוא הפסד קטן ביחס, אינו נחשב, \u0003אבל תם אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 שכיון שמשלם רק את חצי הנזק, ישלם גם מהפסד פחת ערך הנבילה. ולכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו דברים בשני המקרים. ולפי הסבר זה אין להוכיח ממשנה זו לענייננו האם \"חצי נזק\" הינו חיוב ממוני או קנס.","ומציעים ראיה אחרת: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ראיה ממה ששנינו בברייתא: \u0003מה בין תם למועד — שהתם משלם חצי נזק מגופו,\u0004 מדמי השור המזיק עצמו, ואם אינו שווה כדי חצי הנזק, כגון אם שור זול הזיק שור יקר — הרי זה הפסדו של הניזק. \u0003ומועד משלם נזק שלם מן העלייה\u0004 (מרכוש הבעלים). שבעליו משלם את דמי כל הנזק מרכושו בלי קשר לשווי השור המזיק. \u0003ולא קתני\u0004 \u0005[שנה]\u0006 שם את ההבדל הנוסף, \u0003שהתם אינו משלם על פי עצמו, ומועד משלם על פי עצמו.\u0004 שהרי לפי הכלל שלמדנו במשנתנו שהמודה בקנס פטור, אין המודה בכך צריך לשלם! ומכאן ראיה שחצי נזק אינו קנס אלא ממון.","ודוחים: מכאן אין ראיה, כי \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003ושייר,\u0004 ולא שנה את כל פרטי ההבדלים בין תם ומועד. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003שייר\u0004 עוד שאתה אומר \u0003דהאי\u0004 \u0005[ש\u0006את הלכה \u0005זו]\u0006 גם \u0003שייר,\u0004 שהרי אי אפשר לטעון ששייר החכם, אם אין הוכחה אחרת לכך שלא נמנו כל ההבדלים האפשריים! ומשיבים: \u0003שייר חצי כופר.\u0004 שיש הבדל נוסף ביניהם, כי שור מועד שהרג את האדם משלם בעליו כופר, וכששור תם הורג אדם איננו משלם אפילו חצי כופר. ודוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום חצי כופר — זה לאו שיורא\u0004 \u0005[לא שיור]\u0006 \u0003הוא,\u0004 וטעמו של דבר —"],["\u0003הא מני\u0004 \u0005[זו\u0006 שיטת \u0005מי היא],\u0006 כשיטת \u0003ר' יוסי הגלילי היא,\u0004 ש\u0003אמר: תם משלם חצי כופר,\u0004 ולשיטה זו אין לענין זה הבדל בין תם למועד אלא רק מה שנתפרש במשנה. ומביאים ראיה נוספת: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו, אם אמר: \u0003\"המית שורי את פלוני\", או: \"\u0004המית שורי את \u0003שורו של פלוני\" — הרי זה משלם על פי עצמו. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר שם \u0003ב\u0004שור \u0003תם,\u0004 שמשלם חצי נזק, והרי זו הוכחה שתשלום זה נחשב לתשלום ממון, ולא לקנס! שאילו לא היה זה חיוב ממון, לא היה מתחייב בהודאתו. ודוחים: \u0003לא,\u0004 מדובר כאן \u0003במועד.\u0004","","ושואלים: אם כן, \u0003אבל בתם מאי\u0004 \u0005[מה]\u0006 יהא הדין, ש\u0003אינו משלם על פי עצמו,\u0004 אם כן \u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה\u0006 ב\u0005סופה,\u0006 בהמשכה של המשנה\u0005]\u0006 שאם אמר \u0003\"\u0004המית שורי \u0003עבדו של פלוני\" — אינו משלם על פי עצמו, ניפלוג וניתני בדידה\u0004 \u0005[שיחלוק וישנה בה עצמה]\u0006 חלוקה פנימית קרובה יותר: \u0003במה דברים אמורים — במועד, אבל תם — אינו משלם על פי עצמו!\u0004 ודוחים: כל המשנה \u0003כולה במועד קמיירי\u0004 \u0005[עוסקת],\u0006 ואינה דנה כאן כלל בדיניו של שור תם, ולפיכך אינה מחלקת בין תם למועד, ולכן אין ממנה הוכחה לענייננו. ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במשנתנו, \u0003זה הכלל: כל המשלם יתר על מה שהזיק — אינו משלם על פי עצמו,\u0004 שהיתר על מה שהזיק נקרא קנס. ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם משלם \u0003פחות ממה שהזיק — משלם על פי עצמו.\u0004 והרי זו הוכחה שחצי נזק הוא תשלום ממון ולא קנס! ודוחים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 ותדייק \u0003הא\u0004 \u0005[הרי]\u0006 \u0003פחות ממה שהזיק, אלא אימא\u0004 \u0005[אמור]\u0006 ודייק כך: \u0003הא\u0004 \u0005[הרי]\u0006 אם משלם \u0003כמה שהזיק — משלם על פי עצמו.\u0004 ומקשים: אם כן לפי פירוש זה, \u0003אבל\u0004 אם משלם \u0003פחות\u0004 ממה שהזיק — \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין לדעתך — ש\u0003אינו משלם על פי עצמו,\u0004 אם כן \u0003ליתני\u0004 \u0005[שישנה]\u0006 לשון כללית יותר: \u0003זה הכלל כל שאינו משלם כמה שהזיק — אינו משלם על פי עצמו, דמשמע\u0004 \u0005[שמשמעות]\u0006 לשון זו היא כוללת גם כשמשלם \u0003פחות, ומשמע\u0004 גם כשמשלם \u0003יתר!\u0004 ואומרים: אכן, מכאן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי רב הונא בנו של רב יהושע שחצי נזק הוא קנס.","","","ומסכמים להלכה: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003פלגא ניזקא קנסא\u0004 \u0005[חצי נזק קנס\u0006 הוא\u0005].\u0006 ותוהים: \u0003תיובתא והלכתא\u0004 \u0005[קושיה חמורה\u0006 עליו \u0005והלכה\u0006 כמותו\u0005]?!\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 הלכה כמותו, כי יש להסביר: \u0003טעמא מאי איתותב\u0004 \u0005[מה טעם הושב,\u0006 הוקשו דבריו ונשארו בקושיה\u0005] —\u0006 \u0003משום דלא קתני\u0004 \u0005[שאינו שונה]\u0006 \u0003\"כמה שהזיק\",\u0004 אולם לשון זו \u0003לא פסיקא ליה\u0004 \u0005[אינה פסוקה,\u0006 אינה מוחלטת, \u0005לו],\u0006 משום שיש יוצאים מן הכלל. \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 הלכה של \u0003חצי נזק צרורות.\u0004 שאם הלך בעל חיים כדרכו, ותוך כדי הילוכו העיף צרורות, אבנים, והן גרמו נזק — משלם על כך רק חצי נזק, ולא את כל הנזק כולו. \u0003דהלכתא גמירי לה דממונא\u0004 \u0005[שהלכה למודה לנו ש\u0006חיוב \u0005ממון]\u0006 \u0003הוא\u0004 ולא קנס, ודינו לכל ענין כדין נזקי רגל, אלא שמשלם רק חצי הנזק. \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003לא קתני\u0004 \u0005[שנה]\u0006 אותה הצעה \"כמה שהזיק\" באופן כללי שרק אם המשלם כפי שהזיק משלם על פי עצמו, שהרי יש בהלכה דבר הדומה לחצי נזק בנגיחה, ולכל הדעות זה תשלום ממון וגם אותו ישלמו בהודאת עצמו.","ומן הפסק הזה ממשיכים ומסיימים: \u0003והשתא דאמרת פלגא ניזקא קנסא\u0004 \u0005[ועכשיו שאמרת,\u0006 ופסקת, ש\u0005חצי נזק קנס\u0006 הוא\u0005],\u0006 \u0003האי כלבא דאכל אימרי\u0004 \u0005[כלב זה שאכל טלאים],\u0006 \u0003ושונרא דאכיל תרנגולי רברבי\u0004 \u0005[וחתול שאכל תרנגולים גדולים],\u0006 הרי נזק \u0003משונה הוא\u0004 ובתם משלם רק חצי נזק כמו בנגיחה, \u0003ולא מגבינן\u0004 \u0005[ואין אנו גובים\u0006 אותו\u0005]\u0006 \u0003בבבל,\u0004 משום שתשלום עבור נזק בלתי רגיל הוא קנס, ואין גובים קנסות בבבל, שאין בה דיינים סמוכים הרשאים לדון בדיני קנסות. \u0003אבל,\u0004 אם אכל החתול תרנגולים \u0003זוטרי\u0004 \u0005[קטנים]\u0006 — \u0003אורחיה הוא ומגבינן\u0004 \u0005[דרכו היא ואנחנו גובים\u0006 לו לניזק\u0005],\u0006 שאין זה קנס אלא ממון. ומעירים: \u0003ו\u0004במקרים כאלה שהם בתורת קנס — גם בבבל, \u0003אי\u0004 \u0005[אם]\u0006 \u0003תפס\u0004 הניזק מנכסי המזיק כדי שיעור הקנס — \u0003לא מפקינן מיניה\u0004 \u0005[אין אנו מוציאים ממנו],\u0006 שהרי מעיקר הדין מגיע לו תשלום, ואין הנתבע יכול לטעון שאינו חייב כלום. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אמר\u0004 הניזק לבית הדין: \u0003אקבעו\u0004 \u0005[קיבעו]\u0006 \u0003לי זימנא\u0004 \u0005[זמן]\u0006 ללכת \u0003לארץ ישראל,\u0004 ששם אפשר לדון גם בדיני קנסות — \u0003מקבעינן ליה\u0004 \u0005[קובעים לו].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא אזיל\u0004 \u0005[הולך]\u0006 הנתבע לארץ ישראל לפי טענת התובע — \u0003משמתינן ליה\u0004 \u0005[מנדים אותו].\u0006","","ומעירים: \u0003בין כך ובין כך,\u0004 בין אם עלה לארץ ישראל ובין אם לא עלה, אפילו כשלא מחייבים אותו בבבל לשלם קנס, מכל מקום \u0003משמתינן ליה\u0004 \u0005[מנדים אותו]\u0006 אם לא יסלק את המזיק, \u0003דאמרינן ליה\u0004 \u0005[שאומרים אנו לו]:\u0006 \u0003סליק הזיקך\u0004 \u0005[סלק\u0006 את \u0005המזיק שלך]\u0006 וכדברי \u0003ר' נתן. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005],\u0006 \u0003ר' נתן אומר: מנין שלא יגדל אדם כלב רע בתוך ביתו, ולא יעמיד סולם רעוע בתוך ביתו — שנאמר: \"\u0004ועשית מעקה לגגך \u0003ולא תשים דמים בביתך\"\u0004 (דברים כב, ח), מכאן שאסור לו לאדם שישהה בביתו דבר המסכן את הבריות (\"דמים\"). ואם אינו מסלקו — מנדים אותו.","","\u0003נערה שנתפתתה — בושתה ופגמה וקנסה של אביה, ו\u0004כן דמי \u0003הצער בתפוסה\u0004 (אנוסה). \u0003עמדה\u0004 הנערה \u0003בדין\u0004 עם המפתה או האונס \u0003עד שלא מת האב — הרי הן של אב,\u0004 כפי שאמרנו. לפיכך אם \u0003מת האב\u0004 לפני שהספיק לגבות את הכסף מן האיש — \u0003הרי הן,\u0004 הכספים הללו, \u0003של אחין,\u0004 משום שהם היורשים את אביהם וכבר זכה בהן האב.","אולם אם \u0003לא הספיקה לעמוד בדין\u0004 עם המפתה או האונס \u0003עד שמת האב,\u0004 ואחר כך עמדה בדין וזכתה — \u0003הרי הן,\u0004 הכספים הללו, \u0003של עצמה,\u0004 שכיון שמת האב, הרי היא ברשות עצמה לכל דבר. וכן אם \u0003עמדה בדין עד שלא בגרה — הרי הן של אב,\u0004 ואם \u0003מת האב — הרי הן של אחין\u0004 היורשים אותו, אף שבגרה בינתיים. אבל אם \u0003לא הספיקה לעמוד בדין עד שבגרה — הרי הן של עצמה. ר' שמעון אומר:\u0004 אפילו \u0003אם\u0004 עמדה בדין בחיי האב, ו\u0003לא הספיקה לגבות עד שמת האב\u0004 — אין האחים יורשים את הכסף הזה, אלא \u0003הרי הן של עצמה,\u0004 שכל עוד לא הגיע הכסף לידי האב ממש, אינו שלו\u0003.\u0004"],["אבל \u0003מעשה ידיה ו\u0004כן \u0003מציאתה, אף על פי שלא גבתה,\u0004 כגון שעדיין לא קיבלה את שכר עבודתה, גם אם \u0003מת האב — הרי הן של אחין\u0004 שהם יורשי האב, שכיון שזכתה באלה בחיי האב, נעשו כרכושו, והאחים יורשים אותו.","על המשנה שואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 במשנה זו? הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 כבר: \u0003המפתה נותן שלשה דברים, והאונס ארבעה. המפתה נותן בושת ופגם וקנס, מוסיף עליו אונס שנותן את הצער!\u0004 ומשיבים: \u0003לאביה איצטריך ליה\u0004 \u0005[הוצרך לו],\u0006 כלומר, החידוש אינו בפירוט החיובים שלו, אלא בכך שהכל ניתן לאביה. ושואלים: \u0003לאביה נמי פשיטא\u0004 \u0005[גם כן פשוט]\u0006 הדבר \u0003מדקא יהיב\u0004 \u0005[מ\u0006מה \u0005שנותן]\u0006 \u0003מפתה\u0004 תשלום כל עיקר, הרי בודאי לאביה הוא נותן, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לעצמה\u0004 הוא נותן — \u0003אמאי יהיב\u0004 \u0005[מדוע\u0006 בכלל \u0005נותן]\u0006 \u0003המפתה\u0004 קנס? הלא \u0003מדעתה עבד\u0004 \u0005[עשה]\u0006 מה שעשה, וכיצד היא יכולה לתבוע ממנו פיצויים על מה שעשה מרצונה?","ומסבירים: בגלל המקרה שבסיפא, ש\u0003עמדה בדין\u0004 ואחר כך מת האב לפני שהספיקה לגבות \u0003איצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 לשנות, ומשום \u0003פלוגתא\u0004 \u0005[\u0006ה\u0005מחלוקת]\u0006 של \u0003ר' שמעון ורבנן\u0004 \u0005[וחכמים]\u0006 בשאלה האם הבנים יורשים את הפיצויים הללו מן האב, או אינם יורשים והקנס לעצמה.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 במסכת שבועות, מי שאמר לאחר: \u0003\"אנסת\u0004 את בתי, או \u0003פיתית את בתי\", והוא,\u0004 הנתבע, \u0003אומר: \"לא אנסתי ולא פיתיתי\",\u0004 ואמר לו האב: \u0003\"משביעך אני\", ואמר\u0004 הנתבע: \u0003\"אמן\", ואחר כך הודה\u0004 שאכן אנס או פיתה את הבת — הרי זה \u0003חייב,\u0004 הן בתשלומים של אונס או מפתה, והן בתוספת חומש ובהבאת קרבן על שבועת שקר.","\u0003ר' שמעון פוטר.\u0004 וטעמו: \u0003שאינו משלם קנס על פי עצמו.\u0004 ולכן, גם אם היה מודה לאב מתחילה — לא היה צריך לשלם, ואי אפשר לומר שרק בשל השבועה יצטרך לשלם דבר שבעצם אפשר לתבוע ממנו רק כשיש עדים. \u0003אמרו לו\u0004 חכמים: \u0003אף על פי שאינו משלם קנס על פי עצמו — אבל משלם בושת ופגם על פי עצמו,\u0004 ואם כן יש כאן תביעת ממון שכפר בה, ובמקרה כזה, כאשר הודה שנשבע לשקר משלם ומביא קרבן.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003אביי מרבה, האומר לחבירו: \"אנסת\u0004 או \u0003פיתית את בתי והעמדתיך בדין\u0004 על זה \u0003ונתחייבת לי ממון\"\u0004 ולא שילמת, \u0003והוא,\u0004 הנתבע, \u0003אומר: \"לא אנסתי ולא פיתיתי ולא העמדתני בדין ולא נתחייבתי לך ממון\". ונשבע\u0004 הנתבע על דבריו, \u0003ו\u0004אחר כך \u0003הודה — ל\u0004דעת \u0003ר' שמעון מאי\u0004 \u0005[מה]\u0006 הדין?","האם נאמר: \u0003כיון\u0004 ש\u0003עמד בדין\u0004 וכבר נתחייב — \u0003ממונא הואי, ומיחייב עליה\u0004 \u0005[ממון הוא, וחייב עליו]\u0006 \u0003קרבן שבועה,\u0004 כדין כל הכופר בתביעת ממון. \u0003או דלמא\u0004 \u0005[שמא],\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003עמד בדין,\u0004 עיקרו של הכסף \u0003קנס הוי\u0004 \u0005[הוא]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 מכיון שנתחייב כבר בדין הרי \u0003ממונא הוי, ומיחייב עליה\u0004 \u0005[ממון הוא, וחייב עליו]\u0006 \u0003קרבן שבועה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי מברייתא, \u0003ר' שמעון אומר: יכול האומר לחבירו \"אנסת ופיתית את בתי\", והוא,\u0004 הנתבע, \u0003אומר: \"לא אנסתי ולא פיתיתי\",\u0004 או שטוען: \u0003\"המית שורך את עבדי\", והוא אומר: \"לא המית\". או שאמר לו עבדו: \"הפלת את שיני וסימית את עיני\u0004 ואתה צריך לשחררני \u0003\", והוא,\u0004 האדון, \u0003אומר: \"לא הפלתי ולא סימיתי\", ונשבע\u0004 הנתבע על טענתו, \u0003והודה\u0004 לאחר מכן, \u0003יכול יהא חייב\u0004 קרבן משום שבועת כפירת ממון —","\u0003תלמוד לומר\u0004 בכתוב המדבר בקרבן שבועה: \u0003\"וכחש בעמיתו בפקדון או בתשומת יד או בגזל או עשק את עמיתו. או מצא אבדה וכחש בה ונשבע על שקר\"\u0004 (ויקרא ה, כא-כב), \u0003מה אלו מיוחדין שהן ממון,\u0004 שכל הדברים המנויים באותו כתוב הם חיובי ממון שבין אדם לחבירו, \u0003אף כל\u0004 חיובים \u0003שהן\u0004 תביעות של \u0003ממון, יצאו אלו\u0004 של האונס, המפתה וכיוצא בהם, \u0003שהן קנס.\u0004"],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר שם \u0003בשעמד בדין,\u0004 ובכל זאת, כיון שעיקר הכסף היה קנס, אין ר' שמעון מחייב על השבועה! ודחה רבה: \u0003לא,\u0004 שם מדובר \u0003בשלא עמד בדין.\u0004","חזר אביי והקשה: \u0003והא מדרישא\u0004 \u0005[והרי מ\u0006כיון \u0005שראשה\u0006 של ברייתא זו\u0005]\u0006 דנה \u0003ב\u0004מקרה \u0003שעמד בדין — סיפא נמי\u0004 \u0005[סופה גם כן]\u0006 \u0003בשעמד בדין. דקתני רישא\u0004 \u0005[ששנה\u0006 ב\u0005ראשה]\u0006 של הברייתא הזו: \u0003אין לי\u0004 שיתחייב בקרן חומש ואשם \u0003אלא\u0004 ב\u0003דברים שמשלמין עליהם את הקרן. תשלומי כפל, תשלומי ארבעה וחמשה, והאונס, והמפתה, ומוציא שם רע, מנין\u0004 שהם בכלל החיוב בקרבן שבועת הפקדון — \u0003תלמוד לומר: \"\u0004נפש כי תחטא \u0003ומעלה מעל\"\u0004 (ויקרא ה, כא), \u0003ריבה\u0004 כל מיני חטא ומעל.","ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003לא עמד בדין,\u0004 אם כן \u0003כפילא מי איכא\u0004 \u0005[כפל, האם יש\u0006 כאן\u0005]?\u0006 שהרי לדעת הכל מי שהודה מעצמו אינו משלם כפל, וכאן הרי מוזכר תשלום כפל! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן \u0003בשעמד בדין,\u0004 ונחלקו במקרה שהדיינים פסקו כי אכן חייב כפל. \u0003ומדרישא\u0004 \u0005[ומ\u0006כיון \u0005שראשה]\u0006 של הברייתא הוא מדברת \u0003ב\u0004אופן \u0003שעמד בדין,\u0004 אם כן \u0003סיפא נמי\u0004 \u0005[סופה גם כן]\u0006 מדברת \u0003ב\u0004אופן \u0003שעמד בדין\u0004 ולמרות זאת אין ר' שמעון מחייב על השבועה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003יכילנא לשנויי לך\u0004 \u0005[יכול אני לתרץ לך]\u0006 ש\u0003רישא\u0004 \u0005[\u0006ב\u0005ראשה]\u0006 מדובר \u0003ב\u0004מקרה \u0003שעמד בדין, וסיפא\u0004 \u0005[וסופה]\u0006 מדובר \u0003בשלא עמד בדין, ו\u0004הברייתא הזו \u0003כולה\u0004 כשיטת \u0003ר' שמעון היא.\u0004 ומודה ר' שמעון שלאחר שעמד בדין נעשה אף הכפל כממון, ולפיכך ברישא חייב בקרבן ובתשלום על הודאתו, \u0003ו\u0004אולם \u0003שינויי דחיקי לא משנינן לך\u0004 \u0005[תירוצים דחוקים אינני מתרץ לך].\u0006 ש\u0003אם כן,\u0004 שכל הברייתא היא לשיטת ר' שמעון, אזי \u0003אמרת\u0004 \u0005[\u0006יכול היית \u0005לומר]\u0006 \u0003לי\u0004 או \u0003ליתני רישא\u0004 \u0005[שישנה\u0006 ב\u0005ראשה]\u0006 במפורש \u0003\"ר' שמעון אומר\"\u0004 וכו', \u0003או ליתני סיפא\u0004 \u0005[שישנה\u0006 ב\u0005סופה]\u0006 \u0003\"\u0004אלו \u0003דברי ר' שמעון\".\u0004","\u0003אלא,\u0004 כך אני מפרש: אכן כל הברייתא \u0003כולה\u0004 מדברת \u0003בשעמד בדין, ו\u0004לענין החילוק בפסקי הדינים \u0003רישא רבנן\u0004 \u0005[ראשה\u0006 באמת הוא כשיטת \u0005חכמים]\u0006 שמחייבים אותו בקרבן שבועה כשהתובע אומר שעמד בדין ונתחייב והנתבע נשבע לשקר. \u0003וסיפא\u0004 \u0005[וסופה]\u0006 הוא שיטת \u0003ר' שמעון,\u0004 שפוטר מקרבן שבועה את המודה על פי עצמו.","\u0003ומודינא\u0004 \u0005[ומודה אני]\u0006 \u0003לך\u0004 אביי \u0003לענין קרבן שבועה דרחמנא פטריה\u0004 \u0005[שהתורה פטרה אותו]\u0006 מקרבן שבועה במקרה זה, מפני שהוא לומד \u0003מ\"וכחש\u0004 בעמיתו בפקדון\u0003\"\u0004 וכו' (ויקרא ה, כא) שאינו חייב קרבן אלא כאשר נשבע על דבר שהוא מעיקרו חיוב ממון.","\u0003וכי קאמינא\u0004 \u0005[וכאשר אומר אני]\u0006 שלדעת ר' שמעון \u0003ממון הוי\u0004 \u0005[הוא]\u0006 לאחר שנתחייב בדין, לא לענין להתחייב על הודאה בו בקרבן שבועה, אלא הרי זה לענין זכותו \u0003להורישו לבניו.\u0004 שאינו כדין קנס, שאין אדם יכול להורישו לבניו, אלא ממון גמור הוא ומורישו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי על פרט אחרון זה ממשנתנו עצמה, \u0003ר' שמעון אומר: אם לא הספיקה\u0004 הבת \u0003לגבות עד שמת האב — הרי הן של עצמה. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שקנס זה \u0003ממון הוי\u0004 \u0005[הוא]\u0006 \u0003להורישו לבניו\u0004 לאחר העמדה בדין, אם כן \u0003לעצמה אמאי\u0004 \u0005[מדוע]?\u0006 מדוע יהא הכסף לעצמה? הלא כיון שעמדה בדין הרי של ה\u0003אחין בעי מיהוי\u0004 \u0005[\u0006הוא \u0005צריך להיות]\u0006 שהאב מוריש לבניו את הקנס — שהריהו כבר ממון! ונשארה איפוא שיטת רבה ללא פתרון מספיק.","\u0003אמר רבא: האי מילתא קשאי בה\u0004 \u0005[דבר זה התקשו בו]\u0006 \u0003רבה ורב יוסף עשרין ותרתין שנין\u0004 \u0005[עשרים ושתים שנה]\u0006 \u0003ולא איפרק\u0004 \u0005[תורץ],\u0006 \u0003עד דיתיב\u0004 \u0005[שישב]\u0006 \u0003רב יוסף ברישא ופירקה\u0004 \u0005[ב\u0006כסא \u0005ראש\u0006 הישיבה \u0005ותירץ אותה],\u0006 וכך אמר: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 במקרה של אונס, ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ונתן האיש השכב עמה לאבי הנערה חמשים כסף\"\u0004 (דברים כב, כט), לומר: \u0003לא זיכתה תורה\u0004 ממון זה \u0003לאב, אלא משעת נתינה.\u0004 ולכן, מאחר שלא הספיקה הבת לזכות ממון זה לאביה בחייו, אף שכבר נתחייב האונס בדין — לא זכה בו האב להורישו לבניו.","\u0003וכי קאמר\u0004 \u0005[וכאשר אמר]\u0006 \u0003רבה\u0004 שקנס שנתחייב בו בבית דין \u0003ממונא הוי\u0004 \u0005[ממון הוא]\u0006 לענין \u0003להורישו לבניו\u0004 — לא במקרה מיוחד זה של אונס ומפתה אמר, אלא רק \u0003בשאר קנסות\u0004 שדינם כממון לאחר החיוב בדין, ולפיכך מורישו האב לבניו.","ושואלים: \u0003אלא מעתה\u0004 שהוא לומד מדיוק הלשון \"ונתן\", \u0003גבי\u0004 (אצל, בענין) שור שהמית \u0003עבד, דכתיב\u0004 \u0005[שנאמר\u0006 בעניינו\u0005]:\u0006 \u0003\"כסף שלשים שקלים יתן לאדניו\"\u0004 (שמות כא, לב), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003לא זיכתה תורה לאדון אלא משעת נתינה?!\u0004 ומתרצים: \u0003\"יתן\" לחוד \"ונתן\" לחוד,\u0004 שלשון \"יתן\", שהוא בעתיד, אין משמעה שזוכה רק משעת נתינה, אבל לשון \"נתן\", בעבר, כוונתה שרק לאחר שכבר נתן האונס את הקנס, הרי הוא של האב.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שעיקר ההוכחה היא מלשון \"ונתן\", אם כן מה ששנינו בברייתא למעלה לגבי חיוב קרבן שבועה באונס ומפתה, \u0003תלמוד לומר: \"וכחש\"\u0004 אינו הוכחה כלל לענייננו, והלוא \u0003תלמוד לומר: \"ונתן\" מיבעי ליה\u0004 \u0005[צריך היה]\u0006 לו לומר! שכן אפילו אחר העמדה בדין נחשב כקנס.","\u0003אמר רבא: כי איצטריך\u0004 \u0005[כאשר הוצרך]\u0006 להביא את הראיה מן הפסוק \u0003\"וכחש\"\u0004 — מדובר \u0003כגון שעמדה\u0004 הבת \u0003בדין, ובגרה ומתה.\u0004 והחידוש הוא: \u0003דהתם, כי קא ירית\u0004 \u0005[ששם, כאשר יורש]\u0006 \u0003אביה\u0004 — \u0003מינה דידה קא ירית\u0004 \u0005[ממנה עצמה\u0006 הוא \u0005יורש],\u0006 שכיון שבגרה לא זכה האב בקנס מכוח עצמו והיה צריך להיחשב כשאר ממון שהיא מורישה לו. ולכן צריך לימוד מיוחד, לומר שבכל זאת אינו חייב על ממון זה קרבן שבועה אם נשבע לשקר, מפני שעיקרו קנס.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, אם כן הביטוי הנאמר באותה ברייתא, \u0003\"יצאו אלו שהן קנס\"\u0004 איננו נכון, שכן \u0003ממון הוא\u0004 ולא קנס! \u0003אמר רב נחמן בר יצחק\u0004 פירוש הביטוי הוא: \u0003יצאו אלו שעיקרן קנס,\u0004 כלומר, החיוב מעיקרו בא בגלל קנס.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו: \u0003ר' שמעון פוטר, שאינו משלם קנס על פי עצמו.\u0004 ונדייק מן הלשון: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003לא עמד בדין\u0004 ואינו משלם על פי עצמו, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003עמד בדין,\u0004 ש\u0003משלם על פי עצמו, קרבן שבועה נמי מיחייב\u0004 \u0005[גם כן\u0006 הוא \u0005מתחייב],\u0006 ולא כדברי רבה!","ומשיבים: \u0003ר' שמעון לדבריהם דרבנן\u0004 \u0005[של חכמים]\u0006 \u0003קאמר להו\u0004 \u0005[אומר להם],\u0006 וכך צריך לפרש את דבריו: \u0003לדידי\u0004 \u0005[לשיטתי],\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003עמד בדין רחמנא פטריה\u0004 \u0005[פטרה אותו התורה]\u0006 מקרבן שבועה, וזה נלמד \u0003מ\u0004המלה \u0003\"וכחש...\u0004 בפקדון \u0003\",\u0004 שממנה משתמע שאין חיוב זה אלא בדבר שעיקרו ממון. \u0003אלא לדידכו אודו\u0004 \u0005[לשיטתכם, הודו]\u0006 \u0003לי מיהת\u0004 \u0005[על כל פנים]\u0006 \u0003היכא\u0004 \u0005[היכן,\u0006 כאשר\u0005]\u0006 ש\u0003לא עמד בדין, דכי קא תבע, קנסא קא תבע\u0004 \u0005[שכאשר\u0006 הוא \u0005תובע, קנס\u0006 הוא \u0005תובע],\u0006 שבמקרה כזה גם אתם תסכימו אתו שאין כאן תביעת ממון, אלא קנס."],["\u0003ו\u0004כלל הוא ש\u0003מודה בקנס פטור. ו\u0004מסבירים: \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 \u0003כי קא תבע\u0004 \u0005[\u0006ש\u0005כאשר\u0006 האב \u0005תובע]\u0006 בבית דין — \u0003בושת ופגם קא תבע\u0004 \u0005[הוא תובע]\u0006 ואין עיקר כוונתו לקנס, ואם כן יש כאן תביעת ממון שכיחש בה.","ושואלים: אם כן, לפי הסבר זה \u0003במאי קא מיפלגי\u0004 \u0005[במה\u0006 באיזה ענין \u0005חלוקים\u0006 הם\u0005]?\u0006 \u0003אמר רב פפא: ר' שמעון סבר\u0004 כי \u0003לא שביק איניש מידי דקיץ\u0004 \u0005[אין אדם מניח\u0006 מלתבוע \u0005דבר ש\u0006הוא \u0005קצוב],\u0006 כגון תביעת הקנס, \u0003ותבע מידי דלא קיץ\u0004 \u0005[ותובע דבר שאינו קצוב],\u0006 כגון תביעת בושת ופגם. ומשום כך, תביעה של אונס, בעיקרה היא תביעת הקנס. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי \u0003לא שביק איניש מידי דכי מודי ביה לא מיפטר\u0004 \u0005[אין אדם מניח\u0006 מלתבוע \u0005דבר שכאשר מודה בו אין\u0006 הנתבע \u0005נפטר],\u0006 כמו בושת ופגם \u0003ותבע מידי דכי\u0004 \u0005[ותובע דבר שכאשר]\u0006 \u0003מודה ביה\u0004 \u0005[בו]\u0006 הנתבע \u0003מיפטר\u0004 \u0005[ייפטר],\u0006 ולכן יש לומר שעיקר התביעה היתה לגבי בושת ופגם.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אבינא מרב ששת: בת הניזונת מן האחין.\u0004 כלומר, שאביה מת והאחים מפרנסים אותה ממה שירשו מאביהם — שהאב מתחייב בין שאר תנאי הכתובה לספק מזונות הבת מרכושו — בת זו, \u0003מעשה ידיה למי\u0004 הם שייכים?","האם לומר ש\u0003במקום אב קיימי\u0004 \u0005[עומדים]\u0006 האחים, ו\u0003מה התם\u0004 \u0005[שם]\u0006 כשהאב קיים — \u0003מעשה ידיה לאב, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מעשה ידיה לאחין, או דלמא לא דמי\u0004 \u0005[שמא אין דומה]\u0006 \u0003לאב,\u0004 ומדוע — \u0003התם, מדידיה מיתזנא\u0004 \u0005[שם, משלו\u0006 היא \u0005ניזונה]\u0006 ולכן ראוי שיהיו מעשי ידיה שלו, ואולם \u0003הכא לאו מדידהו מיתזנא\u0004 \u0005[כאן לא משלהם\u0006 היא \u0005ניזונה]\u0006 אלא מן הירושה, ולכן אין להם זכות במעשה ידיה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת: \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005למדתם אותה],\u0006 כלומר, אפשר ללמוד תשובה לשאלה זו מדברי המשנה, ששנינו: \u0003אלמנה ניזונת מנכסי יתומים ומעשה ידיה שלהן.\u0004 הרי שאף שהאלמנה ניזונה על פי תנאי הכתובה, ומקבלת מזונות מן הירושה, מכל מקום מעשי ידיה של היתומים, והוא הדין לבת הניזונה מן האחים.","ודוחים: \u0003מי דמי\u0004 \u0005[האם\u0006 הדבר \u0005דומה]?\u0006 \u0003אלמנתו לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 ואין לו ענין מיוחד \u0003בהרווחה\u0004 ובנוחיות שלה, כלומר, אין לנו הוכחה שרצונו שתחיה ברווחה, ולכן נותן לה בדיוק כפי תנאי הכתובה, ומעשה ידיה ליורשים. ואולם \u0003בתו,\u0004 ודאי \u0003ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003בהרווחה\u0004 שלה, ורוצה שתקבל את הכל בשלימות, ומעשה ידיה יהיו ברשותה להרווחה יתירה.","ושואלים: \u0003למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ש\u0003בתו עדיפא ליה\u0004 \u0005[עדיפה לו]\u0006 \u0003מאלמנתו? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבא אמר ר' יוסי:\u0004 מי שמת והותיר אחריו אלמנה ובת, \u0003עשו\u0004 דין \u0003אלמנה אצל הבת\u0004 שגם לה יש זכות להיזון מן הירושה \u0003כ\u0004דין \u0003בת אצל אחין בנכסין מועטין,\u0004 שאינם מספיקים לפרנס את הבת ואת הבנים במשך שנים עשר חודש,","ו\u0003מה הבת אצל אחין,\u0004 הכלל הוא: \u0003הבת ניזונת\u0004 מן הנכסים, \u0003והאחין\u0004 אם אין להם מה לאכול — ילכו ו\u0003ישאלו\u0004 (יקבצו נדבות) \u0003על הפתחים. אף אלמנה אצל הבת — אלמנה ניזונת, והבת תשאל על הפתחים.\u0004 ומכאן שעדיפה לאדם אלמנתו מאשר בתו! ומסבירים: אין הדברים דומים, ש\u0003לענין\u0004 מניעת \u0003זילותא\u0004 \u0005[זלזול] —\u0006 \u0003אלמנתו\u0004 אכן \u0003עדיפא ליה\u0004 \u0005[עדיפה לו].\u0006 שבמקרה שאחת מהן צריכה לחזור על הפתחים — מעדיף הוא שתהיה זו בתו ולא אלמנתו. אולם \u0003לענין הרווחה\u0004 ונוחיות — \u0003בתו עדיפא ליה\u0004 \u0005[עדיפה לו].\u0006","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף\u0004 על מסקנתו של רב ששת שמעשה ידיה לאחין, שנינו במשנתנו: \u0003מעשה ידיה ומציאתה\u0004 של האב \u0003אף על פי שלא גבתה,\u0004 ואם \u0003מת האב — הרי הן של אחין,\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שזכה האב במעשה ידיה \u0003בחיי האב\u0004 ומשמת מורישו לבניו, \u0003הא\u0004 \u0005[הרי]\u0006 שכר מעשה ידיה שעשתה \u0003לאחר מיתת האב — לעצמה\u0004 הוא. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן גם \u0003ב\u0004בת כזו ש\u0003ניזונת\u0004 מן הנכסים? ודוחים: \u0003לא,\u0004 מדובר כאן \u0003בשאינה ניזונת\u0004 מן הנכסים, והיא מפרנסת את עצמה ממעשה ידיה.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בשאינה ניזונת — מאי למימרא\u0004 \u0005[מה\u0006 יש \u0005לומר,\u0006 להשמיענו\u0005]\u0006 בזה? הלא מובן מאליו שכך הוא. ש\u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003יכול הרב\u0004 (האדון) \u0003לומר לעבד \"עשה עמי\u0004 (עבוד אצלי) \u0003ואיני זנך\",\u0004 שאין על האדון חובה הלכתית לפרנס את העבד. אולם \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003בעבד כנעני,\u0004 ש\u0003לא כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003\"עמך\",\u0004 ואין עליו חובה לפרנסו.","\u0003אבל עבד עברי דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003\"עמך\"\u0004 (דברים טו, טז), שמשמעות הכתוב שהעבד העברי חי עם אדוניו כשווה לו — \u0003לא,\u0004 שאין האדון רשאי לתבוע ממנו לעבוד אלא אם כן מפרנס אותו. \u0003כל שכן בתו,\u0004 שוודאי אי אפשר לומר שנערה זו תעבוד, והאחים יקבלו את דמי עבודתה ולא יפרנסו אותה!","\u0003אמר רבה בר עולא: לא נצרכה אלא להעדפה.\u0004 שאין מדובר כאן שהאחים יטלו את כל מעשה ידיה ולא יתנו לה כלום, אלא השאלה היא כאשר מרובה שכר מעשה ידיה יותר ממזונותיה, ונשאר לה עודף מסויים, למי מגיע הסכום הזה. \u0003אמר רבא\u0004 כנגד דברי רבה בר עולא: וכי \u0003גברא רבה\u0004 \u0005[אדם גדול]\u0006 \u0003כרב יוסף לא ידע דאיכא\u0004 \u0005[אינו יודע שיש]\u0006 אפשרות להסביר ב\u0003העדפה, וקמותיב תיובתא\u0004 \u0005[ומקשה קושיה\u0006 על רב ששת\u0005]?\u0006 — ודאי לא ייתכן לומר כך.","\u0003אלא אמר רבא: רב יוסף מתניתין גופא קשיא ליה\u0004 \u0005[המשנה שלנו עצמה\u0006 היתה \u0005קשה לו]\u0006 ומשום כך הגיע למסקנתו. \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]:\u0006 \u0003מעשה ידיה ומציאתה, אף על פי שלא גבתה.\u0004 ודקדק בלשון המשנה: \u0003מציאתה ממאן גביא\u0004 \u0005[ממי\u0006 היא \u0005גובה],\u0006 הרי אין כאן מקום למושג \"גביה\"?","\u0003אלא לאו הכי קאמר\u0004 \u0005[\u0006האם \u0005לא כך אמר],\u0006 כך צריך לפרש את הדברים: \u0003מעשה ידיה\u0004 עצמם הם \u0003כמציאתה, מה מציאתה בחיי האב\u0004 שייכת \u0003לאב,\u0004 ו\u0003לאחר מיתת האב\u0004 שייכת \u0003לעצמה, אף מעשה ידיה נמי\u0004 \u0005[גם כן]:\u0006 \u0003בחיי האב\u0004 שייכים \u0003לאב,\u0004 ו\u0003לאחר מיתת האב\u0004 שייכים \u0003לעצמה,\u0004 גם כשניזונת מהירושה. ומסכמים: אכן, מתוך דיוק זה \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא, שמדובר במעשה ידיה עצמם ולא בהעדפה, ושלא כדברי רב ששת.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 דבר זה בהלכה בשם אמוראים, ש\u0003אמר רב יהודה אמר רב: בת הניזונת מן האחין\u0004 בכל זאת \u0003מעשה ידיה לעצמה. אמר רב כהנא: מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בעבדים: \u0003\"והתנחלתם אתם לבניכם אחריכם\"\u0004 (ויקרא כה, מו) ואומרים שלשון זו באה להדגיש: \u0003אותם,\u0004 את העבדים הכנענים בלבד אתם מנחילים \u0003לבניכם, ולא\u0004 את \u0003בנותיכם לבניכם. מגיד\u0004 כתוב זה \u0003שאין אדם מוריש\u0004 כל \u0003זכות\u0004 שיש לו אצל \u0003בתו, לבנו.\u0004 שהזכויות שהיו לאב בבתו, הן זכויות אישיות, ואולם אינן דבר שמעביר בירושה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבה:\u0004 מניין יודע אתה שהכוונה היא לענין זכות האב במעשה ידיה, \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\u0003בפיתוי הבת, וקנסות וחבלות\u0004 שאירעו לה \u0003הכתוב מדבר,\u0004 שאין זכות האב בקנסות ובפיצויים המגיעים לבת עוברת ליורשיו אחריו. \u0003ו\u0004אכן \u0003כן תנא\u0004 \u0005[שנה\u0006 במפורש\u0005]\u0006 \u0003רב חנינא: בפתוי הבת וקנסות וחבלות הכתוב מדבר!\u0004","על לשון זו שואלים: \u0003חבלות,\u0004 הלא \u0003צערא דגופא נינהו\u0004 \u0005[צער הגוף הן]\u0006 ואנו יודעים שהפיצוי על דבר שגרם צער לבת איננו שייך לאב, והוא רק שומר אותו עבורה, ואם כן, לא היה מקום להזכיר כאן חבלות. \u0003אמר ר' יוסי בר חנינא:\u0004"],["\u0003שפצעה בפניה,\u0004 והחובל בה משלם גם על הפחת שנפחת ערכה לגבי נישואין, וסכום זה, ככסף קידושיה, שייך לאב. \u0003אמר רב זירא אמר רב מתנה אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים],\u0006 \u0003אמר רבי זירא אמר רב מתנה אמר רב: בת הניזונת מן האחין — מעשה ידיה לעצמה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והתנחלתם אתם לבניכם אחריכם\"\u0004 (ויקרא כה, מו), ללמד: \u0003אותם,\u0004 את העבדים, אתם מנחילים \u0003לבניכם, ולא\u0004 את \u0003בנותיכם לבניכם, מגיד\u0004 הכתוב \u0003שאין אדם מוריש זכות\u0004 שיש לו אצל \u0003בתו לבנו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אבימי בר פפי\u0004 לר' זירא: \u0003שקוד אמרה\u0004 את ההלכה הזו. ושואלים: \u0003שקוד מנו\u0004 \u0005[מיהו]?\u0006 הרי זה כינוי ל\u0003שמואל,\u0004 ואולם \u0003הא\u0004 \u0005[הרי]\u0006 \u0003רב אמרה\u0004 שהרי כפי שראינו יש מקור נוסף לכך שרב אמר הלכה זו! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 שכך רצה אבימי לומר: \u0003אף שקוד אמרה.\u0004 כלומר, גם שמואל אמר הלכה זו והסכים לה. \u0003אמר מר בר אמימר לרב אשי: הכי אמרי נהרדעי\u0004 \u0005[כך אומרים\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב ששת\u0004 שבת הניזונת מן האחים מעשה ידיה שלהם. \u0003רב אשי אמר: הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב\u0004 שמעשה ידיה לעצמה. ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב.\u0004","\u0003המארס את בתו\u0004 קטנה \u0003וגרשה\u0004 בעלה, ואחר כך \u0003אירסה\u0004 אביה לאחר \u0003ונתארמלה\u0004 (נתאלמנה) — \u0003כתובתה\u0004 של הבת גם מהבעל השני \u0003שלו,\u0004 של האב היא. אבל אם \u0003השיאה וגרשה\u0004 בעלה, ואחר כך \u0003השיאה ונתארמלה — כתובתה\u0004 גם מהנישואין הראשונים \u0003שלה. ר' יהודה אומר:\u0004 הכתובה \u0003הראשונה של אב. אמרו לו: (אם) משהשיאה\u0004 בפעם הראשונה, \u0003אין\u0004 עוד \u0003לאביה רשות בה.\u0004","מדייקים בלשון המשנה: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003השיאה וגרשה,\u0004 ואחר כך \u0003השיאה\u0004 פעם אחרת \u0003ונתארמלה, אבל\u0004 אם \u0003נתארמלה תרי זמני\u0004 \u0005[שתי פעמים],\u0006 \u0003תו לא חזיא לאינסובי\u0004 \u0005[שוב אינה ראויה להינשא],\u0006 משום שאנו חוששים שהיא בכלל אשה \"קטלנית\", שגורמת בדרך כלשהי למות בעליה. ומעירים: \u0003ואגב אורחיה קא סתים לן\u0004 \u0005[ואגב דרכו סתם לנו]\u0006 ה\u0003תנא כ\u0004שיטת \u0003רבי\u0004 ש\u0003אמר: בתרי זמני הויא\u0004 \u0005[בשתי פעמים היא\u0006 נעשית\u0005]\u0006 \u0003חזקה,\u0004 ולכן לאחר שמתו שני הבעלים שלה הריהי כבר בחזקת \"קטלנית\", ולא כשיטה האומרת שחזקה היא רק בשלוש פעמים.","שנינו במשנה ש\u0003ר' יהודה אומר:\u0004 הכתובה \u0003הראשונה של אב.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה?\u0004 ומסבירים: \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003הואיל ומשעת אירוסין,\u0004 כשהתחייב הבעל הראשון בכתובה, \u0003זכה בהן האב\u0004 בדמי הכתובה, שעדיין היתה הבת ברשותו, משום כך אף שקבלה את הכתובה לאחר שנישאה ונתגרשה, ונחשבת כעומדת בזכות עצמה, מכל מקום זכה כבר האב בכתובה מזמן שהתארסה, שהיתה הבת עוד ברשותו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 מברייתא, \u0003ר' יהודה אומר:\u0004 הכתובה \u0003הראשונה של אב. ומודה ר' יהודה במארס את בתו כשהיא קטנה ובגרה, ואחר כך נשאת, שאין לאביה\u0004 עוד \u0003רשות בה,\u0004 משעה שבגרה, ואין לו גם זכות בכתובתה. ולפי ההסבר שאמרנו \u0003אמאי\u0004 \u0005[מדוע]\u0006 יודה ר' יהודה? — \u0003הכא נמי לימא\u0004 \u0005[כאן גם כן יאמר]:\u0006 \u0003הואיל ומשעת אירוסין זכה בהן האב,\u0004 תהא אם כן הכתובה לאב, למרות שנישאה לאחר בגרותה.","\u0003אלא\u0004 יש לחזור ממה שאמרנו, ולומר כי \u0003אי אתמר, הכי אתמר\u0004 \u0005[אם נאמר\u0006 הדבר, \u0005כך נאמר]:\u0006 \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003הואיל וברשותו נכתבין\u0004 הסכומים שבכתובה, שהרי כותבים כתובה קודם הנישואין, ואז היתה הבת עדיין ברשותו של האב, וזכה בה האב. ולפי זה מובן הדין כשבגרה לפני שנישאה, כי כיון שלמעשה כותבים את הכתובה רק סמוך לנישואין, ואז כבר היתה בוגרת — לא זכה האב בכתובה.","בהמשך לדברים שאמרנו קודם שואלים: כיון שהסברנו שאף לדעת ר' יהודה כתובה נקנית מזמן הנישואין שהוא זמן הכתיבה ולא משעת אירוסין, למרות שהוסכם על הסכום באותה שעה, \u0003ומיגבא, מאימת גביא\u0004 \u0005[ולגבות, מאימתי\u0006 היא \u0005גובה],\u0006 האם אומרים שקנין הכתובה הוא בכל זאת מזמן האירוסין, ויכולה לגבות כתובתה מנכסי הבעל שמכר מאותו זמן ואילך, או שמא אינו אלא מן הנישואין ממש,","\u0003אמר רב הונא: מנה\u0004 (לבעולה) או \u0003מאתים\u0004 (לבתולה) שהם עיקר תקנת הכתובה מדברי חכמים, גובה אשה \u0003מן האירוסין,\u0004 שאנחנו מניחים שבזמן האירוסין כבר נקנה סכום זה, \u0003ותוספת\u0004 שהוסיף הבעל מדעתו גובים מן הלקוחות רק \u0003מן\u0004 זמן \u0003הנשואין. ורב אסי אמר: אחד זה ואחד זה\u0004 גובים רק \u0003מן הנשואין.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב הונא הכי\u0004 \u0005[כך]\u0006 שגובה עיקר כתובה מזמן האירוסין? \u0003והאתמר\u0004 \u0005[והרי נאמר]\u0006 שדנו בשאלה הבאה: \u0003הוציאה עליו\u0004 אשתו בזמן הגירושין \u0003שתי כתובות\u0004 שכתב לה בזמנים שונים, \u0003אחת של מאתים, ואחת של שלש מאות. ואמר רב הונא: באתה\u0004 (באה) \u0003לגבות,\u0004 כיון שיכולה לגבות רק כתובה אחת, אם רוצה לגבות כתובה ראשונה של \u0003מאתים — גובה מזמן ראשון,\u0004 כאשר נכתבה כתובה זו, ואם רוצה לגבות \u0003שלש מאות — גובה מזמן שני.\u0004","\u0003ואם איתא\u0004 \u0005[ואם יש],\u0006 כלומר, אם אנחנו מניחים שלשיטת רב הונא אפשר לחלק, שאת עיקר החיוב גובה מזמן אחד ואת התוספת מזמן שני, \u0003תיגבי\u0004 \u0005[תגבה]\u0006 אם כן \u0003מאתים מזמן ראשון,\u0004 שהרי מאותה שעה כבר זכתה בעיקר הכתובה, \u0003ומאה\u0004 הנוספים הנקובים בכתובה השניה — תגבה \u0003מזמן שני\u0004 כתוספת לכתובתה.","ודוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 אם אתה סבור שהכתובה השניה היא התחייבות נבדלת שאינה קשורה בכתובה הראשונה, אם כן \u0003תיגבי\u0004 \u0005[תגבה]\u0006 \u0003חמש מאות כולם,\u0004 כלומר, את סכום שתי הכתובות ביחד. כיצד? — \u0003מאתים\u0004 תגבה \u0003מזמן ראשון,\u0004 ו\u0003תלת מאה\u0004 \u0005[שלוש מאות]\u0006 \u0003מזמן שני!\u0004","\u0003אלא\u0004 ודאי חייבים להסביר כי \u0003חמש מאות מאי טעמא לא גביא\u0004 \u0005[מה טעם אינה גובה]\u0006 \u0003כיון שלא כתב לה\u0004 בכתובה השניה \u0003\"צביתי ואוסיפית לך תלת מאה\u0004 \u0005[רציתי והוספתי לך שלוש מאות]\u0006 על ה\u0003מאתים\u0004 הראשונים \u0003\",\u0004 משמע שלא נתכוון לכתוב לה תוספת לכתובתה, אלא \u0003הכי קאמר\u0004 \u0005[כך אמר לה]\u0006 \u0003לה,\u0004 כך היתה כוונתו; \u0003אי\u0004 \u0005[אם]\u0006 \u0003מזמן ראשון גביאת\u0004 \u0005[את גובה] —\u0006 \u0003גביא\u0004 \u0005[גובה]\u0006 את ה\u0003מאתים, אי\u0004 \u0005[אם]\u0006 \u0003מזמן שני גביאת\u0004 \u0005[את גובה] —\u0006 \u0003גביא תלת מאה\u0004 \u0005[גובה\u0006 את \u0005שלש מאות]\u0006"],["\u0003הכא נמי היינו טעמא דלא גביא\u0004 \u0005[כאן גם כן זהו הטעם שאינה גובה]\u0006 רק את המאה הנוספים מזמן שני, מכיון ש\u0003לא כתב לה\u0004 בכתובה השניה \u0003\"אוסיפית\u0004 \u0005[הוספתי]\u0006 \u0003לך מאה\u0004 על ה\u0003מאתים\",\u0004 משמע שאין כאן תוספת על הכתובה הקיימת אלא \u0003אחולי אחילתיה לשעבודא קמא\u0004 \u0005[מחלה על השעבוד הראשון]\u0006 והסכימה לקבל את השטר השני, שתחולתו מזמן מאוחר יותר.","שיטת רב הונא הוסברה איפוא, ועכשיו מבררים נושא כללי יותר הקשור בדבריו האחרונים, \u0003אמר מר\u0004 \u0005[החכם],\u0006 רב הונא שאמר באותו דיון: \u0003אי בעיא\u0004 \u0005[אם רוצה] —\u0006 \u0003בהאי גביא\u0004 \u0005[בזה\u0006 היא \u0005גובה],\u0006 \u0003אי בעיא\u0004 \u0005[אם רוצה] —\u0006 \u0003בהאי גביא\u0004 \u0005[בזה\u0006 היא \u0005גובה].\u0006 ושואלים: \u0003לימא פליגא\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005חלוקה]\u0006 דעה זו על דעת \u0003רב נחמן?\u0004 ש\u0003אמר רב נחמן: שני שטרות היוצאין בזה אחר זה\u0004 על אותו דבר, כגון שני שטרות של העברת בעלות על שדה אחד שזמנם שונה — \u0003ביטל\u0004 שטר \u0003שני\u0004 המאוחר יותר \u0003את הראשון.\u0004 ואף כאן תבטל הכתובה השניה את הראשונה לגמרי!","ודוחים: \u0003לאו מי איתמר עלה\u0004 \u0005[האם לא נאמר עליה],\u0006 על הלכה זו של רב נחמן, \u0003אמר רב פפא: ומודה רב נחמן דאי אוסיף ביה דיקלא\u0004 \u0005[שאם הוסיף בו דקל]\u0006 בשטר השני, כגון שהקנה למקבל דקל נוסף, משמע כי \u0003לתוספת כתביה\u0004 \u0005[כתבו],\u0006 והשטר השני לא ביטל את הראשון, אלא הוסיף עליו. \u0003הכא נמי הא אוסיף\u0004 \u0005[כאן גם כן הרי הוסיף]\u0006 \u0003לה מידי\u0004 \u0005[דבר],\u0006 שהרי סכום הכתובה השניה גדול יותר!","כיון שהוזכרה הלכה זו של רב נחמן דנים ב\u0003גופא\u0004 של ההלכה. \u0003אמר רב נחמן: שני שטרות היוצאין בזה אחר זה\u0004 — \u0003ביטל שני את הראשון. אמר רב פפא: ומודה רב נחמן דאי אוסיף ביה דיקלא\u0004 \u0005[שאם הוסיף בו דקל] —\u0006 \u0003לתוספת כתביה\u0004 \u0005[כתבו].\u0006 ומבארים את פרטי ההלכה. \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 שאם השטר ה\u0003ראשון\u0004 שכתב על השדה היה \u0003במכר, ו\u0004ה\u0003שני\u0004 נכתב על אותו שדה עצמו \u0003במתנה,\u0004 אין זה ביטולו של הראשון, אלא \u0003ליפות כחו\u0004 של המקבל \u0003הוא\u0004 ש\u0003כתב ליה\u0004 \u0005[לו]\u0006 שטר נוסף בלשון מתנה \u0003משום דינא דבר מצרא\u0004 \u0005[דין\u0006 של \u0005בן המיצר],\u0006 כי בעל שדה המצוי בצד (על המיצר) של שדה שמוכרים אותו יש לו זכות קדימה לקנות תחילה שדה זה, ודין זה הוא רק כאשר השדה נמכר, אבל אם נותן בעל השדה את שדהו במתנה, אין כל זכות לבן המיצר, ולכן אפשר לומר שהמקנה כתב שטר מתנה כדי להסיר מן המקבל ערעור על בן המיצר.","\u0003וכל שכן\u0004 אם כתב לו שטר \u0003ראשון במתנה ושני במכר, דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 ש\u0003משום דינא\u0004 \u0005[דין]\u0006 של \u0003בעל חוב הוא\u0004 ש\u0003כתב כן.\u0004 שחשש שמא יבוא בעל חוב ויטרוף מן המקבל, ולא תהיינה לו כל זכויות, ולכן כתב הנותן שטר מכר נוסף כדי שתהיה לו זכות לחזור ולגבות ממנו סכום זה.","\u0003אלא אי\u0004 \u0005[אם]\u0006 \u0003שניהם במכר\u0004 או \u0003שניהם במתנה — ביטל שני את הראשון.\u0004 ויש לברר \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לכך שהשטר הראשון בטל? ובזה נחלקו אמוראים. \u0003רפרם אמר: אימר אודויי אודי ליה\u0004 \u0005[אמור\u0006 ש\u0005הודה לו]\u0006 בעל השטר שהיה בשטר הראשון פגם, כגון זיוף, ולכן כתב לו שטר אחר כשר. \u0003רב אחא אמר: אימר אחולי אחליה לשיעבודיה\u0004 \u0005[אמור\u0006 ש\u0005מחל לו\u0006 הקונה \u0005את השעבוד]\u0006 מהזמן הראשון, והסכים שיחול השעבוד רק מזמנו של השטר השני.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]\u0006 אם זה או זה הוא הטעם? ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לכמה דברים: \u0003אורועי סהדי\u0004 \u0005[להרע\u0006 כוחם של ה\u0005עדים],\u0006 שלדברי רפרם, שיש לחשוש שהשטר הראשון מזוייף, הרי גם חתימת העדים שעליו מפוקפקת, ויש לחשוש לעדותם וחתימתם גם בעדות אחרת.","\u0003ולשלומי פירי\u0004 \u0005[ו\u0006כן לענין \u0005לשלם\u0006 את ה\u0005פירות]\u0006 של הנכסים שהיו בין זמן שטר ראשון לזמנו של שני. שלדעת רפרם, כיון שהשטר הראשון מזוייף, צריך הלוקח לשלם לבעלים את הפירות שאכל עד זמן כתיבת השטר השני. ואילו לדעת רב אחא, אמנם מחל הלוקח על השעבוד מהזמן הראשון, אבל מה שלקח — לקח. \u0003ו\u0004כן \u0003לטסקא\u0004 \u0005[ל\u0006תשלום \u0005מיסי קרקע],\u0006 שאם השטר הראשון מזוייף, צריך בעל השדה הקודם לשלם את המיסים, שחלו על השדה במשך הזמן הזה.","כל הדיונים הללו היו בעקבות המחלוקת בין רב הונא ורב אסי לענין זמן גביית הכתובה כאשר באה האשה לגבות מן הנכסים. ושואלים לגופה של אותה בעיה: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על ה\u0003כתובה,\u0004 כלומר, מה הדין במחלוקת זו? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ש\u0003אמר רב יהודה אמר שמואל משום ר' אלעזר בר' שמעון: מנה\u0004 הניתן ככתובה לבעולה ו\u0003מאתים\u0004 הניתנים לבתולה, זמן גבייתם \u0003מן האירוסין, ו\u0004כל \u0003תוספת\u0004 שעל זה — \u0003מן הנישואין.\u0004","\u0003וחכמים אומרים: אחד זה ואחד זה — מן הנישואין,\u0004 ואם כן מחלוקת זו היא מחלוקת תנאים. ולפי כללי ההלכה יש לסכם: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003אחד זה ואחד זה — מן הנישואין,\u0004 כדעת חכמים.","\u0003הגיורת שנתגיירה בתה עמה ו\u0004אחר כך \u0003זינתה\u0004 הבת כשהיתה מאורסת בעודה נערה — \u0003הרי זו\u0004 נידונת \u0003בחנק,\u0004 ולא בסקילה כנערה מאורסה בת ישראל, ו\u0003אין לה לא פתח בית האב,\u0004 שאין צורך להוציא אותה אל פתח אביה לסקול אותה שם כפי שמביאים נערה ארוסה שזינתה (\"והוציאו את הנערה אל פתח בית אביה וסקלוה אנשי עירה באבנים\". דברים כב, כא), \u0003ולא מאה סלע,\u0004 שבת ישראל שהוציא עליה בעלה שם רע שזינתה, והוכח ששיקר, צריך הבעל לשלם מאה סלע, ולזו אין משלמים. כי בהלכות אלה (דברים כב, יג-כא) נאמר כמה פעמים \"בישראל\", ללמד שדינים אלה מיוחדים דווקא לאלה שהן מזרע ישראל.","אולם אם \u0003היתה הורתה\u0004 של הבת \u0003שלא בקדושה,\u0004 כלומר, הריונה התחיל כשאמה היתה עדיין גויה, \u0003ו\u0004אולם \u0003לידתה בקדושה,\u0004 שהאם נתגיירה בזמן ההריון — \u0003הרי זו\u0004 הבת, אם זינתה בהיותה נערה מאורסה — \u0003בסקילה, ו\u0004אולם \u0003אין לה לא פתח בית האב\u0004 כשנידונה למוות, \u0003ולא מאה סלע\u0004 אם התברר שבעלה הוציא עליה שם רע. ואם \u0003היתה הורתה ולידתה בקדושה,\u0004 שנתגיירה אימה טרם הרותה לה \u0003— הרי היא כבת ישראל לכל דבריה.\u0004","ובכלל בדין זה של נערה מאורסה שזינתה: אם \u0003יש לה\u0004 לבת שזינתה \u0003אב ואין לה פתח בית האב,\u0004 כגון שאין לאב בית משלו, או \u0003יש לה פתח בית האב ואין לה אב,\u0004 שמת האב — \u0003הרי זו בסקילה,\u0004 כי \u0003לא נאמר \"פתח בית אב\"\u0004 בכתוב \u0003אלא למצוה,\u0004 אבל לא לומר שאין מקיימים את שאר הדינים האמורים בה אם לא נתקיים פרט זה."],["\u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שגיורת שהורתה שלא בקדושה ולידתה בקדושה נידונת בסקילה? \u0003אמר ריש לקיש,\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004וסקלוה אנשי עירה באבנים \u0003ומתה\"\u0004 (דברים כב, כא), ולשון יתירה זו (\"ומתה\") באה \u0003לרבות הורתה שלא בקדושה ולידתה בקדושה.\u0004","ושואלים: \u0003אי הכי מילקא נמי נילקי\u0004 \u0005[אם כך\u0006 שמרבה אותה הכתוב כישראל, \u0005שילקה\u0006 הבעל \u0005גם כן]\u0006 על שהוציא עליה שם רע, \u0003ומאה סלע נמי לשלם\u0004 \u0005[גם כן שישלם]!\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ומתה\"\u0004 לומר ש\u0003למיתה נתרבתה ולא לקנס.\u0004 ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שבא הכתוב הזה \u0003לרבות\u0004 רק את זו ש\u0003הורתה ולידתה בקדושה?\u0004 ומשיבים: \u0003ההיא, ישראלית מעלייתא\u0004 \u0005[מעולה]\u0006 \u0003היא\u0004 ואין הבדל בינה ובין כל ישראלית אחרת.","ושואלים מצד אחר: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שבא הכתוב \u0003לרבות\u0004 גם את זו ש\u0003הורתה ולידתה שלא בקדושה!\u0004 ומשיבים: \u0003אם כן\u0004 אתה אומר, הרי מה שנאמר שם \u0003\"בישראל\"\u0004 (דברים כב, כא) \u0003מאי אהני ליה\u0004 \u0005[מה הועיל לו],\u0006 שהרי לשון זו באה לומר שאין דין זה נוהג אלא בישראלית, ובודאי לא בא הכתוב אלא למעט את זו שהורתה שלא בקדושה ולידתה בקדושה.","\u0003אמר ר' יוסי בר חנינא: המוציא שם רע על היתומה — פטור, שנאמר: \"\u0004וענשו אותו מאה כסף \u0003ונתנו לאבי הנערה\"\u0004 (דברים כב, יט) — \u0003פרט לזו שאין לה אב.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003ר' יוסי בר אבין, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' יוסי בר זבידא:\u0004 הלא נאמר במפותה \u0003\"אם מאן ימאן אביה\u0004 לתתה לו כסף ישקול כמהר הבתולות\u0003\"\u0004 (שמות כב, טז), ולמדו כי לשון כפולה זו (\"מאן ימאן\") באה \u0003לרבות יתומה לקנס,\u0004 שאף אם אין לה אב והיא ממאנת להינשא לו, משלם המפתה קנס, אלו \u0003דברי ר' יוסי הגלילי.\u0004 משמע שגם אם אין לה אב, אין בזה עיכוב לגבי חיוב קנס!","\u0003הוא מותיב לה והוא מפרק לה\u0004 \u0005[הוא מקשה אותה\u0006 קושיה \u0005והוא מתרץ אותה],\u0006 שר' יוסי הגלילי מדבר \u0003בבא עליה ואחר כך נתיתמה\u0004 וכיון שבשעת מעשה היה לה אב, חל עליו חיוב הקנס.","\u0003רבא אמר\u0004 וחלק על ר' יוסי בר חנינא, ולדעתו המוציא שם רע על היתומה \u0003חייב. ממאי\u0004 \u0005[ממה]\u0006 הוא מסיק זאת — \u0003מדתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 החכם \u0003אמי:\u0004 מהמלה \"בישראל\" נלמד כי רק \u0003בתולת ישראל\u0004 בכלל דין זה \u0003ולא בתולת גרים.\u0004","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 \u0003כי האי גוונא\u0004 \u0005[כגון זה]\u0006 \u0003בישראל מיחייב\u0004 \u0005[הוא חייב],\u0006 כלומר, שגם אם אין לה אב חייב לשלם, \u0003היינו דאיצטריך קרא למעוטי\u0004 \u0005[זהו שהוצרך הכתוב למעט]\u0006 \u0003גרים,\u0004 כי כל גיורת היא בגדר יתומה, שכן הקשר שהיה לה עם הוריה בהיותה גויה מנותק עם גיורה, והריהי כמי שאין לה אב כלל. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003בישראל כהאי גוונא\u0004 \u0005[כגון זה]\u0006 \u0003פטור, השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003בישראל פטור\u0004 עליה, \u0003בגרים מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר פרשה מיוחדת שאין להם קנס?!","\u0003אמר ריש לקיש: המוציא שם רע על הקטנה — פטור, שנאמר: \"ונתנו לאבי הנערה\" \"נערה\"\u0004 בכתיב \u0003מלא\u0004 (בה\"א בסוף המלה) \u0003דבר הכתוב,\u0004 שלא כמו בהרבה מקומות אחרים במקרא — למעט קטנה שלא הגיעה עדיין לגיל הנערות.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אחא בר אבא: טעמא דכתיב\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שכתוב]\u0006 \u0003בה \"הנערה\"\u0004 בכתיב מלא, \u0003הא לאו הכי\u0004 \u0005[הרי לולא זה]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003אפילו קטנה\u0004 בכלל דינים אלה?! אולם דבר זה לא ייתכן מסיבה אחרת כי \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 שם \u0003\"ואם אמת היה הדבר הזה לא נמצאו בתולים לנערה. והוציאו את הנערה אל פתח בית אביה וסקלוה\"\u0004 (דברים כב, כ-כא) \u0003וקטנה\u0004 הרי \u0003לאו בת עונשין היא!\u0004 ואם כן, מן ההכרח לומר לפי הענין שמדובר בנערה דווקא ולא בקטנה שאינה בת עונשין, ואין צורך בדרשת הכתיב המלא!","\u0003אלא,\u0004 צריך לומר שהכתיב המלא בא ללמד דין אחר: \u0003כאן\u0004 מובן מתוך הענין שמדובר בנערה דווקא, ולכן כתוב, \u0003\"נערה\"\u0004 מלא, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כל מקום שנאמר \"נער\"\u0004 בכתיב חסר — \u0003אפילו קטנה במשמע,\u0004 ולא בא אלא להוציא בוגרת.","\u0003תני\u0004 \u0005[שנה]\u0006 החכם \u0003שילא\u0004 ברייתא זו: \u0003שלש מדות בנערה\u0004 לענין מוציא שם רע: \u0003באו לה עדים בבית חמיה,\u0004 כלומר, כשהיתה כבר נשואה, והעידו \u0003שזינתה בבית אביה\u0004 בעודה ארוסה —"],["\u0003סוקלין אותה על פתח בית אביה, כלומר,\u0004 בא הדבר לומר: \u0003ראו גידולים שגידלתם. באו לה עדים בבית אביה\u0004 קודם נשואיה, והעידו \u0003שזינתה בבית אביה — סוקלין אותה על פתח שער העיר,\u0004 כדין כל ארוסה שזינתה. \u0003סרחה\u0004 (חטאה) בזנות בהיותה נערה \u0003ולבסוף בגרה — תידון בחנק\u0004 כאשת איש.","ושואלים על ההלכה האחרונה: \u0003למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 שב\u0003כל היכא דאשתני גופא אישתני קטלא\u0004 \u0005[מקום שהשתנה הגוף\u0006 לאחר החטא \u0005השתנתה\u0006 גם \u0005המיתה]?\u0006 \u0003ורמינהי\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003נערה המאורסה שזינתה, ומשבגרה הוציא עליה\u0004 בעלה \u0003שם רע — הוא אינו לוקה, ואינו נותן מאה סלע,\u0004 מפני שנאמר בכתוב \"נערה\" דווקא, ו\u0003היא וזוממיה מקדימין לבית הסקילה,\u0004 כלומר, הם נסקלים למרות שאין במקרה זה תשלום קנס.","ובראשונה תוהים על הלשון: \u0003היא וזוממיה סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 כיצד ייתכן הדבר? שהרי אם יתברר שהעדים עדי אמת והיא אכן חטאה — היא לבדה נסקלת. ואם מתברר שהם עדים זוממים והיא לא חטאה — הרי הם נסקלים והיא אינה נסקלת! \u0003אלא\u0004 צריך לתקן ולומר: \u0003או היא או זוממיה מקדימין לבית הסקילה.\u0004 ומכל מקום משמע מכאן לענייננו שאף על פי שהשתנה גופה, מפני שבגרה, מכל מקום לא השתנתה מיתתה!","\u0003אמר רבא: מוציא שם רע קאמרת\u0004 \u0005[אומר אתה]?\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מוציא שם רע\u0004 ש\u0003חידוש הוא\u0004 ויש בדין זה דברים שאינם דומים להלכות הכלליות, \u0003דהא\u0004 \u0005[שהרי]\u0006 אשה ש\u0003נכנסה לחופה ולא נבעלה\u0004 עדיין, \u0003בעלמא\u0004 \u0005[בדרך כלל],\u0006 \u0003ו\u0004אם \u0003זינתה\u0004 לאחר נישואיה — נידונה \u0003בחנק,\u0004 שמכניסתה לחופה נחשבת כאשה נשואה, \u0003ואילו מוציא שם רע,\u0004 אף על פי שכבר נכנסה לחופה, בשעת הוצאת השם רע, אם זינתה טרם כניסתה לחופה, הריהי נידונת \u0003בסקילה,\u0004 ולא השתנתה מיתתה לחנק.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבא: דלמא כי חדית רחמנא היכא\u0004 \u0005[שמא כאשר חידשה תורה\u0006 במוציא שם רע, הרי זה \u0005במקום]\u0006 ש\u0003לא אישתני גופא\u0004 \u0005[השתנה הגוף\u0006 שלה\u0005],\u0006 שאף שנכנסה לחופה, מכל מקום נשארה כפי שהיתה נערה בתולה, \u0003אבל היכא דאישתני גופא\u0004 \u0005[היכן שהשתנה גופה],\u0006 בבגרות, \u0003לא חדית רחמנא\u0004 \u0005[חידשה תורה],\u0006 ותידון בחנק כאשת איש!","\u0003אלא אמר רב נחמן בר יצחק:\u0004 שאלה זו אם \u0003אישתני\u0004 \u0005[השתנה]\u0006 הדין כאשר השתנה הגוף או \u0003לא אישתני\u0004 \u0005[השתנה],\u0006 \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 נאמר בתורה כי כהן גדול או מלך מביאים קרבן מיוחד על שחטאו בשגגה (ויקרא ד, ג-יב, ויקרא כב-כו), אולם אם \u0003חטאו עד שלא נתמנו, ונתמנו,\u0004 ונודע להם חטאם לאחר המינוי, \u0003הרי הן כהדיוטות\u0004 ומביאים כבשה או שעירה כשאר הדיוט שחטא.","\u0003ר' שמעון אומר: אם נודע להם\u0004 החטא \u0003עד שלא נתמנו,\u0004 אף על פי שנתמנו לפני שהביאו קרבן — \u0003חייבים\u0004 להביא קרבן כהדיוט, אבל אם נודע להם \u0003משנתמנו — פטורים\u0004 מקרבן לגמרי. כי מאחר שנשתנתה דרגתם ונשתנה קרבנם, בטל מהם חיוב קרבן ראשון לגמרי. הרי שר' שמעון סבור כי שינוי שחל באדם משנה את דינו למפרע בנוגע לעבירות שעבר במצב אחר. ודומה הדבר לענייננו, שישתנה דין נערה ארוסה שזינתה והתבגרה קודם שנודע הדבר."],["\u0003אימור דשמעינן ליה\u0004 \u0005[אמור ששמענו אותו]\u0006 את \u0003ר' שמעון דאזיל\u0004 \u0005[שהולך]\u0006 \u0003אף בתר\u0004 \u0005[אחר]\u0006 \u0003ידיעה,\u0004 שמתחשב גם בזמן שנודע לו החטא, וסבור שבגלל זה משתנה גם הדין, אבל \u0003דאזיל בתר\u0004 \u0005[שהולך אחר]\u0006 ה\u0003ידיעה ולא אזיל בתר\u0004 \u0005[הולך אחר]\u0006 \u0003חטאה\u0004 \u0005[\u0006זמן ה\u0005חטא]\u0006 \u0003מי שמעת ליה\u0004 \u0005[האם שמעת אותו]?\u0006 ש\u0003אם כן\u0004 היה סבור — \u0003לייתי\u0004 \u0005[שיביא]\u0006 \u0003קרבן כי דהשתא\u0004 \u0005[כמו ש\u0006דינו \u0005עכשיו]:\u0006 כהן \u0003משוח\u0004 יביא \u0003פר, ונשיא\u0004 (מלך) יביא \u0003שעיר!\u0004 ואם כן אין לנו הוכחה לשיטה שאם נודע חטאה של הנערה הארוסה לאחר שבגרה היא נידונה כבוגרת (בחנק).","ומשיבים: בכל זאת מחלוקת היא בנושא זה כי \u0003האמר ליה\u0004 \u0005[הרי אמר לו]\u0006 \u0003ר' יוחנן לתנא\u0004 (חוזר המשניות) שאמר לו את דברי שילא לגבי נערה המאורסה: \u0003תני\u0004 \u0005[שנה],\u0006 \u0003תידון בסקילה.\u0004 ושואלים על דברי ר' יוחנן: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003\"נערה המאורסה\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003והא\u0004 \u0005[וזו]\u0006 הלא \u0003בוגרת היא! אמר ר' אילעא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"הנערה\"\u0004 — וכוונתו: \u0003הנערה שהיתה כבר\u0004 בזמן שחטאה, אף שעכשיו אינה עוד נערה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חנניא לר' אילעא:\u0004 אם הולכים אחר מה שהיתה בשעת חטאה, \u0003אי הכי מילקא נמי לילקי\u0004 \u0005[אם כך,\u0006 המוציא שם רע על זו, שבגרה, \u0005שילקה גם כן]\u0006 \u0003ומאה סלע נמי לישלם\u0004 \u0005[גם כן שישלם]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רחמנא ניצלן מהאי דעתא\u0004 \u0005[ה' יצילנו מדעה זו],\u0006 כלומר, אתה אומר דברים בלתי הגיוניים. ענה לו: \u0003אדרבה, רחמנא ניצלן מדעתא דידך\u0004 \u0005[להיפך, ה' יצילנו מן\u0006 ה\u0005דעה שלך]\u0006 שהיא־היא שאינה מסתברת.","ושואלים: \u0003ו\u0004באמת, \u0003טעמא מאי\u0004 \u0005[מהו הטעם]\u0006 שלענין סקילה היא נידונת כנערה, ולענין קנס נידונת כבוגרת? \u0003אמר ר' יצחק בר אבין, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יצחק בר אבא: זו,\u0004 הנערה שחטאה, \u0003מעשיה\u0004 (זנותה) \u0003גרמו לה\u0004 ולכן נענשת לפי המצב שהיה בזמן חטאה, \u0003וזה,\u0004 הבעל שנידון בקנס, \u0003עקימת שפתיו,\u0004 כלומר, מה שחטא בדיבורו, בהוצאת שם רע עליה \u0003גרמו לו.\u0004 כיצד? \u0003זו מעשיה גרמו לה, כשהיא זנאי\u0004 \u0005[כאשר זינתה] —\u0006 בהיותה \u0003נערה זנאי\u0004 \u0005[זינתה]\u0006 לכן נידונת כנערה. \u0003וזה עקימת שפתיו גרמו לו, אימת קא מיחייב\u0004 \u0005[מתי הוא מתחייב] —\u0006 \u0003ההיא שעתא\u0004 \u0005[בשעה זו]\u0006 שהוציא עליה שם רע בדיבורו, \u0003וההיא שעתא\u0004 \u0005[ובאותה שעה]\u0006 \u0003בוגרת הואי\u0004 \u0005[היתה].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נערה המאורסה שזינתה\u0004 — \u0003סוקלין אותה על פתח בית אביה. אין לה פתח בית האב,\u0004 שאין לאביה בית \u0003— סוקלין אותה על פתח שער העיר ההיא. ובעיר שרובה גוים,\u0004 ואי אפשר לעשות זאת על פתח שער העיר — \u0003סוקלין אותה על פתח בית דין. כיוצא בדבר אתה אומר: העובד עבודה זרה — סוקלין אותו על שער שעבד בו, ובעיר שרובה גויים\u0004 — \u0003סוקלין אותו על פתח בית דין.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 שסוקלים אותו במקום שעבד בו? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 שנאמר בדין העובד עבודה זרה: \"והוצאת את האיש ההוא או את האשה ההיא אשר עשו את הדבר הרע הזה אל שעריך... וסקלתם באבנים ומתו\" (דברים יז, ה), ופירושו: \u0003\"שעריך\" — זה שער שעבד בו\u0004 עבודה זרה, ושם הוא נסקל. ושואלים: \u0003אתה אומר שער שעבד בו\u0004 עבודה זרה, \u0003או אינו אלא שער שנידון בו,\u0004 שער בית הדין?","ומשיבים: \u0003נאמר \"שעריך\" למטה\u0004 בכתוב זה המדבר בעונשו של העבריין, \u0003ונאמר \"שעריך\" למעלה\u0004 (\"כי ימצא בקרבך באחד שעריך אשר ה' אלהיך נותן לך איש או אשה אשר יעשה את הרע בעיני ה' אלקיך לעבור בריתו\". (דברים יז, ב), \u0003מה \"שעריך\" האמור למעלה\u0004 מדובר ב\u0003שער שעבד בו, אף \"שעריך\" האמור למטה\u0004 לענין מיתה, הכוונה היא ל\u0003שער שעבד בו\u0004 עבודה זרה.","\u0003דבר אחר: \"שעריך\"\u0004 בא להוציא: \u0003ולא שערי גוים.\u0004 ותוהים: \u0003האי\u0004 \u0005[\u0006מלה \u0005זו],\u0006 \u0003\"שעריך\" הא אפיקתיה\u0004 \u0005[הרי\u0006 כבר \u0005הוצאת אותה]\u0006 ללמוד ממנה לענין מקום העונש וכיצד אתה למד מאותה מלה דין נוסף? ומשיבים: \u0003אם כן,\u0004 שהיתה הכוונה ללמדנו רק דבר אחד, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003\"שער\", מאי\u0004 \u0005[מה]\u0006 טעם נאמר \u0003\"שעריך\" — שמע מינה תרתי\u0004 \u0005[למד מכאן שתיים].\u0006","שואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 מקור במקרא לענין \u0003עבודה זרה,\u0004 שסוקלים את העבריין בשער שעבד בו, \u0003נערה המאורסה מנא לן\u0004 \u0005[מניין לנו]\u0006 שסוקלים אותה על פתח בית אביה?","\u0003אמר ר' אבהו: גמר\u0004 \u0005[למד]\u0006 כעין גזירה שווה \u0003\"פתח\"\u0004 האמור במוציא שם רע (דברים כב, כא) \u0003מ\"פתח\"\u0004 האמור במשכן \"פתח שער החצר\" (במדבר ד, כו), \u0003ו\"פתח\"\u0004 זה \u0003מ\"שער\"\u0004 הסמוך לו (\"פתח שער\"), \u0003ו\"שער\"\u0004 שבמשכן \u0003מ\"שעריך\"\u0004 האמור בעבודה זרה. ללמד שדין העונש בפתח האמור בזו שזינתה הוא כדין שערים האמורים בעבודה זרה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המוציא שם רע — לוקה ונותן מאה סלע. ר' יהודה אומר: ללקות — לוקה מכל מקום,\u0004 אבל \u0003מאה סלע,\u0004 אם \u0003בעל\u0004 אותה — \u0003נותן, לא בעל — אינו נותן.\u0004","ומעירים: \u0003קא מיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' אליעזר בן יעקב ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003המוציא שם רע — לוקה ונותן מאה סלע, בין בעל בין שלא בעל, כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים].\u0006 \u0003ר' יהודה אומר: ללקות — לוקה מכל מקום,\u0004 אבל לגבי \u0003מאה סלע,\u0004 אם \u0003בעל — נותן, לא בעל — אינו נותן,\u0004 ו\u0003כ\u0004שיטת \u0003ר' אליעזר בן יעקב.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי כל הברייתא הזו \u0003כולה כ\u0004דעת \u0003ר' אליעזר בן יעקב\u0004 היא. \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש להבין את הדברים: \u0003המוציא שם רע — לוקה ונותן מאה סלע, והוא שבעל. ר' יהודה אומר: ללקות — לוקה מכל מקום,\u0004 שלא נאמר שהדבר תלוי בבעילה אלא לענין קנס.","ושואלים: \u0003ו\u0004האם \u0003סבר ר' יהודה\u0004 כי \u0003ללקות לוקה מכל מקום? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' יהודה אומר: בעל — לוקה, לא בעל — אינו לוקה! אמר רב נחמן בר יצחק:\u0004 מה שאמר ר' יהודה ש\u0003לוקה\u0004 מכל מקום, זוהי \u0003מכת מרדות מדרבנן\u0004 \u0005[מ\u0006דברי \u0005חכמים],\u0006 שכיון שעבר והוציא עליה שם רע — מלקים אותו על ששיקר וגרם לה להסתכן אבל לא מדין תורה."],["\u0003רב פפא אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בעל לוקה\" דקתני התם\u0004 \u0005[ששנה שם],\u0006 \"לוקה\" משמעו — שמשלם \u0003ממון.\u0004 ושואלים: \u0003וקרי ליה\u0004 \u0005[ו\u0006האם \u0005קורא\u0006 הוא \u0005לו]\u0006 \u0003ל\u0004תשלום \u0003ממון\u0004 בשם \u0003\"מלקות\"?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003והא תנן\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 במשנה\u0005]:\u0006 \u0003האומר \"חצי ערכי עלי\" — נותן חצי ערכו,\u0004 כפי שנקצב לכל אדם בתורה (ויקרא כז, ב-ח) לפי מינו ולפי מספר שנותיו. \u0003ר' יוסי בר' יהודה אומר: לוקה ונותן ערך שלם.\u0004 ושאלו על כך: \u0003לוקה אמאי\u0004 \u0005[מדוע]?\u0006 וכי מה עבירה עבר שילקה עליה? \u0003אמר רב פפא:\u0004 הכוונה היא \u0003לוקה\u0004 בממונו, שמתחייב \u0003בערך שלם.\u0004","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ר' יוסי בר' יהודה — \u0003גזירה\u0004 היא שגזרו חכמים כשאמר \u0003\"חצי ערכו\" אטו\u0004 \u0005[משום]\u0006 זה שאומר \u0003\"ערך חציו\".\u0004 והאומר \u0003\"ערך חציו\" הוי ליה\u0004 \u0005[הרי הוא]\u0006 כמנדב \u0003אבר שהנשמה תלויה בו\u0004 (כגון ראשו או לבו). וכל מי שאומר ערך על אבר שהחיים תלויים בו, הרי זה כאילו נדר ערך אדם שלם.","ועוד לענין מוציא שם רע, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר שם \u0003\"וענשו אתו\"\u0004 (דברים כב, יט) — הרי \u0003זה\u0004 עונש \u0003ממון\u0004 שהוא משלם כקנס, \u0003\"ויסרו\"\u0004 (דברים כב, יח) — \u0003זה מלקות.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 זה שאמרו \u0003\"וענשו\" זה ממון — דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וענשו אתו מאה כסף ונתנו לאבי הנערה\"\u0004 (דברים כב, יט), והדבר פשוט. \u0003אלא \"ויסרו\" זה מלקות — מנלן\u0004 \u0005[מניין לנו]?\u0006","\u0003אמר ר' אבהו: למדנו\u0004 כעין גזירה שווה \u0003\"יסרו\"\u0004 האמור כאן \u0003מ\"יסרו\"\u0004 האמור בבן סורר ומורה (\"כי יהיה לאיש בן סורר ומורה איננו שומע בקול אביו ובקול אמו ויסרו אותו\" דברים כא, יח) \u0003ו\"יסרו\"\u0004 האמור בבן סורר ומורה \u0003מ\"בן\"\u0004 האמור שם (\"בן סורר ומורה... ויסרו אותו\". דברים כא, יח) \u0003ו\"בן\"\u0004 זה \u0003מ\"בן\"\u0004 האמור במלקות \u0003\"והיה אם בן הכות הרשע\"\u0004 (דברים כה, ב) ללמד ש\"יסור\" זה, ייסור במלקות הוא.","ושואלים: \u0003אזהרה,\u0004 כלומר, הלאו, מקור האיסור שבגללו מלקים גבי \u0003מוציא שם רע, מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003ר' אלעזר אמר:\u0004 הלאו הוא \u0003מ\"לא תלך רכיל\"\u0004 (ויקרא יט, טז). \u0003ר' נתן אומר:\u0004 המקור הוא \u0003מ\u0004מה שנאמר \u0003\"ונשמרת מכל דבר רע\"\u0004 (דברים כג, י) ומפרש \"דבר רע\" — דיבור רע.","ושואלים: \u0003ור' אלעזר מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר מהאי\u0004 \u0005[מ\u0006פסוק \u0005זה]\u0006 שאמר ר' נתן? ומשיבים: הפסוק \u0003ההוא\u0004 \"דבר\" שנאמר שם \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004כפי שאמר \u0003ר' פנחס בן יאיר.\u0004 שעל הכתוב \u0003\"ונשמרת מכל דבר רע\", מכאן אמר ר' פנחס בן יאיר: אל יהרהר אדם ביום\u0004 הרהורים של זימה (וזהו \"ונשמרת\") \u0003ויבא\u0004 בשל כך \u0003לידי טומאה\u0004 של קרי (\"דבר רע\") \u0003בלילה.\u0004","ושואלים עוד: \u0003ור' נתן מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר מהאי\u0004 \u0005[מ\u0006פסוק \u0005זה]\u0006 שהביא ר' אלעזר \"לא תלך רכיל\"? ומסבירים: הכתוב \u0003ההוא,\u0004 הוא מפרשו: \u0003אזהרה לבית דין שלא יהא רך לזה\u0004 לבעל דין אחד \u0003וקשה לזה,\u0004 אלא צריך לנהוג בשני הצדדים בשווה. שפירש לשון \"רכיל\" = רך לי.","ועוד בדיני מוציא שם רע, שנינו: אם \u0003לא אמר\u0004 הבעל \u0003לעדים \"בואו והעידוני\"\u0004 שאשתו זינתה, \u0003והן מעידים אותו מאליהן,\u0004 ונתברר שהם עדי שקר — \u0003הוא אינו לוקה, ואינו נותן מאה סלעים,\u0004 שהרי הוא לא עשה מעשה לרעתה. \u0003היא וזוממיה מקדימין לבית הסקילה,\u0004 כדי להורגם.","וקודם כל תוהים על הלשון: \u0003היא וזוממיה סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 שהרי אם היא חייבת ויוצאת להיסקל — אין הם זוממים, ולהיפך, אם הם זוממים ונסקלים — היא אינה חייבת! \u0003אלא\u0004 יש לפרש: \u0003או היא או זוממיה מקדימין לבית הסקילה,\u0004 שאם עדי אמת הם — היא נסקלת, ואם נמצאו זוממים — הם נסקלים. עד כאן לשון הברייתא.","ומדייקים: \u0003טעמא\u0004 \u0005[הטעם],\u0006 דווקא, ש\u0003לא אמר להו\u0004 \u0005[להם]\u0006 כלל להעיד, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא אגרינהו\u0004 \u0005[שכר אותם],\u0006 אלא פיתה אותם בדברים שיעידו כטענתו — הוא לוקה ומשלם. והרי זה \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 הבעל \u0003אינו חייב\u0004 בעונשים כשהוציא שם רע \u0003עד שישכור עדים.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה?\u0004 שהרי לא נתפרש במקרא ששכר הבעל עדי שקר! \u0003אמר ר' אבהו: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה של \u0003\"שימה\" \"שימה\"; כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בדין מוציא שם רע: \u0003\"ושם לה עלילת דברים\"\u0004 (דברים כב, יד), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בענין ריבית: \u0003\"לא תשימון עליו נשך\"\u0004 (שמות כב, כד) \u0003מה להלן,\u0004 בנשך, הכוונה היא שימה של \u0003ממון, אף כאן,\u0004 \"ושם לה עלילות\", הוא דבר שמשלם עבורו \u0003ממון.\u0004","\u0003אמר רב נחמן בר יצחק, וכן תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף צידוני בי\u0004 \u0005[\u0006ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שמעון בן יוחאי: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר מ\u0003\"שימה\" \"שימה\",\u0004 כפי שאמר ר' אבהו.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 לדעת ר' יהודה, אם \u0003שכרן בקרקע\u0004 ולא בכסף, \u0003מהו\u0004 הדין? שכרם \u0003בפחות משוה פרוטה מהו?\u0004 שכר את העדים \u0003שניהם בפרוטה\u0004 אחת \u0003מהו?\u0004 שאם לומדים את הדבר מנשך הרי שם מדובר בכסף בלבד, ואין דין כסף אלא בשוה פרוטה ומעלה.","כיוצא בזה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי\u0004 והעלה בעיות מסופקות אחרות בדיני מוציא שם רע: \u0003הוציא שם רע על הנישואין הראשונים מהו?\u0004 שאם נשא אותה פעם אחת וגירש אותה, ואחר כך נשא אותה בשניה, והוציא שם רע על הנישואין הראשונים, שטען שזינתה אז תחתיו, מה יהא דינו? וכן אם הוציא שם רע \u0003על נשואי אחיו, מהו?\u0004 כלומר, שהוא היה יבם, וטען שבנישואיה הראשונים, כשנשא אותה אחיו, כבר לא היתה בתולה. לשאלות אלה לא נמצאו פתרונות.","ומעירים: \u0003פשוט מיהא חדא\u0004 \u0005[פתור לפחות אחת]\u0006 מהשאלות הללו. \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' יונה\u0004 על הכתוב \u0003\"\u0004ואמר אבי הנערה אל הזקנים \u0003את בתי נתתי לאיש הזה\"\u0004 (דברים כב, טז), שהדגשה זו באה ללמד: \u0003לזה — ולא ליבם.\u0004 ומכאן שאין דין זה חל על יבם המוציא שם רע על אשת אחיו שהתייבמה לו.","בתוך הדיון הקודם הזכרנו כמה פעמים שהדברים תלויים במחלוקת חכמים ור' אליעזר בן יעקב. ושואלים: \u0003מאי רבנן\u0004 \u0005[מה\u0006 היא שיטת \u0005חכמים]\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 היא שיטת\u0005]\u0006 \u0003ר' אליעזר בן יעקב\u0004 שאנחנו מרמזים להם? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כיצד הוצאת שם רע? בא\u0004 הבעל \u0003לבית דין, ואמר\u0004 לאב: \u0003\"פלוני, לא מצאתי לבתך בתולים\". אם יש עדים שזינתה תחתיו — יש לה כתובה מנה.\u0004","ולפני שמסיימים להביא את הברייתא כבר מתעוררת תמיהה רבה: \u0003אם יש עדים שזינתה תחתיו יש לה כתובה מנה?!\u0004 הלא \u0003בת סקילה\u0004 (ראויה להיסקל) \u0003היא!\u0004 ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך צריך לתקן את הדברים: \u0003אם יש עדים שזינתה תחתיו\u0004 — הרי היא נידונת \u0003בסקילה,\u0004 אולם אם \u0003זינתה מעיקרא\u0004 \u0005[מתחילה]\u0006 לפני האירוסין בעודה פנויה, נמצא שרק רימתה אותו במה שאמרה שהיא בתולה, ולכן \u0003יש לה כתובה מנה,\u0004 כפי שמגיע לבעולה שנישאת.","\u0003נמצא ששם רע אינו שם רע,\u0004 כלומר, שהדברים אינם נכונים — \u0003הוא לוקה ונותן מאה סלע, בין בעל\u0004 אותה בשעתו \u0003ובין לא בעל. ר' אליעזר בן יעקב אומר: לא נאמרו דברים הללו אלא כשבעל.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' אליעזר בן יעקב\u0004 הוא מפרש את הכתובים כמשמעם, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"ובא אליה\"\u0004 (דברים כב, יג) \u0003\"ואקרב אליה\"\u0004 (דבריםך כב, יד), שהם לשונות בעילה,","\u0003אלא לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ובא אליה\",\u0004 ומה פירוש \u0003\"ואקרב אליה\"\u0004 אם לא בעל? ומסבירים: הם מבינים \u0003\"ובא אליה\"\u0004 — כוונתו היא \u0003בעלילות, \"ואקרב אליה\" — בדברים,\u0004 ולא בביאה.","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' אליעזר בן יעקב — היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"לא מצאתי לבתך בתולים\"\u0004 (דברים כב, יז), שטען שבעל אותה ומצא שאינה בתולה. \u0003אלא לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא מצאתי לבתך בתולים\",\u0004 הרי לא בעל אותה! ומשיבים, הם מפרשים שהוא טוען: \u0003\"לא מצאתי לבתך כשרי בתולים\".\u0004 לא מצאתי שיש לה כשרות של בתולים, שהרי טוען שנודע לו שזינתה.","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' אליעזר בן יעקב, היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 בדברי האב \u0003\"ואלה בתולי בתי\"\u0004 (דברים כב, יז), שיש בידו חפץ המוכיח שהיתה בתולה כנגד טענת הבעל שלא מצא הבתולים. \u0003אלא לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ואלה בתולי בתי\"?\u0004 ומסבירים לשיטתם, האב מוכיח וטוען: \u0003\"ואלה כשרי בתולי בתי\",\u0004 שמביא עדים כנגד העדים, או הוכחות אחרות שבתו היתה בתולה כשירה.","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' אליעזר בן יעקב — היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"ופרשו השמלה\"\u0004 (דברים כב, יז), כלומר, מביאים את הסדין שנבעלה עליו ומוכיחים שהיה עליו דם בתולים. \u0003אלא לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים]\u0006 האומרים שיכול להוציא שם רע גם אם לא בעל, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ופרשו השמלה\"?\u0004","\u0003אמר ר' אבהו:\u0004 הם מפרשים בלשון רמז: \u0003פרשו מה ששם לה\u0004 (\"שמלה\" — דברים כב, לה), כלומר, מבררים ובודקים את העדות הזו שהעיד כנגדה. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"ופרשו השמלה\", מלמד שבאין עדים של זה,\u0004 של הבעל, \u0003ועדים של זה,\u0004 של אבי האשה, \u0003ובוררין\u0004 בית דין \u0003את הדבר כשמלה חדשה,\u0004 וחכמים מפרשים את הביטוי הזה כדרך משל. \u0003ר' אליעזר בן יעקב אומר: דברים ככתבן,\u0004 ופרשו \u0003שמלה ממש.\u0004","\u0003שלח ר' יצחק בר רב יעקב בר גיורי\u0004 מארץ ישראל לבבל \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: אף על גב\u0004 \u0005[אף על פי]\u0006 \u0003שלא מצינו בכל התורה כולה שחלק הכתוב בין ביאה כדרכה לביאה שלא כדרכה,\u0004 לא \u0003ל\u0004ענין \u0003מכות ו\u0004לא \u0003ל\u0004ענין \u0003עונשין\u0004 אחרים, \u0003אבל\u0004 ב\u0003מוציא שם רע חלק;\u0004 ש\u0003אינו חייב עד שיבעול\u0004 את האשה, ואפילו היתה הבעילה \u0003שלא כדרכה, ויוציא\u0004 עליה \u0003שם רע\u0004 שמצא שהיתה בעולה \u0003כדרכה.\u0004","ושואלים: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא הלכה זו שאמר ר' יוחנן? \u0003אי כרבנן\u0004 \u0005[אם כ\u0006דעת \u0005חכמים]\u0006 אם כן למה צריך שיבעל אותה, הרי לדעתם \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא בעל\u0004 אותה כלל מתחייב. \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003ר' אליעזר בן יעקב\u0004"],["\u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003כדרכה בעינן\u0004 \u0005[אנו צריכים]!\u0006 שהרי לדעתו הדברים ככתבם, שבא עליה ומצא שאיננה בתולה. \u0003אלא שלח רב כהנא משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן\u0004 שכך היתה המימרה: \u0003אינו חייב עד שיבעול כדרכה ויוציא שם רע בכדרכה,\u0004 כדברי ר' אליעזר בן יעקב.","\u0003האב זכאי בבתו\u0004 בעודה קטנה או נערה, \u0003בקידושיה,\u0004 בכל דרך שמתקדשת: \u0003בכסף,\u0004 שכסף קידושיה לו, או \u0003בשטר,\u0004 שאם קיבל שטר אירוסין עליה, הריהי מקודשת, \u0003ובביאה,\u0004 שרשאי למוסרה לאחר לביאה לשם קידושין. וכן \u0003זכאי\u0004 האב \u0003במציאתה,\u0004 שמה שמוצאת בעודה קטנה או נערה, הוא שלו. \u0003ו\u0004כמו כן זכאי האב \u0003במעשה ידיה, ובהפרת נדריה,\u0004 שאביה רשאי להפר נדר שנודרת, \u0003ומקבל את גיטה\u0004 אם נתגרשה לפני שבגרה. \u0003ו\u0004אולם \u0003אינו אוכל פירות בחייה,\u0004 שאם היה לה רכוש משלה, כגון שירשה מקרובי אמה, אינו אוכל פירות של רכוש זה בחייה, אף שאם מתה הוא יורש אותה.","אם \u0003נשאת\u0004 הבת לאיש — \u0003יתר עליו הבעל\u0004 בזכויותיו ובחובותיו. בזכויותיו — \u0003שאוכל פירות\u0004 נכסיה \u0003בחייה,\u0004 ובחובותיו — \u0003וחייב במזונותיה, ובפרקונה\u0004 (לפדות אותה אם נשבתה), \u0003וקבורתה,\u0004 אם מתה. \u0003ר' יהודה אומר: אפילו עני שבישראל לא יפחות משני חלילין ומקוננת\u0004 שהיו נוהגים לשכור לצורך ההלוויה, שאף זה חלק מחובת הקבורה.","שנינו במשנה שהאב זכאי בכסף הקידושין של בתו, ושואלים: \u0003בכסף מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003אמר רב יהודה: אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי האמה העבריה היוצאת לחופש: \u0003\"ויצאה חנם אין כסף\"\u0004 (שמות כא, יא), ונדייק מכאן: \u0003אין כסף לאדון זה,\u0004 כלומר, אדוניה אינו מקבל כסף בשעת יציאתה ממנו, \u0003ו\u0004אולם \u0003יש כסף לאדון אחר, ומנו\u0004 \u0005[ומיהו]?\u0006 \u0003אביה\u0004 שהוא כמו אדון לה, שגם כשיוצאת ממנו (בקידושין) עדיין יש לו זכות בכסף קידושיה.","ושואלים: מדוע נדייק כך? \u0003ואימא לדידה\u0004 \u0005[ואמור\u0006 שכסף קידושיה ינתן \u0005לה]\u0006 ומן הכתוב נלמד שאין כסף לאדון זה, אבל יש כסף לה עצמה כשיוצאת מרשות האב! ודוחים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003אביה מקבל\u0004 את \u0003קידושיה,\u0004 שיכול לקדשה למי שרוצה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"את בתי נתתי לאיש הזה\"\u0004 (דברים כב, טז) האם תאמר ש\u0003איהי שקלא כספא\u0004 \u0005[היא תקח\u0006 את \u0005הכסף]?!\u0006 והרי הוא המקבל עבורה את הקידושין!","ומקשים: \u0003ואימא הני מילי\u0004 \u0005[ואמור\u0006 ש\u0005דברים אלה]\u0006 שאביה מקדשה אמורים ב\u0003קטנה, דלית\u0004 \u0005[שאין]\u0006 \u0003לה יד,\u0004 כלומר, אין לה כוח משפטי של זכיה בעצמה, לפי שאין לה דעת, \u0003אבל נערה דאית\u0004 \u0005[שיש]\u0006 \u0003לה יד,\u0004 שיצאה מקטנות והריהי בת דעת, ואם כן \u0003איהי\u0004 \u0005[היא]\u0006 \u0003תקדש נפשה\u0004 \u0005[\u0006את \u0005עצמה]\u0006 \u0003ואיהי תשקול כספא\u0004 \u0005[והיא תיקח\u0006 גם את \u0005כסף\u0006 הקידושין\u0005]!\u0006 ומשיבים, יש לימוד אחר לזה, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בנעריה בית אביה\"\u0004 (במדבר ל, יז), ללמד: \u0003כל שבח\u0004 ורווח של הבת בזמן \u0003נעורים — לאביה,\u0004 ובכלל זה גם כסף קידושיה.","ושואלים: \u0003ואלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב הונא אמר רב: מנין\u0004 לנו \u0003שמעשה הבת לאביה — שנאמר: \"וכי ימכר איש את בתו לאמה\"\u0004 (שמות כא, ז), \u0003מה אמה מעשה ידיה לרבה\u0004 (לאדוניה) — \u0003אף בת מעשה ידיה לאביה. למה לי\u0004 דרשה זו? \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 ההוכחה \u0003מ\"בנעריה בית אביה\"! אלא\u0004 ודאי הכתוב \u0003ההוא\u0004 \"בנעוריה בית אביה\" \u0003בהפרת נדרים הוא דכתיב\u0004 \u0005[שנאמר],\u0006 שלענין זה יש זכות לאב, אבל אין הכתוב מדבר בענין ממונות.","\u0003וכי תימא נילף מינה\u0004 \u0005[ואם תאמר נלמד ממנה],\u0006 שכשם שזכאי בהפרת נדריה, כך יהיה זכאי בממונה — הרי כלל הוא ש\u0003ממונא מאיסורא לא ילפינן\u0004 \u0005[\u0006דיני \u0005ממונות מ\u0006דיני \u0005איסורים אין אנו למדים],\u0006 לפי שהן שתי מערכות הלכתיות נבדלות. \u0003וכי תימא נילף מקנסא\u0004 \u0005[ואם תאמר\u0006 ש\u0005נלמד מ\u0006דין \u0005קנס]\u0006 שמשלם האונס את הנערה, שמפורש בכתוב שהוא ניתן לאב — הרי גם כאן \u0003ממונא מקנסא לא ילפינן\u0004 \u0005[ממון מקנס אין אנו למדים],\u0006 כי בקנסות יש דינים מיוחדים.","\u0003וכי תימא נילף\u0004 \u0005[ואם תאמר\u0006 ש\u0005נלמד]\u0006 \u0003מבושת ופגם\u0004 שאביה מקבל אם נאנסה — אף בזה יש לומר: \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003בושת ופגם\u0004 ש\u0003אביה נמי\u0004 \u0005[גם כן]\u0006 \u0003שייך ביה\u0004 \u0005[בהם],\u0006 שהרי גם האב נפגע ממאורע מביש זה, ואין ללמוד מכאן דיני ממונות אחרים.","\u0003אלא\u0004 חוזרים ללימוד הראשון מהכתוב \"חינם אין כסף\", ו\u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר, \u0003דכי ממעט רחמנא\u0004 \u0005[שכאשר מיעט הכתוב]\u0006 בפסוק \"ויצאה חינם\" — \u0003יציאה דכוותה קא\u0004 \u0005[שכמותה הוא]\u0006 \u0003ממעט,\u0004 שאמנם כאשר היא יוצאה בבגרותה מן האדון — אין כסף לאדון, אבל אם יוצאת לפני זמן זה על ידי תשלום מקצת מן הכסף שקיבלה כשנמכרה לאמה — יש עדיין כסף לאדון ביציאה זו, ומכאן נלמד ליציאתה מרשות אביה בקידושין שכסף הקידושין שייך לאביה.","ומקשים: \u0003והא לא דמיא הא יציאה להא יציאה\u0004 \u0005[והרי אינה דומה יציאה זו ליציאה זו]:\u0006 \u0003התם, גבי\u0004 \u0005[שם, אצל]\u0006 ה\u0003אדון, נפקא לה מרשותיה\u0004 \u0005[יוצאת היא מרשותו]\u0006 \u0003לגמרי\u0004 כאשר הוא משחרר אותה, ואילו \u0003יציאה\u0004 מרשותו של ה\u0003אב אכתי מחסרא\u0004 \u0005[עדיין מחוסרת\u0006 היא\u0005]\u0006 \u0003מסירה לחופה,\u0004 וכל עוד לא נישאה היא ברשות אביה, ואם כן אי אפשר להשוות יציאתה לנישואין ליציאתה מהעבדות!","ומשיבים: \u0003מ\u0004זכותו ל\u0003הפרת נדרים\u0004 שנדרה \u0003מיהא נפקא\u0004 \u0005[על כל פנים יצאה]\u0006 \u0003לה מרשותיה\u0004 \u0005[מרשותו]\u0006 במידה מסויימת כבר משעת הקידושין, שלענין זה כבר אינו שולט בה לגמרי, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003נערה המאורסה אביה ובעלה\u0004 יחד \u0003מפירין לה נדריה,\u0004 ושוב אין האב לבדו יכול להפר לה, ולפיכך אפשר להשוות יציאה ליציאה.","שנינו שאב רשאי לקדש את בתו ב \u0003שטר ו\u0004ב\u0003ביאה.\u0004 ושואלים: \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 דבר זה? ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והיתה לאיש אחר\"\u0004 (דברים כד, ב), ומכיון שלא נתפרש באיזה דרך נתקדשה־\"הוייתה\" לאיש אחר, הרי \u0003איתקוש הוויות להדדי\u0004 \u0005[הוקשו,\u0006 הושוו ה\u0005הוויות\u0006 של נישואין \u0005זו לזו],\u0006 שכל דרכי הקידושין שוות זו לזו, וכשם שהן שוות לענין זה, כך הן שוות גם לענין זכות האב.","שנינו במשנה שהאב \u0003זכאי במציאתה.\u0004"],["\u0003משום איבה,\u0004 כדי שלא תהא לו איבה כלפיה שאם תמצא דברים ולא תתן לו, לא ירצה לפרנסה.","שנינו במשנה שהאב זכאי \u0003במעשה ידיה\u0004 של בתו הקטנה והנערה. ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה? ומשיבים: ש\u0003אמר רב הונא אמר רב: מנין שמעשה\u0004 ידי \u0003הבת לאב — שנאמר: \"וכי ימכר איש את בתו לאמה\"\u0004 (שמות כא, ז) ודורשים: \u0003מה אמה מעשה ידיה לרבה\u0004 (לאדוניה) — \u0003אף בת מעשה ידיה לאביה.\u0004 ושואלים: \u0003ואימא הני מילי\u0004 \u0005[ואמור\u0006 ש\u0005דברים אלה\u0006 אמורים\u0005]\u0006 דווקא ב\u0003קטנה, דמצי מזבן לה\u0004 \u0005[שיכול\u0006 האב \u0005למכור אותה]\u0006 לשפחה, \u0003אבל נערה דלא מצי מזבן לה\u0004 \u0005[שאינו יכול למכור אותה],\u0006 \u0003מעשה ידיה דידה הוו\u0004 \u0005[שלה הם]!\u0006","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר\u0006 הדבר\u0005]\u0006 שאף מעשה ידי הנערה של \u0003אביה הוו\u0004 \u0005[הם],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003מעשה ידיה לאו\u0004 \u0005[לא]\u0006 של \u0003אביה, אלא הא דזכי ליה רחמנא\u0004 \u0005[זה שזיכתה לו התורה]\u0006 \u0003לאב למימסרה\u0004 \u0005[למוסרה]\u0006 לבתו נערה \u0003לחופה, היכי מצי מסר לה\u0004 \u0005[איך\u0006 הוא \u0005יכול למסור אותה]?\u0006 \u0003הא קמבטל לה\u0004 \u0005[הרי\u0006 הוא \u0005מבטל אותה]\u0006 באותה שעה \u0003ממעשה ידיה,\u0004 ואם מעשה ידיה לעצמה היתה יכולה למחות על כך. אלא ודאי ששל אביה הם.","על ראיה זו \u0003פריך\u0004 \u0005[הקשה]\u0006 \u0003רב אחאי: אימא\u0004 \u0005[אמור]\u0006 שכאשר הוא מוסר אותה לחופה מדובר \u0003דיהיב\u0004 \u0005[שנותן]\u0006 \u0003לה שכר פקעתה\u0004 \u0005[ביטול\u0006 מלאכתה\u0005]\u0006 ולכן אינה יכולה למחות. \u0003אי נמי דמסר לה בליליא\u0004 \u0005[או גם כן ש\u0006הוא \u0005מוסר אותה\u0006 לחופה \u0005בלילה]\u0006 כאשר אינה עובדת. \u0003אי נמי דמסר לה\u0004 \u0005[או גם כן שמוסר אותה]\u0006 \u0003בשבתות וימים טובים,\u0004 כאשר אינה עובדת.","\u0003אלא,\u0004 חוזרים ללימוד הראשון מאמה עבריה, ועל הקושיה שמא זהו רק בקטנה שיכול למוכרה, אבל לא בנערה — על כך צריך לומר: \u0003קטנה לא צריכא קרא\u0004 \u0005[אינה צריכה כתוב]\u0006 כלל ללמד שמעשה ידיה לאב, וטעמו של דבר — \u0003השתא זבוני מזבין לה\u0004 \u0005[עכשיו,\u0006 הרי, \u0005למכור\u0006 הוא \u0005מוכר אותה],\u0006 \u0003מעשה ידיה מיבעי\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 ששייכים לו?! שאם גופה שייך לו — כל שכן מעשה ידיה. \u0003אלא כי איצטריך קרא\u0004 \u0005[כאשר הוצרך הכתוב]\u0006 באמה עבריה, הרי זה \u0003לנערה,\u0004 שגם מעשה ידיה לאביה.","שנינו במשנה שהאב זכאי \u0003בהפרת נדריה\u0004 של בתו. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בפרשה העוסקת בענין הפרת נדרים: \u0003\"בנעריה בית אביה\"\u0004 (במדבר ל, יז) ומפורש שם שהאב מיפר את נדרי בתו.","עוד שנינו במשנה שהאב \u0003מקבל את גיטה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה? ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויצאה... והיתה\u0004 לאיש אחר\u0003\"\u0004 (דברים כד, ב), הרי בפסוק זה \u0003איתקוש\u0004 \u0005[הוקשה,\u0006 הושוותה\u0005]\u0006 \u0003יציאה\u0004 (גירושין) \u0003להוייה\u0004 (נישואין) \u0003,\u0004 שאותם הדינים הקיימים בנישואין, קיימים גם בגירושין, וכפי שמקבל את קידושיה, כך מקבל את גיטה.","שנינו במשנה שהאב \u0003אינו אוכל פירות\u0004 נכסים שירשה בתו מקרובי אמה \u0003בחייה\u0004 של בתו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003האב אינו אוכל פירות בחיי בתו. ר' יוסי בר' יהודה אומר: האב אוכל פירות בחיי בתו.\u0004 ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]?\u0006 ומסבירים, ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר: בשלמא\u0004 \u0005[נניח]\u0006 ה\u0003בעל תקינו ליה רבנן פירי\u0004 \u0005[תיקנו לו חכמים פירות],\u0006 משום ש\u0003אם\u0004 לא \u0003כן מימנע\u0004 \u0005[יימנע]\u0006 \u0003ולא פריק\u0004 \u0005[יפדה\u0006 אותה\u0005],\u0006 שזכות הבעל באכילת פירות היא כנגד חובתו לפדותה,","\u0003אלא\u0004 ה\u0003אב, מאי איכא למימר\u0004 \u0005[מה יש לומר] —\u0006 \u0003דמימנע\u0004 \u0005[שיימנע]\u0006 \u0003ולא פריק\u0004 \u0005[יפדה\u0006 אותה\u0005]?\u0006 \u0003בלאו הכי פריק לה\u0004 \u0005[בלא זה,\u0006 בלא אכילת פירות, גם כן \u0005יפדה אותה]!\u0006 שהרי בתו היא ובודאי לא יתעלם מבשרו וידאג לפדיונה! \u0003ור' יוסי בר' יהודה סבר:\u0004 אם אנו אומרים שהאב אינו זכאי לאכול מפירות נכסיה, ה\u0003אב נמי מימנע\u0004 \u0005[גם כן יימנע]\u0006 \u0003ולא פריק\u0004 \u0005[יפדה].\u0006 וטעמו, \u0003סבר\u0004 האב: \u0003כיסא נקיטא עילוה, תיזיל ותפרוק נפשה\u0004 \u0005[כיס\u0006 כסף \u0005מוחזק עליה,\u0006 בידה, ששמרה לה לעת הצורך. \u0005תלך ותפדה\u0006 היא \u0005את עצמה]\u0006 והוא אינו צריך לדאוג לה.","שנינו במשנה שאם \u0003ניסת\u0004 לבעל, \u0003יתר עליו הבעל\u0004 על האב \u0003שהוא אוכל\u0004 פירות נכסיה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כתב לה\u0004 האב בכתובתה שנותן לה נדוניה \u0003פירות, כסות וכלים שיבואו עמה מבית אביה לבית בעלה\u0004 — אם \u0003מתה\u0004 בזמן האירוסין, \u0003לא זכה הבעל בדברים הללו. משום ר' נתן אמרו: זכה הבעל בדברים הללו.\u0004","ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003ר' אלעזר בן עזריה ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003נתארמלה\u0004 (נתאלמנה) האשה \u0003או נתגרשה, בין מן הנשואין בין מן האירוסין\u0004 — \u0003גובה את הכל,\u0004 את כל הכתובה שכתב לה בעלה, גם אם הוסיף הרבה על מאתים או מנה הקצובים לה על פי הדין. \u0003ר' אלעזר בן עזריה אומר:\u0004 אם נתאלמנה או נתגרשה \u0003מן הנשואין\u0004 — \u0003גובה את הכל, ו\u0004אם \u0003מן האירוסין\u0004 — מקבלת רק עיקר הכתובה שתיקנו חכמים. שאם היתה \u0003בתולה\u0004 — \u0003גובה מאתים, ו\u0004אם היתה \u0003אלמנה\u0004 — גובה רק \u0003מנה,\u0004 ואינה מקבלת את התוספות שהוסיף לה הבעל בכתובה."],["\u0003שלא כתב לה\u0004 תוספת על הסכום שקבעו חכמים \u0003אלא על מנת לכונסה,\u0004 וכיון שלא נשאה — לא זיכה לה. ונשווה את השיטות: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003לא זכה\u0004 הבעל בנדוניה — הוא סבור \u0003כ\u0004שיטת \u0003ר' אלעזר בן עזריה,\u0004 ולכן, אומר שגם האב לא כתב אלא על מנת שיכנסנה. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003זכה\u0004 בנדוניה — הוא סבור \u0003כ\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 בענין תוספת כתובה.","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[ש\u0006דעת \u0005הכל]\u0006 \u0003כר' אלעזר בן עזריה,\u0004 וכך יש להסביר: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003לא זכה\u0004 — פשוט שהוא \u0003כ\u0004דעת \u0003ר' אלעזר בן עזריה, ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003זכה\u0004 — הוא מחלק בין הדברים כך: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אלעזר בן עזריה אלא מדידיה לדידה\u0004 \u0005[משלו לשלה],\u0006 שהבעל כותב לאשה תוספת לכתובה, שיש טעם בדבר — \u0003שלא כתב לה אלא על מנת לכונסה,\u0004 ולפני כניסה לא התכוון לתת.","\u0003אבל מדידה לדידיה\u0004 \u0005[משלה לשלו],\u0006 מה שאביה כותב כנדוניה, \u0003אפילו ר' אלעזר בן עזריה מודי\u0004 \u0005[מודה]\u0006 שהבעל זוכה בהם, שהמתנות שהאב נותן הן \u0003משום איחתוני\u0004 \u0005[ההתחתנות]\u0006 \u0003הוא,\u0004 שמעוניין להיות בקשר חיתון במשפחה זו, \u0003והא איחתני להו\u0004 \u0005[והרי התחתנו,\u0006 התקשרו כבר\u0005]\u0006 ואין הדבר קשור לחיבת נישואין.","שנינו במשנה שהבעל \u0003חייב במזונותיה\u0004 של אשתו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003תיקנו\u0004 חכמים חובת הבעל ב\u0003מזונותיה\u0004 של אשתו \u0003תחת\u0004 חובת האשה לתת לו את \u0003מעשה ידיה. ו\u0004כן תיקנו שיהא חייב הבעל בהוצאות \u0003קבורתה תחת כתובתה,\u0004 כלומר, בעד הנדוניה שמכניסה לו, ו\u0003לפיכך בעל אוכל פירות\u0004 הנכסים.","ותוהים: \u0003פירות מאן דכר שמייהו\u0004 \u0005[מי הזכיר\u0006 את \u0005שמם]?!\u0006 הרי לא נזכרו בברייתא כלל פירות הנכסים, וכיצד הגיעה הברייתא לדבר בהם?! ומסבירים: \u0003חסורי מחסרא, והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא, \u0005וכך שנה,\u0006 כך יש לשנותה\u0005]:\u0006 \u0003תיקנו מזונותיה תחת מעשה ידיה, ופירקונה\u0004 \u0005[ופדיונה],\u0006 חובתו לפדות אותה כאשר נשבית, \u0003תחת פירות\u0004 שהוא אוכל מנכסיה, \u0003וקבורתה תחת כתובתה, לפיכך בעל אוכל פירות.\u0004","הסברנו איפוא כיצד הגיעו לדבר בפירות, אבל הסגנון עדיין קשה, ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 המשמעות של מלת \u0003\"לפיכך\"\u0004 כאן, וכיצד יוצאת מסקנה זו של \"לפיכך\"?","ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מיכל לא נכלינהו, אנוחי ננחינהו\u0004 \u0005[\u0006ש\u0005לא יאכלם\u0006 הבעל, את הפירות, אלא \u0005יניח אותם]\u0006 ויהו שמורים, שאם יצטרך לפדותה, יפדה אותה מכספים אלה. ש\u0003אם\u0004 לא היו נוהגים \u0003כן, מימנע\u0004 \u0005[יימנע]\u0006 \u0003ולא פריק\u0004 \u0005[יפדה\u0006 אותה\u0005],\u0006 שלא ירצה להוציא מכספו לפדיונה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דהא עדיפא\u0004 \u0005[ש\u0006תקנה \u0005זו עדיפה]\u0006 שיאכל את הפירות, ומדוע? — \u0003זימנין\u0004 \u0005[פעמים]\u0006 ש\u0003לא מלו\u0004 \u0005[ימלאו],\u0006 שפירות הנכסים אינם עולים כדי דמי פדיונה, \u0003ו\u0004כיון שתיקנו שאוכל את הפירות מחוייב להוסיף ו\u0003פריק לה מדידיה\u0004 \u0005[ויפדה אותה משלו].\u0006 ולפי זה מובנת לשון \"לפיכך\", שכיון שתיקנו שאוכל פירות כנגד פדיונה, דאגו שיהא בתקנה זו משום אבטחה שלא יימנע לפדותה.","עד כאן לפירוש לשון הברייתא, אבל שואלים לעצם הדברים: \u0003ואיפוך אנא\u0004 \u0005[ואהפוך אני],\u0006 מדוע אומרים שמזונותיה תיקנו תחת מעשה ידיה — שמא מזונותיה תחת הפירות מנכסיה, וכיוצא בזה?","\u0003אמר אביי: תיקנו מצוי למצוי, ושאינו מצוי לשאינו מצוי,\u0004 כלומר, תיקנו את הדברים באופן כזה שכנגד החובות המצויות של הבעל כלפי האשה תיקנו התחייבויות מצויות של האשה כלפי הבעל, ודברים שהם פחות מצויים תיקנו כנגד דברים שאצל האשה הם פחות מצויים. ולכן, מזונות שהם תדירים תיקנו כנגד מעשה ידיה שהם תדירים, ופירות נכסים, שלא תמיד הם מצויים, תיקנו אותם כנגד פדיונה מן השבי, ונדוניה כנגד הקבורה.","\u0003אמר רבא: האי תנא סבר\u0004 \u0005[תנא זה\u0006 שלהלן \u0005סבור]\u0006 שחובת הבעל ב\u0003מזונות\u0004 האשה היא \u0003מדאורייתא\u0004 \u0005[מן התורה].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב באמה עבריה \"כמשפט הבנות יעשה לה... שארה כסותה ועונתה לא יגרע\" (שמות כא, ט-י): \u0003\"שארה\"\u0004 — \u0003אלו מזונות.\u0004 וראיה לדבר שהן מזונות — \u0003וכן הוא אומר: \"ואשר אכלו שאר עמי\"\u0004 (מיכה ג, ג), שמשמעו — בשר עמי. \u0003\"כסותה\"\u0004 — \u0003כמשמעו,\u0004 כלומר, חובתו להלביש אותה בבגדים. \u0003\"ענתה\"\u0004 — \u0003זו עונה\u0004 של תשמיש \u0003האמורה בתורה\u0004 לכל אדם לפי הפנאי שלו, \u0003וכן הוא אומר \"אם תענה את בנתי\"\u0004 (בראשית לא, נ), שפירושו: שלא ימנע מהן עונתן.","\u0003ר' אלעזר אומר: \"שארה\"\u0004 — \u0003זו עונה.\u0004 וראיה לדבר ש\"שאר\" פירושו ענין של תשמיש — \u0003וכן הוא אומר: \"איש איש אל כל שאר בשרו לא תקרבו לגלות ערוה\"\u0004 (ויקרא יח, ו). \u0003\"כסותה\"\u0004 — \u0003כמשמעו,\u0004 בגדים. \u0003\"עונתה\"\u0004 — \u0003אלו מזונות, וכן הוא אומר: \"ויענך וירעבך\u0004 ויאכילך את המן\u0003\"\u0004 (דברים ח, ג)."],["\u0003ר' אליעזר בן יעקב אומר: \"שארה\"\u0004 ו\u0003\"כסותה\"\u0004 הם ענין אחד, והכוונה: \u0003לפום\u0004 \u0005[לפי]\u0006 \u0003שארה,\u0004 לפי בשרה ולפי גילה — \u0003תן כסותה, שלא יתן לה לא\u0004 בגדים \u0003של ילדה\u0004 (צעירה) \u0003לזקינה, ולא של זקינה לילדה.\u0004 וכן \u0003\"כסותה\" ו\"ענתה\"\u0004 הם ענין אחד: \u0003לפום\u0004 \u0005[לפי]\u0006 \u0003עונתה\u0004 וזמנה \u0003תן כסותה, שלא יתן\u0004 בגדים \u0003חדשים\u0004 ועבים \u0003בימות החמה, ולא שחקים\u0004 (בגדים שנשחקו) \u0003בימות הגשמים,\u0004 שבימים אלה היא זקוקה לבגדים עבים ומחממים.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 ברייתא זו: \u0003\"שארה\"\u0004 — \u0003זו קרוב בשר\u0004 בזמן תשמיש, \u0003שלא ינהג בה מנהג פרסיים שמשמשין מטותיהן בלבושיהן.\u0004 ומעירים: האמור בברייתא זו \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב הונא,\u0004 ש\u0003אמר רב הונא: האומר \"אי אפשי\u0004 (אין אני רוצה) לשמש את המטה \u0003אלא\u0004 כשאהיה \u0003אני בבגדי והיא בבגדה\"\u0004 — במקרה כזה \u0003יוציא\u0004 (יגרש את אשתו) \u0003ונותן כתובה,\u0004 וכדברי התנא בברייתא שחובה מן התורה היא להיות בשעת תשמיש בקירוב בשר.","שנינו במשנה ש \u0003ר' יהודה אומר: אפילו עני שבישראל\u0004 לא יפחת בזמן קבורת אשתו משני חלילים ומקוננת. ומדייקים: \u0003מכלל\u0004 הדברים אתה למד כי ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 סתם משנה, \u0003סבר\u0004 כי \u0003הני\u0004 \u0005[אלה]\u0006 \u0003לא\u0004 בכלל חובת הבעל. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]?\u0006 \u0003אי דאורחה\u0004 \u0005[אם ש\u0006כך \u0005דרכה],\u0006 כלומר, כך המנהג במשפחתה לנהוג בזמן קבורה — \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ה\u0003תנא קמא\u0004 ש\u0003אמר\u0004 ש\u0003לא\u0004 צריך לעשות כן? שהרי אם אינו עושה כן הוא מבזה אותה. \u0003ואי דלאו אורחה\u0004 \u0005[ואם שאין\u0006 זה \u0005דרכה] —\u0006 אם כן \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה?\u0004","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 לומר אלא \u0003כגון דאורחיה דידיה ולאו אורחה דידה\u0004 \u0005[ש\u0006זו \u0005דרכו שלו,\u0006 שבמעמדו ובמשפחתו נהוג כך, \u0005ו\u0006אולם \u0005אין\u0006 זה לפי \u0005דרכה שלה],\u0006 שבמקומה או במשפחתה אין הכל עושים כך; ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר: כי אמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 את הכלל שהאשה הנישאת לאיש \u0003עולה עמו\u0004 (עם בעלה) וצריך לנהוג בה לפי מעמדו \u0003ואינה יורדת עמו\u0004 גם אם הוא במעמד נמוך יותר — \u0003הני מילי מחיים\u0004 \u0005[דברים אלה\u0006 אמורים בזמן שהם \u0005חיים],\u0006 \u0003אבל לאחר מיתה\u0004 — \u0003לא\u0004 תיקנו.","\u0003ור' יהודה סבר: אפילו לאחר מיתה\u0004 צריך לנהוג עמה כפי מעמדו, ואם דרך בני משפחתו בחלילים ובמקוננות — חייב גם להביא לה כמו כן בזמן קבורתה. \u0003אמר רב חסדא אמר מר עוקבא: הלכה כר' יהודה.\u0004","אגב הבאת פסק הלכה זה מביאים עוד ממה ש\u0003אמר רב חסדא אמר מר עוקבא: מי שנשתטה\u0004 (נשתגע) — \u0003בית דין יורדין לנכסיו וזנין ומפרנסין את אשתו ובניו ובנותיו, ו\u0004נותנים גם \u0003דבר אחר,\u0004 כפי שיבואר להלן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: מאי שנא מהא דתניא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 דבר זה \u0005ממה ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מי שהלך למדינת הים ואשתו תובעת מזונות\u0004 — \u0003בית דין יורדין לנכסיו, וזנין ומפרנסין את אשתו, אבל לא\u0004 את \u0003בניו ובנותיו ולא\u0004 נותנים לה \u0003דבר אחר,\u0004 שאין חיוב לזונם כשהוא בחיים, ומדוע מי שנשתטה מפרנסים גם את בניו ובנותיו?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ולא שאני לך\u0004 \u0005[ואינו שונה אצלך]\u0006 \u0003בין\u0004 אדם ש\u0003יוצא לדעת\u0004 (מדעתו), \u0003ליוצא שלא לדעת?\u0004 שזה שהשתטה הרי שלא לדעתו עשה כן, ובודאי רוצה הוא לזונם מנכסיו, למרות שאינו חייב, ולכן נותנים למשפחתו את כל צורכה, אבל כשהוא יוצא למדינת הים הוא עושה כן מדעתו, ואנו מניחים שהשאיר לבניו ולבנותיו כדי צורכם, ואם לא הכין להם — גילה דעתו שאינו רוצה לפרנס אותם.","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"דבר אחר\"\u0004 שהוזכר כאן? \u0003רב חסדא אמר: זה תכשיט,\u0004 שנוסף למזונות נותנים לאשה גם צורכי קישוט. \u0003רב יוסף אמר:\u0004 זהו כסף עבור \u0003צדקה.\u0004 ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שלא נותנים לה מנכסיו \u0003תכשיט, כל שכן\u0004 שאין נותנים לצורך \u0003צדקה,\u0004 שאם הלך למדינת הים אין נותנים מנכסיו כסף לצדקה, אבל \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שאין נותנים כסף ל\u0003צדקה\u0004 — \u0003אבל תכשיט יהבינן לה\u0004 \u0005[נותנים לה]\u0006 בכל מקרה, שאנחנו מניחים ש\u0003לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 לבעל \u0003דתינוול\u0004 \u0005[שתתנוול\u0006 אשתו\u0005]\u0006 בהיעדר קישוטים.","\u0003אמר רב חייא בר אבין אמר רב הונא: מי שהלך למדינת הים ומתה אשתו\u0004 — \u0003בית דין יורדין לנכסיו, וקוברין אותה לפי כבודו.\u0004 ושואלים: האם דווקא \u0003לפי כבודו ולא לפי כבודה?\u0004 ואיך לנהוג אם היא היתה מכובדת ממנו?","ומשיבים: \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003אף לפי כבודו,\u0004 שאם היה הוא ממעמד מכובד יותר — קוברים אותה לפי כבודו. ומעירים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו\u0006 בכך\u0005]:\u0006 ש\u0003עולה עמו\u0004 למעמדו \u0003ואינה יורדת עמו, ואפילו לאחר מיתה,\u0004 וכר' יהודה במשנה.","\u0003אמר רב מתנה, האומר: \"אם מתה\u0004 (תמות) אשתו \u0003לא תקברוה מנכסיו\"\u0004 — \u0003שומעין לו.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003כי אמר\u0004 \u0005[כאשר\u0006 הוא \u0005אומר],\u0006 מדוע אנו שומעים לו — שאנו אומרים שכיון שמת, \u0003דנפלי נכסי קמי יתמי\u0004 \u0005[שהנכסים נופלים\u0006 בירושה \u0005לפני היתומים]\u0006 ועליהם אין חובה לקבור אותה, ויורשיה שירשו את כתובתה הם יקברוה. אולם \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא אמר\u0004 דבר זה במפורש \u0003נמי, נכסי קמי יתמי רמו\u0004 \u0005[גם כן,\u0006 הלא \u0005הנכסים לפני היתומים הם מוטלים]\u0006 ושייכים להם, ומה ההבדל אם ציווה או לא ציווה על כך?","\u0003אלא\u0004 כך צריך לתקן ולומר: \u0003האומר: \"אם מת הוא\u0004 (כלומר, האומר על עצמו שאם הוא ימות) \u0003לא תקברוהו מנכסיו\",\u0004 שאינו רוצה שיוציאו הוצאות עליו, אלא יקברוהו מן הצדקה — \u0003אין שומעין לו,\u0004 וקוברים אותו מנכסיו ולא מן הצדקה. ומדוע? — \u0003לאו כל הימנו\u0004 (אין זה בכוחו) \u0003שיעשיר את בניו\u0004 וימנע מהם הוצאה זו, \u0003ויפיל עצמו\u0004 למעמסה \u0003על\u0004 קופת \u0003הציבור.\u0004","\u0003לעולם\u0004 הבת, גם לאחר שנתארסה \u0003היא\u0004 עדיין \u0003ברשות האב\u0004 לכל דבר, \u0003עד שתכנס\u0004"],["\u0003לרשות הבעל לנשואין,\u0004 כלומר, שתיכנס לחופה. \u0003מסר האב\u0004 את בתו \u0003לשלוחי הבעל\u0004 שהם יביאוה אל הבעל לחופה — \u0003הרי היא\u0004 מאז המסירה \u0003ברשות הבעל.\u0004 אולם אם \u0003הלך האב עם שלוחי הבעל, או שהלכו שלוחי האב עם שלוחי הבעל\u0004 — \u0003הרי היא\u0004 עדיין \u0003ברשות האב,\u0004 לפי שלא נמסרה לגמרי לחלוטין לרשות הבעל. אבל אם שלחה האב על ידי שליחים אל הבעל, ו\u0003מסרו שלוחי האב\u0004 את האשה \u0003לשלוחי הבעל\u0004 — \u0003הרי היא\u0004 מאותה שעה \u0003ברשות הבעל.\u0004","שנינו במשנה שלעולם היא ברשות האב עד שתיכנס לגמרי לרשות הבעל. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות ההדגשה ש\u0003לעולם\u0004 היא ברשות אביה? ומסבירים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003משנה ראשונה. דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אם \u0003הגיע זמן\u0004 שקבע הבעל לנישואין \u0003ולא נישאו\u0004 הבנות — הרי הן \u0003אוכלות\u0004 מזונות \u0003משלו\u0004 (משל הבעל) \u0003ואוכלות בתרומה\u0004 אם היה הבעל כהן, משום שמאותו זמן יש להן זכויות כאילו היו נשואות. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 במשנתנו שאין הלכה כשיטת המשנה הראשונה, אלא \u0003לעולם\u0004 הן ברשות האב, עד שייכנסו לחופה ממש.","שנינו במשנה שאם \u0003מסר האב\u0004 את בתו \u0003לשלוחי הבעל\u0004 — \u0003הרי היא ברשות הבעל. אמר רב:\u0004 ב\u0003מסירתה\u0004 היא יוצאת מרשות האב \u0003לכל\u0004 ענין ונחשבת לגמרי ברשות הבעל \u0003חוץ מ\u0004אשר לענין אכילת \u0003תרומה,\u0004 שאם היה הבעל כהן — עדיין אסור לה לאכול בתרומה עד שתיכנס ממש לחופה. \u0003ורב אסי אמר:\u0004 במסירתה היא נחשבת ברשות הבעל \u0003אף לתרומה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב הונא לרב אסי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהקשה זאת \u0003חייא בר\u0004 \u0005[בנו]\u0006 של \u0003רב לרב אסי,\u0004 הרי שנינו: \u0003לעולם היא ברשות האב עד שתכנס לחופה,\u0004 ולדברי רב אסי, הרי משמסרה לשלוחי הבעל לנישואין כבר אינה ברשותו! \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב: לאו אמינא לכו לא תיזלו בתר איפכא\u0004 \u0005[\u0006וכי \u0005לא אמרתי לכם אל תלכו אחר ההיפך]?!\u0006 כלומר, אל תדחו דברים על ידי ראיה ממקור שאין משמעותו ברורה, ואפשר להבינה ולהופכה לכמה צדדים, שהרי \u0003יכול\u0004 רב אסי \u0003לשנויי לכו\u0004 \u0005[לתרץ לכם]\u0006 שכוונת הדברים היא ש\u0003מסירתה\u0004 לשלוחי הבעל \u0003זו היא כניסתה לחופה,\u0004 ודין אחד להם.","\u0003ושמואל אמר\u0004 בשיטה אחרת: מסירתה לשלוחי הבעל מועילה רק \u0003ל\u0004ענין \u0003ירושתה,\u0004 כלומר, שהבעל יורש אותה אם מתה כאילו כבר נכנסה לחופה.","\u0003ריש לקיש אמר:\u0004 מסירתה מועילה \u0003ל\u0004עניין \u0003כתובתה.\u0004 ומבררים, \u0003כתובתה\u0004 שאמר ריש לקיש \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא:\u0004 אם תאמר שהכוונה היא \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003מתה ירית לה\u0004 \u0005[יורש\u0006 הוא \u0005אותה]\u0006 וכתובתה בכלל, אם כן \u0003היינו\u0004 \u0005[הם הם]\u0006 דברי \u0003שמואל\u0004 ואין בכך חידוש! \u0003אמר רבינא:\u0004 ריש לקיש בא \u0003לומר\u0004 ש\u0003כתובתה מאחר מנה,\u0004 שאם מת הבעל אחרי שאשתו נמסרה לשלוחיו, אף לפני שנכנסה ממש לחופה, אין היא נחשבת עוד כאלמנה מן האירוסין, שכתובתה מאתיים, אלא כאלמנה מן הנישואין שכתובתה רק מנה.","ואילו \u0003ר' יוחנן ור' חנינא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מסירתה\u0004 מועילה \u0003לכל\u0004 ענין, \u0003אף לתרומה,\u0004 שאם הבעל כהן, אוכלת מאותה שעה בתרומה.","\u0003מיתיבי\u0004 \u0005[מקשים],\u0006 ממה ששנינו בתוספתא: \u0003הלך האב עם שלוחי הבעל, או שהלכו שלוחי האב עם שלוחי הבעל, או שהיתה לה חצר בדרך ונכנסה עמו\u0004 עם ארוסה \u0003ללין\u0004 (ללון) בלבד, ולא לשם נישואין, אלא רק כדי לחכות בלילה זה עד שיגיעו למקום מגורי הבעל, \u0003אף על פי שכתובתה\u0004 (הנדוניה שלה) כבר \u0003בבית בעלה,\u0004 אם \u0003מתה\u0004 בינתיים — \u0003אביה יורשה,\u0004 שעדיין איננה נחשבת כמסורה לבעל.","אבל אם \u0003מסר האב לשלוחי הבעל, או שמסרו שלוחי האב לשלוחי הבעל, או שהיתה לו חצר בדרך ונכנסה עמו לשום\u0004 (לשם) \u0003נישואין, אף על פי שכתובתה\u0004 עדיין \u0003בבית אביה\u0004 שעוד לא נתן אותה לבעל, אם \u0003מתה\u0004 — \u0003בעלה יורשה.\u0004","\u0003במה דברים אמורים\u0004 — \u0003לירושתה, אבל לתרומה\u0004 אינו כן, ש\u0003אין אשה\u0004 שנישאת לכהן \u0003אוכלת בתרומה עד שתכנס לחופה\u0004 ממש. ואם כן \u0003תיובתא דכולהו\u0004 \u0005[קושיה חמורה של,\u0006 על, \u0005כולם]\u0006 שכן הברייתא הזו היא כנגד כל שיטות האומרים שמסירתה מועילה גם לענין תרומה! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005].\u0006","לעצם דברי הברייתא שואלים: \u0003הא גופא קשיא\u0004 \u0005[זה עצמו קשה]:\u0006 \u0003אמרת\u0004 שאם \u0003נכנסה עמו\u0004 לחצר שלה כדי \u0003ללין\u0004 (ללון) באותו לילה, עדיין היא ברשות אביה. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 שהיה ברור שהם נכנסים רק \u0003ללין\u0004 שם, \u0003הא סתמא\u0004 \u0005[הרי\u0006 אם נכנסה \u0005סתם],\u0006 הרי זה כאילו נכנסה \u0003לשם נישואין. אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005הסוף,\u0006 ההמשך\u0005]:\u0006 \u0003נכנסה עמו\u0004 לחצר שלו \u0003לשם נישואין,\u0004 ונדייק \u0003הא סתמא\u0004 \u0005[הרי\u0006 אם נכנסה \u0005סתם],\u0006 ולא פירשה שכניסתה לשם נישואין, הרי זה כאילו נכנסה \u0003ללין.\u0004 הרי שהדיוקים מן הרישא ומן הסיפא סותרים זה את זה!","\u0003אמר רב אשי:\u0004 אין לדייק כך, אלא \u0003סתמי סתמי קתני\u0004 \u0005[סתמים סתמים שנה]\u0006 וכך צריך להבין: אם נכנסה \u0003סתם\u0004 ל\u0003חצר דידה\u0004 \u0005[שלה]\u0006 — הרי הכוונה שהיא נכנסה \u0003ללין\u0004 בלבד. \u0003סתם\u0004 נכנסה ל\u0003חצר דידיה\u0004 \u0005[שלו] —\u0006 ודאי \u0003לנשואין\u0004 נכנסה, אלא אם כן פירשו שהיתה להם כוונה אחרת.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בברייתא: אם \u0003מסר האב\u0004 את בתו \u0003לשלוחי הבעל וזינתה\u0004 לאחר מכן — \u0003הרי זו\u0004 נידונת \u0003בחנק,\u0004 כדין אשת איש שזינתה, ואינה נידונת בסקילה כארוסה שזינתה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 שמזמן מסירתה לבעל היא נידונת כאשת איש? \u0003אמר ר' אמי בר חמא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לזנות בית אביה\"\u0004 (דברים כב, כא), והרי זה בא לדייק: \u0003פרט לשמסר האב לשלוחי הבעל,\u0004 ששוב אינה בבית אביה.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שבא הדבר להוציא מקרה אחר — \u0003פרט\u0004 לזו \u0003שנכנסה לחופה ו\u0004אף על פי ש\u0003לא נבעלה,\u0004 שהיא נידונת בשריפה כאשת איש, אבל כשמסרה אביה לבעל עדיין נחשבת זנותה בבית אביה ועונשה בסקילה כארוסה ולא כנשואה!","\u0003אמר רבא:\u0004 אל תאמר שבא הדבר לצורך זה, שכן \u0003אמר לי\u0004 החכם \u0003אמי\u0004 והסביר לי כי \u0003חופה בהדיא כתיבא\u0004 \u0005[במפורש נאמרה],\u0006 כלומר, שזו שנכנסת לחופה נחשבת כאשת איש נלמד מן הכתובים לא על דרך הדיוק, אלא כבר ידוע באופן אחר: שנאמר בענין נערה המאורסה שזינתה \u0003\"כי יהיה נער בתולה מארשה לאיש\"\u0004 (דברים כב, כג), וכך משמעות הלשון: \u0003\"נערה\"\u0004 בא להדגיש — \u0003ולא בוגרת, \"בתולה\"\u0004 — \u0003ולא בעולה, \"מארשה\"\u0004 — \u0003ולא נשואה.\u0004","ומעתה נברר מה פירושם של הדברים: \u0003מאי\u0004 \u0005[מה]\u0006 עניינה של \u0003\"נשואה\"\u0004 זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003נשואה\u0004 היא נשואה \u0003ממש\u0004 שנכנסה לחופה ונבעלה כבר, אם כן \u0003היינו\u0004 \u0005[הרי היא]\u0006 מה שכבר אמרנו \u0003\"בתולה\" ולא בעולה! אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה במה שאמרו \"נשואה\" כוונתו \u0003שנכנסה לחופה ולא נבעלה,\u0004 שאם זינתה מיתתה בחנק, כבעולה."],["\u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003היכא דהדרא לבי נשא הדרא למילתא קמייתא\u0004 \u0005[כאשר\u0006 היא \u0005חוזרת לבית אביה,\u0006 כשנתאלמנה או נתגרשה, היא \u0005חוזרת לדבר,\u0006 למצבה, \u0005הקודם]\u0006 ונחשבת כאילו לא יצאה כלל מרשות האב? \u0003אמר רבא: ההוא כבר\u0004 \u0005[\u0006את ההנחה \u0005הזו]\u0006 \u0003פסקה\u0004 \u0005[פסק,\u0006 פתר\u0005]\u0006 \u0003תנא דבי\u0004 \u0005[התנא מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004","\u0003דתנא דבי\u0004 \u0005[ששנה התנא מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 זה שנאמר \u0003\"ונדר אלמנה וגרושה כל אשר אסרה על נפשה יקום עליה\"\u0004 (במדבר ל, י), \u0003מה תלמוד לומר?\u0004 הרי אין חידוש בדבר; \u0003והלא\u0004 לאחר שנתאלמנה או נתגרשה היא כבר \u0003מוצאת מכלל\u0004 רשות ה\u0003אב ומוצאת מכלל\u0004 רשות ה\u0003בעל,\u0004 ואין מי שימנע בעדה מלקיים את נדרה!","\u0003אלא, הרי שמסר האב לשלוחי הבעל, או שמסרו שלוחי האב לשלוחי הבעל, ונתארמלה\u0004 (נתאלמנה) \u0003בדרך או נתגרשה,\u0004 בזו \u0003היאך\u0004 (איך) \u0003אני קורא בה: בית אביה של זו או בית בעלה של זו?\u0004 שהרי אין מצבה ברור כלל ומי הוא זה הראוי להפר נדריה? \u0003אלא\u0004 בא הכתוב \u0003לומר לך: כיון שיצאה שעה אחת מרשות האב\u0004 — \u0003שוב\u0004 אביה \u0003אינו יכול להפר,\u0004 ודינה כאלמנה או גרושה לכל דבר, וכן גם לענייננו, אפילו אם חזרה לבית אביה, נשאר דינה כנשואה.","\u0003אמר רב פפא: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כעין זה, שהנמסרת לשלוחי הבעל דינה כנשואה: \u0003הבא על נערה המאורסה\u0004 — \u0003אינו חייב עד שתהא נערה בתולה מאורסה והיא בבית אביה.\u0004 ונברר מה משמעות הדברים לפרטיהם: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003\"נערה\",\u0004 בא להוציא — \u0003ולא בוגרת, \"בתולה\"\u0004 — \u0003ולא בעולה, \"מאורסה\"\u0004 — \u0003ולא נשואה.\u0004 אולם \u0003בבית אביה למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה],\u0006 \u0003לאו למעוטי\u0004 \u0005[\u0006האם \u0005לא למעט]\u0006 את אותו מקרה שבו \u0003מסר האב לשלוחי הבעל\u0004 שדינה כנשואה? מתברר איפוא שגם בברייתא נרמזה הלכה זו.","\u0003אמר רב נחמן בר יצחק: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]:\u0006 \u0003הבא על אשת איש, כיון שנכנסה לרשות הבעל לנשואין, אף על פי שלא נבעלה — הבא עליה הרי זה בחנק\u0004 כדין נשואה ולא כדין ארוסה. משמע: \u0003נכנסה לרשות הבעל בעלמא\u0004 \u0005[בלבד]\u0006 גם אם לא נכנסה לחופה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003האב אינו חייב במזונות בתו\u0004 בחייו. \u0003זה מדרש דרש ר' אלעזר בן עזריה לפני חכמים בכרם ביבנה:\u0004 כיון שתיקנו חכמים שלאחר מות האב \u0003הבנים יירשו\u0004 את כתובת אמם \u0003והבנות יזונו\u0004 מנכסיו, יש להשוות את השניים: \u0003מה הבנים אינן יורשין אלא לאחר מיתת האב\u0004 ולא בחייו — \u0003אף הבנות אין ניזונות\u0004 מרכושו \u0003אלא לאחר מיתת אביהן.\u0004","שנינו במשנה שאין האב חייב במזונות בתו. ומדייקים: \u0003במזונות בתו הוא\u0004 ש\u0003אינו חייב, הא\u0004 \u0005[הרי]\u0006 משמע כי \u0003במזונות בנו — חייב.\u0004 ועוד: \u0003בתו נמי\u0004 \u0005[גם כן],\u0006 \u0003חובה הוא דליכא\u0004 \u0005[שאין\u0006 כאן\u0005],\u0006 כלומר, שאי אפשר לחייבו מן הדין לפרנס את בתו, אך ודאי \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מצוה איכא\u0004 \u0005[יש\u0006 בכך\u0005].\u0006 ולפי הבנה זו \u0003מני מתניתין\u0004 \u0005[\u0006של \u0005מי היא משנתנו]?\u0006 שהרי אינה \u0003לא\u0004 כדעת \u0003ר' מאיר, לא\u0004 כדעת \u0003ר' יהודה, ולא\u0004 כדעת \u0003ר' יוחנן בן ברוקא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצוה לזון את הבנות, קל וחומר לבנים.\u0004 ומדוע קל וחומר — משום \u0003דעסקי\u0004 \u0005[ש\u0006הם \u0005עוסקים]\u0006 \u0003בתורה,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: מצוה לזון את הבנים, וקל וחומר לבנות, משום\u0004 החשש ל\u0003זילותא\u0004 \u0005[זלזול\u0006 בהן\u0005]\u0006 אם תצטרכנה לחזר על הפתחים. \u0003ר' יוחנן בן ברוקא אומר: חובה לזון את הבנות לאחר מיתת אביהן, אבל בחיי אביהן — אלו ואלו,\u0004 הבנים והבנות, \u0003אינן ניזונין.\u0004","ואם כן \u0003מני מתניתין\u0004 \u0005[כמי היא משנתנו]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהיא כשיטת \u0003ר' מאיר — הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 שגם לזון את ה\u0003בנים מצוה\u0004 היא ולא חובה?! \u0003אי\u0004 \u0005[אם\u0006 שיטת\u0005]\u0006 \u0003ר' יהודה — הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 שלזון את ה\u0003בנים נמי\u0004 \u0005[גם כן]\u0006 \u0003מצוה\u0004 היא ולא חובה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003ר' יוחנן בן ברוקא\u0004 — הרי לשיטתו נראה ש\u0003אפילו מצוה נמי ליכא\u0004 \u0005[גם כן אין]\u0006 בכך אפילו בבנות! — ואין איפוא שיטה המתאימה לדעת משנתינו.","ומשיבים: אפשר ליישב את שיטת המשנה בדרכים שונות, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמשנתנו כשיטת \u0003ר' מאיר, איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 משנתנו כשיטת \u0003ר' יהודה, איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 משנתנו כשיטת \u0003ר' יוחנן בן ברוקא.\u0004","ומבארים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שכשיטת \u0003ר' מאיר\u0004 האומר כי מצוה לזון את הבנות וקל וחומר לבנים היא, \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך צריך להבין את משנתנו: \u0003האב אינו חייב במזונות בתו, ו\u0004באמת \u0003הוא הדין לבנו. הא\u0004 \u0005[הרי]\u0006 \u0003מצוה בבתו איכא\u0004 \u0005[יש],\u0006 \u0003קל וחומר לבנים\u0004 שיש בהם מצוה. \u0003והאי דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003בתו\u0004 \u0005[בתו]\u0006 בלבד ולא אמר בתו ובנו — אין לדייק מכאן שחייב במזונות בנו, אלא \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006"],["ש\u0003אפילו בתו, חובה הוא דליכא\u0004 \u0005[שאין]\u0006 בכך, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מצוה איכא\u0004 \u0005[יש\u0006 בדבר\u0005].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי משנתנו כשיטת \u0003ר' יהודה\u0004 האומר כי מצוה לזון את הבנים וקל וחומר לבנות היא, \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך צריך להבין את לשון המשנה: \u0003האב אינו חייב במזונות בתו — וכל שכן\u0004 שאינו חייב לתת \u0003לבנו\u0004 מזונות, \u0003הא\u0004 \u0005[הרי]\u0006 אבל \u0003מצוה בבנו איכא\u0004 \u0005[יש]\u0006 אף על פי שאין חובה, \u0003וקל וחומר לבנות. והא דקתני\u0004 \u0005[וזה ששנה]\u0006 \u0003בתו\u0004 דווקא — \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003אפילו\u0004 לזון את \u0003בתו חובה ליכא\u0004 \u0005[אין]\u0006 בכך, למרות שלדעתו ברור שיש בכך מצוה כדי שלא יזלזלו בה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כי משנתנו היא כדעת \u0003ר' יוחנן בן ברוקא\u0004 האומר כי חובה לזון את הבנות לאחר מיתת אביהן אבל בחייו אין ניזונים ממנו לא בניו ולא בנותיו, \u0003והכי קאמר\u0004 \u0005[וכך אמר],\u0006 כך יש להבין אותה: \u0003אינו חייב במזונות בתו והוא הדין\u0004 שאינו חייב במזונות אף \u0003לבנו, והוא הדין\u0004 ש\u0003אפילו מצוה נמי ליכא\u0004 \u0005[גם כן אין]\u0006 לא בבנו ולא בבתו, \u0003ואיידי\u0004 \u0005[ועל ידי,\u0006 מכיון\u0005]\u0006 שצריך היה לומר לבסוף ש\u0003בנות לאחר מיתת אביהן חובה\u0004 לזון אותן מן הנכסים, \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 לשם הקבלה \u0003אינו חייב\u0004 במזונות בתו בחייו. ואין ללמוד מכאן שאף שאינו חייב יש בכך מצוה, אלא יש להבין שבחייו אין כל התחייבות, ואף לא משום מצוה.","\u0003אמר ר' אילעא אמר ריש לקיש משום\u0004 (בשם) \u0003ר' יהודה בר חנינא: ב\u0004עיר \u0003אושא התקינו\u0004 חכמים, \u0003שיהא אדם זן את בניו ואת בנותיו כשהן קטנים. איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 האם \u0003הלכתא כוותיה\u0004 \u0005[הלכה כמותו]\u0006 \u0003או אין הלכתא כוותיה\u0004 \u0005[הלכה כמותו],\u0006 כלומר, האם כך פוסקים למעשה שחייב אדם לזון את ילדיו הקטנים? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לכך מן העובדות הללו: \u0003כי הוה אתו לקמיה\u0004 \u0005[כאשר היו באים לפני]\u0006 \u0003רב יהודה\u0004 להתלונן על אב שאינו מפרנס את ילדיו, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003יארוד ילדה ואבני מתא שדיא\u0004 \u0005[התנין יולד\u0006 וולדות \u0005ועל בני העיר\u0006 הוא \u0005מטיל]\u0006 את חובת פרנסתם?! אלא ודאי מן הראוי שהוא יפרנסם.","\u0003כי הוה אתו לקמיה\u0004 \u0005[כאשר היו באים לפני]\u0006 \u0003רב חסדא\u0004 בתביעה כגון זו, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כפו ליה אסיתא בצבורא\u0004 \u0005[הפכו לו מכתשת בציבור]\u0006 שיהיה לו מקום מוגבה לעמוד עליו, \u0003וליקום ולימא\u0004 \u0005[ושיקום\u0006 אותו אב \u0005ויאמר]:\u0006 \u0003עורבא בעי בניה וההוא גברא לא בעי בניה\u0004 \u0005[העורב רוצה\u0006 ודואג ל\u0005בניו, והאיש הזה,\u0006 אני, \u0005איננו רוצה את בניו]\u0006?! כלומר, עליו להצהיר ברבים שהוא רע מן העורבים. לגופה של מימרה זו שואלים: \u0003ועורבא בעי בניה\u0004 \u0005[ו\u0006האם \u0005העורב רוצה\u0006 לפרנס \u0005את בניו]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"\u0004נותן לבהמה לחמה \u0003לבני ערב אשר יקראו\"\u0004 (תהלים קמז, ט), משמע שהוריהם אינם מפרנסים אותם והם ניזונים רק בחסדי ה'! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שהעורב אינו חס על בניו לתת להם מזונם, הרי זה דווקא \u0003בחיורי\u0004 \u0005[בלבנים],\u0006 כלומר כל עוד בניהם צעירים ופלומתם עדיין לבנה, שאז הם שונאים אותם ומתאכזרים אליהם, ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שהם חסים על בניהם ונותנים להם מזונם, הרי זה \u0003באוכמי\u0004 \u0005[בשחורים],\u0006 שלאחר שגדלו ופלומתם שחורה כשל הוריהם, אוהבים הם אותם ודואגים למזונם.","\u0003כי הוה אתי לקמיה\u0004 \u0005[כאשר היה בא\u0006 מעשה כזה \u0005לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[היה אומר לו]\u0006 לאב: \u0003ניחא\u0004 \u0005[\u0006האם \u0005נוח]\u0006 \u0003לך דמיתזני\u0004 \u0005[שיתפרנסו]\u0006 \u0003בניך מצדקה?\u0004 ומכל העובדות הללו מוכח שאין הלכה כתקנת אושא, שהרי חכמים אלה לא כפו ממש את האב לפרנס את בניו.","ומעירים: \u0003ו\u0004כל זה \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שאין כופים את האב לזון את בניו ובנותיו, \u0003אלא דלא אמיד\u0004 \u0005[שאינו עשיר]\u0006 וצריך להתייגע הרבה כדי לפרנס את ילדיו, \u0003אבל\u0004 אם הוא \u0003אמיד\u0004 \u0005[עשיר] —\u0006 \u0003כפינן ליה על כרחיה\u0004 \u0005[כופים אנו אותו בעל כורחו]\u0006 שיפרנס את בניו. \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003רבא כפייה\u0004 \u0005[כפאו]\u0006 את \u0003רב נתן בר אמי\u0004 שהיה עשיר \u0003ואפיק מיניה\u0004 \u0005[והוציא ממנו]\u0006 \u0003ארבע מאה זוזי\u0004 \u0005[מאות זוז]\u0006 \u0003לצדקה, ו\u0004מכאן שאף בדבר שאין בו חובה מסויימת, מכל מקום אדם אמיד שיכול להרשות לעצמו, כופים אותו בית הדין שיתן, וכל שכן שכופים אותו לפרנס את ילדיו.","\u0003אמר ר' אילעא אמר ריש לקיש: ב\u0004עיר \u0003אושא התקינו\u0004 תקנה נוספת: \u0003הכותב כל נכסיו לבניו,\u0004 כלומר, שנותן להם בחייו במתנה את כל נכסיו — \u0003הוא ואשתו נזונים מהם\u0004 בחייהם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהקשה זאת \u0003ר' שמואל בר נחמני:\u0004 מה החידוש שבקביעה זו? הרי \u0003גדולה מזו אמרו,\u0004 ש\u0003אלמנתו\u0004 של אדם \u0003נזונת מנכסיו\u0004 גם אם ירשה אותם בתו הנשואה, ולמרות שבעלה זכה בהם ואין אלמנה ניזונית מנכסים המשועבדים לאחר, בכל זאת כאן כדי שלא תפסיד האלמנה לגמרי תיקנו חכמים שתיזון מהם, ואם כן \u0003הוא ואשתו\u0004 בחייו \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שמתפרנסים מן הנכסים שנתנו במתנה לבניהם?!","ומהי הלכה זו שהוא מצטט — ש\u0003שלח רבין באיגרתיה\u0004 \u0005[במכתבו\u0006 לבבל\u0005]\u0006 הלכות אלה: \u0003מי שמת והניח אלמנה ובת\u0004 היורשות את נכסיו — \u0003אלמנתו ניזונת מנכסיו,\u0004 שהרי זה הוא מתנאי הכתובה. \u0003נישאת הבת\u0004 ומה שירשה הם נכסי מלוג שפירותיהם לבעלה — גם אז \u0003אלמנתו ניזונת מנכסיו.\u0004","ומה הדין אם \u0003מתה הבת\u0004 ובעלה יורשה? \u0003אמר ר' יהודה בן אחותו של ר' יוסי בר חנינא: על ידי\u0004 (אצלי) \u0003היה מעשה\u0004 שהובאה שאלה זו לדיון לפני חכמים, \u0003ואמרו:\u0004 גם אז \u0003אלמנתו ניזונת מנכסיו.\u0004 שגם במקרה שעברו הנכסים בירושה לבעל אנו אומרים שאין זה מפקיע את זכות האלמנה בנכסים, ואם כן \u0003הוא ואשתו מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?!\u0006","ודוחים: אין זו קושיה, כי יש מקום להבדיל, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 באלמנה תיקנו דין זה, לפי \u0003דליכא דטרח\u0004 \u0005[שאין\u0006 מי \u0005שיטרח]\u0006 עבור האשה, שהרי נשארה אלמנה לבדה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 כאשר הוא חי — \u0003נטרח לדידיה ולדידה\u0004 \u0005[\u0006ש\u0005יטרח בשבילו ובשבילה]\u0006 ויפרנס את אשתו מעבודתו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין מכריחים אותו לעשות כן, והוא ניזון מן הנכסים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 האם \u0003הלכתא כוותיה\u0004 \u0005[הלכה כמותו]\u0006 \u0003או לית הלכתא כוותיה\u0004 \u0005[אין הלכה כמותו]?\u0006 האם נוהגים כדברי ר' אילעא או לא? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לכך מעובדה זו: ש\u0003ר' חנינא ור' יונתן הוו קיימי\u0004 \u0005[היו עומדים]\u0006 יחד, \u0003אתא ההוא גברא גחין ונשקיה\u0004 \u0005[בא איש אחד התכופף ונישקו]\u0006 את \u0003ר' יונתן אכרעיה\u0004 \u0005[על רגלו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חנינא: מאי האי\u0004 \u0005[מה זה]\u0006 למה הוא מכיר לך טובה כל כך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אותו אדם \u0003כותב נכסיו לבניו הוא,\u0004 שנתן להם את נכסיו במתנה בחייו,"]]};
